INSERT INTO `courses` (`id`, `name`, `short_name`, `description`, `active`, `created_at`, `updated_at`) VALUES
(1, 'ceneval exani 1 math', 'ceneval exani 1 math', 'In this course we will explore the blah blah of blah. The foreignIdFor method adds a {column}_id equivalent column for a given model class. The column type will be UNSIGNED BIGINT, CHAR(36), or CHAR(26) depending on the model key type abcdef...', 0, NULL, '2025-08-03 00:41:07'),
(2, 'ceneval exani 2 math', 'ceneval exani 2 math', 'In this course we will explore the blah blah of blah. Also there will be donuts. uidado con los estafadores que se hacen pasar por Indeed. El uso de Indeed es gratuito para los candidatos. Nunca debes aceptar enviar pagos a una posible empresa o tercero que asegure estar representando a Indeed. Si crees que puedes haber sido víctima de una estafa...', 0, NULL, '2025-08-03 00:41:07'),
(3, 'english', 'english', 'In this course we will explore the blah blah of blah. Also there will be donuts. And cute girls. A safe way is to duplicate the column. i.e. rename the old one, create a new one with the original\'s name, make it unique AND nullable, then write a method to copy the data from the old column into the new column. But your method should only keep the first occurrence of a value, and leave the subsequent occurrences as NULL.', 0, NULL, '2025-08-03 00:41:07'),
(4, 'Precalculus', 'Precalculus', 'From Algebra One through everything you\'ll need to get started in, and succeed with, Calculus.', 0, '2025-04-11 21:38:46', '2025-08-06 12:08:10'),
(5, 'Estadística', 'Estadística', 'tbi', 1, '2025-04-14 15:17:45', '2025-08-03 00:41:07'),
(10, 'Pensamiento Matemático 1', 'Pensamiento Matemático 1', 'TBI', 1, '2025-05-21 15:55:23', '2025-08-03 00:41:07'),
(11, 'Cálculo Diferencial', 'Cálculo Diferencial', 'tbi', 1, '2025-04-14 15:17:45', '2025-08-03 00:41:07'),
(12, 'Pensamiento Matemático 3', 'Pensamiento Matemático 3', 'Similar a Cálculo diferencial con un nivel más accesible.', 1, '2025-05-21 15:55:23', '2025-08-03 00:41:07'),
