INSERT INTO `lessons` (`id`, `name`, `short_name`, `lesson_set_id`, `sequence_id`, `active`, `is_premium`, `lesson_text`, `lesson_type`, `lesson_page`, `created_at`, `updated_at`) VALUES
(1, 'easy addition', 'easy addition', 1, 0, 1, 0, 'just add', 'text', '', NULL, '2025-08-03 00:40:28'),
(2, 'not-so-easy addition', 'not-so-easy addition', 1, 0, 1, 0, 'We elected a man everyone who matters in this country knew was an idiot. The bulk of them refused to say so openly and directly — either because they thought he could do something for them or because there are political and journalistic norms against speaking that way.', 'text', '', NULL, '2025-08-03 00:40:28'),
(3, 'easy subtraction', 'easy subtraction', 2, 0, 1, 0, 'Chief Justice Roberts has issued an administrative stay in the Abrego Garcia case, temporarily relieving the <span class=\"text-green-600\">Trump</span> administration of its duty to return him from El Salvador.', 'text', '', NULL, '2025-08-03 00:40:28'),
(4, 'not-so-easy subtraction', 'not-so-easy subtraction', 2, 0, 1, 0, 'Unrest continues at Mount Spurr volcano. Seismicity remains elevated with occasional small, shallow volcanic earthquakes detected beneath the volcano over the past day. No significant activity detected in satellite data or web camera data.', 'text', '', NULL, '2025-08-03 00:40:28'),
(5, 'intro to order of ops', 'intro to order of ops', 3, 0, 1, 0, 'PEMDAS', 'text', '', NULL, '2025-08-03 00:40:28'),
(6, 'image test', 'image test', 1, 100, 1, 0, 'Bowser is such a nice dog:<div className=\"py-10 mx-auto\"><img src=\"/storage/dog.jpg\"  alt=\"Dog Image\" /></div>', 'text', '', NULL, '2025-08-03 00:40:28'),
(7, 'test latex lesson type', 'test latex lesson type', 1, 0, 1, 0, 'Let\'s solve for x: $$ \\frac{1}{2}x = 1 $$ To do this, we must get $ x $ by itself. Recall, we can multiply both sides of an equation by a number, and the results will be equal. In this case, one side is $ \\frac{1}{2}x $. If we multiply that by $2$, we sould have $ x $ by itself. So we have $$ \\frac{1}{2}x = 1 $$ $$ 2 \\times \\frac{1}{2}x = 2 \\times 1 $$ $$ x = 2 $$', 'latex', '', NULL, '2025-08-03 00:40:28'),
(8, 'test pdf type', 'test pdf type', 1, 50, 1, 0, '', 'pdf', '4/pdf/stfhlthfrm', NULL, '2025-08-03 00:40:28'),
(9, 'ltx', 'ltx', 1, 51, 1, 0, '\ndocumentclass[12pt]{article}\nusepackage{amsmath}\nusepackage{geometry}\ngeometry{margin=1in}\n	itle{Algebra One Review -- Multiple Choice Questions}\ndate{}\negin{document}\n\nmaketitle\n\nsection*{1. Operations with Real Numbers}\n\negin{enumerate}\nitem What is the value of: ( 3 - 5 	imes 2 + 6 div 3 )\negin{itemize}\n    item[(A)] -5 hfill 	extbf{(Correct)}\n    item[(B)] -7\n    item[(C)] -4\n    item[(D)] 2\nend{itemize}\n\nend{document}\n', 'latex', '', '2025-04-11 21:31:40', '2025-08-03 00:40:28'),
(10, 'Operations with Real Numbers', 'Operations with Real Numbers', 4, 0, 1, 0, '<div class=\"bg-white p-2 rounded-sm shadow mb-2\"><h2>1. Number Systems</h2><p>There are different types of numbers, and we use them for different purposes:</p><ul><li><strong>Whole Numbers:</strong> 0, 1, 2, 3, 4... (no fractions or negatives)</li><li><strong>Integers:</strong> ... -3, -2, -1, 0, 1, 2, 3 ... (includes negatives)</li><li><strong>Rational Numbers:</strong> Numbers that can be written as a fraction like 1/2, 3/4, or even 5 (because 5 = 5/1)</li><li><strong>Irrational Numbers:</strong> Numbers that can\'t be written as a simple fraction, like π (pi) or √2</li><li><strong>Real Numbers:</strong> All rational and irrational numbers</li></ul></div><div class=\"bg-white p-2 rounded-sm shadow mb-2\"><h2>2. Absolute Value</h2><p>Absolute value means how far a number is from 0 on the number line. It is always positive!</p><p><strong>Examples:</strong></p><ul><li>|5| = 5</li><li>|-3| = 3</li><li>|0| = 0</li></ul></div><div class=\"bg-white p-2 rounded-sm shadow mb-2\"><h2>3. Order of Operations</h2><p>When solving math expressions, we follow a specific order. You might have heard of <strong>PEMDAS</strong>:</p><ul><li><strong>P</strong> - Parentheses</li><li><strong>E</strong> - Exponents</li><li><strong>MD</strong> - Multiplication and Division (left to right)</li><li><strong>AS</strong> - Addition and Subtraction (left to right)</li></ul><p><strong>Example:</strong> <br />Solve: 3 + 6 × (5 + 4) ÷ 3 - 7<br />Step 1: Parentheses → 3 + 6 × 9 ÷ 3 - 7<br />Step 2: Multiply/Divide → 3 + 54 ÷ 3 - 7 → 3 + 18 - 7<br />Step 3: Add/Subtract → 14</p></div><div class=\"bg-white p-2 rounded-sm shadow mb-2\"><h2>4. Subtraction is just adding the opposite</h2><p>You never need to subtract -- just add the opposite. The opposite of 4 is -4, so 13 - 4 we can think of as 13 + (-4). That might not seemeasier, but it can be. The opposite of -17 is 17, so 100 - (-17) = 100 + 17.</p><p><strong>Examples:</strong></p><ul><li>The opposite of 5 - x is -5 + x, so 2x - 3 - (5 - x) = 2x + -3 + -5 + x = 3x + -8</li><li>4 - 2a - 3(2a - 7) = 4 + -2a - (6a - 21) = 4 + -2a + (-6a + 21) = 4 + -2a + -6a + 21 = 25 + -8a</li></ul></div>', 'text', '', '2025-04-11 21:53:33', '2025-08-03 00:40:28'),
(11, 'Solving Linear Equations and Inequalities', 'Solving Linear Equations and I', 4, 0, 1, 0, '<h1>Solving Linear Equations and Inequalities</h1><div class=\"bg-white p-2 rounded-sm shadow mb-2\"><h2>1. What Is a Linear Equation?</h2><p>A linear equation is an equation where the highest power of the variable (usually x) is 1. These equations look like this:</p><p><strong>Examples:</strong> <br />x + 3 = 7 <br />2x - 4 = 10</p></div><div class=\"bg-white p-2 rounded-sm shadow mb-2\"><h2>2. Solving Simple Linear Equations</h2><p>The goal is to get the variable (like x) alone on one side of the equation. Let\'s go step by step:</p><div class=\"bg-slate-100 border-l2 border-black p-1 mb-1\"><strong>Example:</strong> Solve x + 5 = 12<br />Step 1: Subtract 5 from both sides → x + 5 - 5 = 12 - 5<br />Step 2: x = 7</div><div class=\"bg-slate-100 border-l2 border-black p-1 mb-1\"><strong>Example:</strong> Solve 3x = 15<br />Step 1: Divide both sides by 3 → x = 15 ÷ 3<br />Step 2: x = 5</div></div><div class=\"bg-white p-2 rounded-sm shadow mb-2\"><h2>3. Solving More Complicated Equations</h2><p>Sometimes you’ll need to do more than one step, like using the distributive property or combining like terms.</p><div class=\"bg-slate-100 border-l2 border-black p-1 mb-1\"><strong>Example:</strong> Solve 2(x + 3) = 10<br />Step 1: Distribute → 2x + 6 = 10<br />Step 2: Subtract 6 from both sides → 2x = 4<br />Step 3: Divide by 2 → x = 2</div><div class=\"bg-slate-100 border-l2 border-black p-1 mb-1\"><strong>Example:</strong> Solve 3x - 4 = 2x + 1<br />Step 1: Subtract 2x from both sides → x - 4 = 1<br />Step 2: Add 4 to both sides → x = 5</div></div><div class=\"bg-white p-2 rounded-sm shadow mb-2\"><h2>4. What Is an Inequality?</h2><p>Inequalities are like equations, but instead of \"=\", they use these symbols:</p><ul><li><strong>&lt;</strong> less than</li><li><strong>&gt;</strong> greater than</li><li><strong>&le;</strong> less than or equal to</li><li><strong>&ge;</strong> greater than or equal to</li></ul></div><div class=\"bg-white p-2 rounded-sm shadow mb-2\"><h2>5. Solving Inequalities</h2><p>Solving inequalities works just like solving equations—until you multiply or divide by a negative number. Then you must flip the inequalitysign!</p><div class=\"bg-slate-100 border-l2 border-black p-1 mb-1\"><strong>Example:</strong> Solve x + 4 &lt; 10<br />Step 1: Subtract 4 → x &lt; 6</div><div class=\"bg-slate-100 border-l2 border-black p-1 mb-1\"><strong>Example:</strong> Solve -2x &gt; 8<br />Step 1: Divide both sides by -2 (flip the sign!) → x &lt; -4</div><div class=\"bg-slate-100 border-l2 border-black p-1 mb-1\"><strong>Example:</strong> Solve 4x - 2(x + 1) &lt; 3(x + 3)<br />Step 1: Simplify both sides → 4x + -2x + -2 &lt; 3x + 9<br />Step 2: Simplify further → 2x + -2 &lt; 3x + 9<br />Step 3: Subtract 3x from both sides → -x + -2 &lt; 9<br />Step 3: Add 2 to both sides → -x &lt; 11<br />Step 4: Divide both sides by -1 → x &gt; -11<br /></div></div>', 'text', '', '2025-04-11 21:53:33', '2025-08-03 00:40:28'),
(12, 'Graphing Linear Equations and Functions', 'Graphing Linear Equations and ', 4, 0, 1, 0, 'Linear functions are typically written in slope-intercept form: $ y = mx + b $, where $ m $ is the slope and $ b $ is the y-intercept. The slope describes the steepness of the line and is calculated as the change in $ y $ over the change in $ x $. To graph a line, start at the y-intercept and use the slope to find another point. Plotting several points helps ensure accuracy. Graphing allows visualization of solutions and relationships.', 'latex', '', '2025-04-11 21:53:33', '2025-08-03 00:40:28'),
(13, 'Systems of Linear Equations and Inequalities', 'Systems of Linear Equations an', 4, 0, 1, 0, 'A system of equations consists of two or more equations with the same variables. Solutions to these systems are the set of values that satisfy all equations. Methods of solving include graphing, substitution, and elimination. Systems can have one solution (intersecting lines), no solution (parallel lines), or infinitely many solutions (same line). Systems of inequalities use shading to represent all possible solutions on the coordinate plane.', 'pdf', '4/pdf/systems', '2025-04-11 21:53:33', '2025-08-03 00:40:28'),
(14, 'Laws of Exponents', 'Laws of Exponents', 4, 0, 1, 0, '[HHH]Exponents are a way to show repeated multiplication. For example, [LLL]$$3^4 = 3 \\times 3 \\times 3 \\times 3 = 81$$. [HHH]The number 3 is called the base, and 4 is the exponent. Understanding the laws of exponents helps simplify expressions and solve equations more easily. Let\'s go over the most important rules, with step-by-step examples.<div class=\"font-bold my-1 text-lg\">Exponent Laws and Examples</div><div class=\"font-bold my-1\">1. Product of Powers Rule</div>[LLL]$$a^m \\cdot a^n = a^{m+n}$$Example 1:$$2^3 \\cdot 2^4 = 2^{3+4} = 2^7 = 128$$Example 2:$$x^2 \\cdot x^5 = x^{2+5} = x^7$$[HHH]<div class=\"font-bold my-1\">2. Quotient of Powers Rule</div>[LLL]$$\\frac{a^m}{a^n} = a^{m-n}$$Example 3:$$\\frac{5^6}{5^2} = 5^{6-2} = 5^4 = 625$$Example 4:$$\\frac{y^8}{y^3} = y^{8-3} = y^5$$[HHH]<div class=\"font-bold my-1\">3. Power of a Power Rule</div>[LLL]$$(a^m)^n = a^{mn}$$Example 5:$$(3^2)^4 = 3^{2 \\times 4} = 3^8 = 6561$$Example 6:$$(x^3)^2 = x^{3 \\cdot 2} = x^6$$[HHH]<div class=\"font-bold my-1\">4. Power of a Product Rule</div>[LLL]$$(ab)^n = a^n \\cdot b^n$$Example 7:$$(2x)^3 = 2^3 \\cdot x^3 = 8x^3$$[HHH]<div class=\"font-bold my-1\">5. Power of a Quotient Rule</div>[LLL]$$\\left(\\frac{a}{b}\\right)^n = \\frac{a^n}{b^n}$$Example 8:$$\\left(\\frac{3}{4}\\right)^2 = \\frac{3^2}{4^2} = \\frac{9}{16}$$[HHH]<div class=\"font-bold my-1\">6. Zero Exponent Rule</div>[LLL]$$a^0 = 1 (a \\neq 0)$$Example 9:$$7^0 = 1$$$$x^0 = 1$$[HHH]<div class=\"\">Why does this make sense? Let´s use the Product of Powers Rule to calculate it:</div>[LLL]$$x^0 \\cdot x^a = x^{0+a} = x^a$$Since multiplying by $x^0$ leaves $x^a$ unchanged, it follows that it is equal to 1 [HHH]<div class=\"font-bold my-1\">7. Negative Exponent Rule</div>[LLL]$$a^{-n} = \\frac{1}{a^n}$$Example 10:$$2^{-3} = \\frac{1}{2^3} = \\frac{1}{8}$$', 'hybrid', '', '2025-04-11 21:53:33', '2025-08-03 00:40:28'),
(15, 'Polynomials: Operations and Factoring', 'Polynomials: Operations and Fa', 4, 0, 1, 0, 'Polynomials are expressions that consist of variables and coefficients, using operations of addition, subtraction, and multiplication. Terms are separated by plus or minus signs. Operations include combining like terms and using distributive property. Factoring is the reverse of multiplication and is used to simplify or solve polynomial equations. Common techniques include factoring out the greatest common factor, difference of squares, and trinomial factoring.', 'pdf', '4/pdf/polynomials', '2025-04-11 21:53:33', '2025-08-03 00:40:28'),
(16, 'Rational Expressions and Equations', 'Rational Expressions and Equat', 4, 10, 1, 0, 'Rational expressions are fractions where the numerator and/or denominator are polynomials. To simplify, factor both numerator and denominator and cancel common factors. When adding or subtracting, find a common denominator. Equations involving rational expressions may require multiplying both sides by the least common denominator to eliminate fractions. Always check for values that make any denominator zero, as they are excluded from the solution set.', 'pdf', '4/pdf/rational', '2025-04-11 21:53:33', '2025-08-03 00:40:28'),
(17, 'Radical Expressions and Equations', 'Radical Expressions and Equati', 4, 6, 1, 0, 'Radical expressions involve roots, such as square roots or cube roots. The principal square root of a number $ x $ is written $ \\sqrt{x} $. Simplifying radicals often involves factoring the number and simplifying using perfect squares. Equations with radicals require isolating the radical and then squaring both sides, taking care to check for extraneous solutions caused by squaring. Radicals can also be expressed using rational exponents.', 'pdf', '4/pdf/radical', '2025-04-11 21:53:33', '2025-08-03 00:40:28'),
(18, 'Quadratic Equations and Functions', 'Quadratic Equations and Functi', 4, 4, 1, 0, '[HHH]<p>Quadratic equations have the standard form [LLL]$ ax^2 + bx + c = 0 $. [HHH]They can be solved using factoring, completing the square, or the quadratic formula.</p><br /><h2><strong>1. Solving by Factoring</strong></h2><p>Remember factoring? Basically we rewrite something like </p>[LLL]$ ax^2 + bx + c $ in the form $(x + q)(x + p)$[HHH]<p>Don\'t let the variable names bother you -- x is the only variable above; the others just represent numbers</p><p><strong>Example:</strong> <br />[LLL]$ x^2 - 5x + 4 = (x - 4)(x - 1) $[HHH]</p><p>We are essentially multiplying in reverse. Check that our factorization is correct by multiplying the right hand side.</p><p>If two things multiply to zero, at least one of them must be zero.</p><p><strong>Example:</strong> <br />[LLL]Solve $ x^2 - 5x + 4 = 0 $ <br />$ (x - 4)(x - 1) = 0 $ <br />$ x = 4 $ or $ x = 1 $ <br />[HHH]</p><br /><h2><strong>2. Solving by Completing the Square</strong></h2><p>A perfect square has the form </p>[LLL]$ x^2 + bx + (\\frac{b}{2})^2 $[HHH]<p>and this factors to</p>[LLL]$ (x + \\frac{b}{2})^2 $<p><strong>Example:</strong> <br />[LLL]Solve $ x^2 + 6x - 7 = 0 $[HHH]</p><p>Move the 7 to the right hand side.</p>[LLL]$ x^2 + 6x = 7 $[HHH]<p>Square half of six to get 9. Add to each side</p>[LLL]$ x^2 + 6x + 9 = 16 $[HHH]<p>The left-hand side is now a perfect square. Factor it</p>[LLL]$ (x + 3)^2 = 16 $[HHH]<p>Square-root both sides. One side takes two values</p>[LLL]$ x + 3 = \\pm4 $[HHH]<p>This is a short way of wrting two problems</p>[LLL]$ x + 3 = 4 $ and $ x + 3 = -4 $<br />$ x = 1 $ or $ x = -7 $', 'pdf', '4/pdf/quadratic', '2025-04-11 21:53:33', '2025-08-03 00:40:28'),
(19, 'Word Problems and Applications', 'Word Problems and Applications', 4, 0, 1, 0, 'Algebra is often used to model and solve real-world problems. Word problems typically involve translating a situation into an equation or system of equations. Key steps include identifying known and unknown quantities, writing expressions or equations to represent relationships, and solving the equations. Units and logical reasoning are important. Practice is essential to become proficient at applying algebra to various scenarios.', 'latex', '', '2025-04-11 21:53:33', '2025-08-03 00:40:28'),
