(191, 161, '20w^{-1}', 30, '2025-05-28 17:50:33', '2025-05-28 17:50:33'),
(192, 175, 'Work from the inside out. Find $ f(2) $ first', 10, '2025-06-21 20:26:48', '2025-06-21 20:26:48'),
(193, 175, 'Since $ f(2) = 3 $, $ g(f(2)) = g(3) $', 20, '2025-06-21 20:26:48', '2025-06-21 20:26:48'),
(274, 220, '\\textbf{Paso 1: Sustituimos directamente } \\(x = 4\\) \\[ \\frac{4^3 - 4(4)^2 + 4 - 4}{4^2 - 4(4)} = \\frac{64 - 64 + 0}{16 - 16} = \\frac{0}{0} \\] Esto es una \\textbf{indeterminación}, por lo que debemos simplificar.  \\bigskip', 10, '2025-07-06 14:45:29', '2025-07-06 14:45:29'),
(275, 220, '\\textbf{Paso 2: Factorizamos el numerador y el denominador}  Factorizamos el numerador agrupando términos: \\[ x^3 - 4x^2 + x - 4 = (x^3 - 4x^2) + (x - 4) = x^2(x - 4) + 1(x - 4) \\] \\[ = (x^2 + 1)(x - 4) \\]  Factorizamos el denominador: \\[ x^2 - 4x = x(x - 4) \\]  \\bigskip', 20, '2025-07-06 14:45:29', '2025-07-06 14:45:29'),
(276, 220, '\\textbf{Paso 3: Simplificamos la fracción}  \\[ \\frac{(x^2 + 1)(x - 4)}{x(x - 4)} = \\frac{x^2 + 1}{x}, \\quad x \\ne 4 \\]  \\bigskip  \\textbf{Paso 4: Sustituimos } \\(x = 4\\) \\text{ en la expresión simplificada}  \\[ \\frac{4^2 + 1}{4} = \\frac{16 + 1}{4} = \\frac{17}{4} \\]  \\bigskip', 30, '2025-07-06 14:45:29', '2025-07-06 14:45:29'),
(277, 220, '\\textbf{Resultado final:}  \\[ \\boxed{\\lim_{x \\to 4} \\frac{x^3 - 4x^2 + x - 4}{x^2 - 4x} = \\frac{17}{4}={4.25}} \\]  \\end{document}', 40, '2025-07-06 14:45:29', '2025-07-06 14:45:29'),
(278, 221, '\\textbf{Paso 1: Sustituimos directamente } \\(x = 4\\) \\[ \\frac{4^3 - 4(4)^2 + 4 - 4}{4^2 - 4(4)} = \\frac{64 - 64 + 0}{16 - 16} = \\frac{0}{0} \\] Esto es una \\textbf{indeterminación}, por lo que debemos simplificar.  \\bigskip', 10, '2025-07-06 14:47:29', '2025-07-06 14:47:29'),
(279, 221, '\\textbf{Paso 2: Factorizamos el numerador y el denominador}  Factorizamos el numerador agrupando términos: \\[ x^3 - 4x^2 + x - 4 = (x^3 - 4x^2) + (x - 4) = x^2(x - 4) + 1(x - 4) \\] \\[ = (x^2 + 1)(x - 4) \\]  Factorizamos el denominador: \\[ x^2 - 4x = x(x - 4) \\]  \\bigskip', 20, '2025-07-06 14:47:29', '2025-07-06 14:47:29'),
(280, 221, '\\textbf{Paso 3: Simplificamos la fracción}  \\[ \\frac{(x^2 + 1)(x - 4)}{x(x - 4)} = \\frac{x^2 + 1}{x}, \\quad x \\ne 4 \\]  \\bigskip  \\textbf{Paso 4: Sustituimos } \\(x = 4\\) \\text{ en la expresión simplificada}  \\[ \\frac{4^2 + 1}{4} = \\frac{16 + 1}{4} = \\frac{17}{4} \\]  \\bigskip', 30, '2025-07-06 14:47:29', '2025-07-06 14:47:29'),
(281, 221, '\\textbf{Resultado final:}  \\[ \\boxed{\\lim_{x \\to 4} \\frac{x^3 - 4x^2 + x - 4}{x^2 - 4x} = \\frac{17}{4}={4.25}} \\]  \\end{document}', 40, '2025-07-06 14:47:29', '2025-07-06 14:47:29'),
(338, 222, '\\[ \\boxed{\\text{PASO 1: SUSTITUCIÓN DIRECTA}} \\]  \\[ \\frac{4^3 - 4(4)^2 + 4 - 4}{4^2 - 4(4)} = \\frac{64 - 64 + 0}{16 - 16} = \\frac{0}{0} \\]  Esto es una indeterminación, por lo que debemos simplificar.', 10, '2025-07-06 20:58:31', '2025-07-06 20:58:31'),
(339, 222, '\\[ \\boxed{\\text{PASO 2: FACTORIZACIÓN}} \\]  Agrupamos términos en el numerador:  \\[ x^3 - 4x^2 + x - 4 = (x^3 - 4x^2) + (x - 4) \\]  \\[ = x^2(x - 4) + 1(x - 4) = (x^2 + 1)(x - 4) \\]  Factorizamos el denominador:  \\[ x^2 - 4x = x(x - 4) \\]', 20, '2025-07-06 20:58:31', '2025-07-06 20:58:31'),
(340, 222, '\\[ \\boxed{\\text{PASO 3: SIMPLIFICACIÓN}} \\]  \\[ \\frac{(x^2 + 1)(x - 4)}{x(x - 4)} = \\frac{x^2 + 1}{x}, \\quad x \\ne 4 \\]', 30, '2025-07-06 20:58:31', '2025-07-06 20:58:31'),
(341, 222, '\\[ \\boxed{\\text{PASO 4: EVALUACIÓN DEL LÍMITE}} \\]  \\[ \\frac{4^2 + 1}{4} = \\frac{16 + 1}{4} = \\frac{17}{4}={4.25} \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } \\frac{17}{4}={4.25}} \\]', 40, '2025-07-06 20:58:31', '2025-07-06 20:58:31'),
(342, 223, '\\[ \\boxed{\\text{PASO 1: SUSTITUCIÓN DIRECTA}} \\]  \\[ \\frac{3^3 - 3(3)^2 + 3 - 3}{3^2 - 3(3)} = \\frac{27 - 27 + 0}{9 - 9} = \\frac{0}{0} \\]  Esto es una indeterminación, por lo tanto se debe simplificar.', 10, '2025-07-06 20:59:44', '2025-07-06 20:59:44'),
(343, 223, '\\[ \\boxed{\\text{PASO 2: FACTORIZACIÓN}} \\]  Agrupamos términos en el numerador:  \\[ x^3 - 3x^2 + x - 3 = (x^3 - 3x^2) + (x - 3) \\]  \\[ = x^2(x - 3) + 1(x - 3) = (x^2 + 1)(x - 3) \\]  Factor del denominador:  \\[ x^2 - 3x = x(x - 3) \\]', 20, '2025-07-06 20:59:44', '2025-07-06 20:59:44'),
(344, 223, '\\[ \\boxed{\\text{PASO 3: SIMPLIFICACIÓN}} \\]  \\[ \\frac{(x^2 + 1)(x - 3)}{x(x - 3)} = \\frac{x^2 + 1}{x}, \\quad x \\ne 3 \\]', 30, '2025-07-06 20:59:44', '2025-07-06 20:59:44'),
(345, 223, '\\[ \\boxed{\\text{PASO 4: EVALUACIÓN DEL LÍMITE}} \\]  \\[ \\frac{3^2 + 1}{3} = \\frac{9 + 1}{3} = \\frac{10}{3}={3.333} \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } \\frac{10}{3}={3.333}} \\]', 40, '2025-07-06 20:59:44', '2025-07-06 20:59:44'),
(346, 224, '\\[ \\boxed{\\text{PASO 1: SUSTITUCIÓN DIRECTA}} \\]  \\[ \\frac{3^3 - 3(3)^2 + 3 - 3}{3^2 - 3(3)} = \\frac{27 - 27 + 0}{9 - 9} = \\frac{0}{0} \\]  Esto es una indeterminación, por lo tanto se debe simplificar.', 10, '2025-07-06 21:04:43', '2025-07-06 21:04:43'),
(347, 224, '\\[ \\boxed{\\text{PASO 2: FACTORIZACIÓN}} \\]  Agrupamos términos en el numerador:  \\[ x^3 - 3x^2 + x - 3 = (x^3 - 3x^2) + (x - 3) \\]  \\[ = x^2(x - 3) + 1(x - 3) = (x^2 + 1)(x - 3) \\]  Factor del denominador:  \\[ x^2 - 3x = x(x - 3) \\]', 20, '2025-07-06 21:04:43', '2025-07-06 21:04:43'),
(348, 224, '\\[ \\boxed{\\text{PASO 3: SIMPLIFICACIÓN}} \\]  \\[ \\frac{(x^2 + 1)(x - 3)}{x(x - 3)} = \\frac{x^2 + 1}{x}, \\quad x \\ne 3 \\]', 30, '2025-07-06 21:04:43', '2025-07-06 21:04:43'),
(349, 224, '\\[ \\boxed{\\text{PASO 4: EVALUACIÓN DEL LÍMITE}} \\]  \\[ \\frac{3^2 + 1}{3} = \\frac{9 + 1}{3} = \\frac{10}{3}={3.333} \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } \\frac{10}{3}={3.333}} \\]', 40, '2025-07-06 21:04:43', '2025-07-06 21:04:43'),
(354, 226, '\\[ \\boxed{\\text{PASO 1: SUSTITUCIÓN DIRECTA}} \\]  \\[ \\frac{3 - 3}{\\sqrt{3(3)} - 3} = \\frac{0}{\\sqrt{9} - 3} = \\frac{0}{3 - 3} = \\frac{0}{0} \\]  Se obtiene una indeterminación. Para resolverla, racionalizamos el denominador.', 10, '2025-07-06 21:13:16', '2025-07-06 21:13:16'),
(355, 226, '\\[ \\boxed{\\text{PASO 2: MULTIPLICAMOS POR EL CONJUGADO}} \\]  Multiplicamos numerador y denominador por el conjugado de \\( \\sqrt{3x} - 3 \\), que es \\( \\sqrt{3x} + 3 \\):  \\[ \\frac{x - 3}{\\sqrt{3x} - 3} \\cdot \\frac{\\sqrt{3x} + 3}{\\sqrt{3x} + 3} = \\frac{(x - 3)(\\sqrt{3x} + 3)}{(\\sqrt{3x} - 3)(\\sqrt{3x} + 3)} \\]  \\[ = \\frac{(x - 3)(\\sqrt{3x} + 3)}{3x - 9} \\]', 20, '2025-07-06 21:13:16', '2025-07-06 21:13:16'),
(356, 226, '\\[ \\boxed{\\text{PASO 3: SIMPLIFICAMOS}} \\]  Notamos que \\( 3x - 9 = 3(x - 3) \\), así que:  \\[ \\frac{(x - 3)(\\sqrt{3x} + 3)}{3(x - 3)} = \\frac{\\sqrt{3x} + 3}{3}, \\quad x \\ne 3 \\]', 30, '2025-07-06 21:13:16', '2025-07-06 21:13:16'),
(357, 226, '\\[ \\boxed{\\text{PASO 4: EVALUAMOS EL LÍMITE}} \\]  \\[ \\frac{\\sqrt{3(3)} + 3}{3} = \\frac{3 + 3}{3} = \\frac{6}{3} = 2 \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } 2} \\]', 40, '2025-07-06 21:13:16', '2025-07-06 21:13:16'),
(358, 225, '\\[ \\boxed{\\text{PASO 1: SUSTITUCIÓN DIRECTA}} \\]  \\[ \\frac{2 - 2}{\\sqrt{2(2)} - 2} = \\frac{0}{\\sqrt{4} - 2} = \\frac{0}{2 - 2} = \\frac{0}{0} \\]  Tenemos una indeterminación. Procedemos a racionalizar el denominador.', 10, '2025-07-06 21:18:03', '2025-07-06 21:18:03'),
(359, 225, '\\[ \\boxed{\\text{PASO 2: MULTIPLICAMOS POR EL CONJUGADO}} \\]  Multiplicamos numerador y denominador por el conjugado de \\( \\sqrt{2x} - 2 \\), que es \\( \\sqrt{2x} + 2 \\):  \\[ \\frac{x - 2}{\\sqrt{2x} - 2} \\cdot \\frac{\\sqrt{2x} + 2}{\\sqrt{2x} + 2} = \\frac{(x - 2)(\\sqrt{2x} + 2)}{(\\sqrt{2x} - 2)(\\sqrt{2x} + 2)} \\]  \\[ = \\frac{(x - 2)(\\sqrt{2x} + 2)}{2x - 4} \\]', 20, '2025-07-06 21:18:03', '2025-07-06 21:18:03'),
(360, 225, '\\[ \\boxed{\\text{PASO 3: SIMPLIFICAMOS}} \\]  Notamos que \\( 2x - 4 = 2(x - 2) \\), por lo tanto:  \\[ \\frac{(x - 2)(\\sqrt{2x} + 2)}{2(x - 2)} = \\frac{\\sqrt{2x} + 2}{2}, \\quad x \\ne 2 \\]', 30, '2025-07-06 21:18:03', '2025-07-06 21:18:03'),
(361, 225, '\\[ \\boxed{\\text{PASO 4: EVALUAMOS EL LÍMITE}} \\]  \\[ \\frac{\\sqrt{2(2)} + 2}{2} = \\frac{\\sqrt{4} + 2}{2} = \\frac{2 + 2}{2} = \\frac{4}{2} = 2 \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } 2} \\]', 40, '2025-07-06 21:18:03', '2025-07-06 21:18:03'),
(362, 228, '\\[ \\boxed{\\text{PASO 1: SUSTITUCIÓN DIRECTA}} \\]  \\[ \\frac{2 - 2}{\\sqrt{2(2)} - 2} = \\frac{0}{\\sqrt{4} - 2} = \\frac{0}{2 - 2} = \\frac{0}{0} \\]  Tenemos una indeterminación. Procedemos a racionalizar el denominador.', 10, '2025-07-07 02:32:45', '2025-07-07 02:32:45'),
(363, 228, '\\[ \\boxed{\\text{PASO 2: MULTIPLICAMOS POR EL CONJUGADO}} \\]  Multiplicamos numerador y denominador por el conjugado de \\( \\sqrt{2x} - 2 \\), que es \\( \\sqrt{2x} + 2 \\):  \\[ \\frac{x - 2}{\\sqrt{2x} - 2} \\cdot \\frac{\\sqrt{2x} + 2}{\\sqrt{2x} + 2} = \\frac{(x - 2)(\\sqrt{2x} + 2)}{(\\sqrt{2x} - 2)(\\sqrt{2x} + 2)} \\]  \\[ = \\frac{(x - 2)(\\sqrt{2x} + 2)}{2x - 4} \\]', 20, '2025-07-07 02:32:45', '2025-07-07 02:32:45'),
(364, 228, '\\[ \\boxed{\\text{PASO 3: SIMPLIFICAMOS}} \\]  Notamos que \\( 2x - 4 = 2(x - 2) \\), por lo tanto:  \\[ \\frac{(x - 2)(\\sqrt{2x} + 2)}{2(x - 2)} = \\frac{\\sqrt{2x} + 2}{2}, \\quad x \\ne 2 \\]', 30, '2025-07-07 02:32:45', '2025-07-07 02:32:45'),
(365, 228, '\\[ \\boxed{\\text{PASO 4: EVALUAMOS EL LÍMITE}} \\]  \\[ \\frac{\\sqrt{2(2)} + 2}{2} = \\frac{\\sqrt{4} + 2}{2} = \\frac{2 + 2}{2} = \\frac{4}{2} = 2 \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } 2} \\]', 40, '2025-07-07 02:32:45', '2025-07-07 02:32:45'),
(366, 229, '\\[ \\boxed{\\text{PASO 1: SUSTITUCIÓN DIRECTA}} \\]  \\[ \\frac{2 - 2}{\\sqrt{2(2)} - 2} = \\frac{0}{\\sqrt{4} - 2} = \\frac{0}{2 - 2} = \\frac{0}{0} \\]  Tenemos una indeterminación. Procedemos a racionalizar el denominador.', 10, '2025-07-07 02:32:54', '2025-07-07 02:32:54'),
(367, 229, '\\[ \\boxed{\\text{PASO 2: MULTIPLICAMOS POR EL CONJUGADO}} \\]  Multiplicamos numerador y denominador por el conjugado de \\( \\sqrt{2x} - 2 \\), que es \\( \\sqrt{2x} + 2 \\):  \\[ \\frac{x - 2}{\\sqrt{2x} - 2} \\cdot \\frac{\\sqrt{2x} + 2}{\\sqrt{2x} + 2} = \\frac{(x - 2)(\\sqrt{2x} + 2)}{(\\sqrt{2x} - 2)(\\sqrt{2x} + 2)} \\]  \\[ = \\frac{(x - 2)(\\sqrt{2x} + 2)}{2x - 4} \\]', 20, '2025-07-07 02:32:54', '2025-07-07 02:32:54'),
(368, 229, '\\[ \\boxed{\\text{PASO 3: SIMPLIFICAMOS}} \\]  Notamos que \\( 2x - 4 = 2(x - 2) \\), por lo tanto:  \\[ \\frac{(x - 2)(\\sqrt{2x} + 2)}{2(x - 2)} = \\frac{\\sqrt{2x} + 2}{2}, \\quad x \\ne 2 \\]', 30, '2025-07-07 02:32:54', '2025-07-07 02:32:54'),
(369, 229, '\\[ \\boxed{\\text{PASO 4: EVALUAMOS EL LÍMITE}} \\]  \\[ \\frac{\\sqrt{2(2)} + 2}{2} = \\frac{\\sqrt{4} + 2}{2} = \\frac{2 + 2}{2} = \\frac{4}{2} = 2 \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } 2} \\]', 40, '2025-07-07 02:32:54', '2025-07-07 02:32:54'),
(370, 230, '\\[ \\boxed{\\text{PASO 1: SUSTITUCIÓN DIRECTA}} \\]  \\[ \\frac{2 - 2}{\\sqrt{2(2)} - 2} = \\frac{0}{\\sqrt{4} - 2} = \\frac{0}{2 - 2} = \\frac{0}{0} \\]  Tenemos una indeterminación. Procedemos a racionalizar el denominador.', 10, '2025-07-07 02:33:05', '2025-07-07 02:33:05'),
(371, 230, '\\[ \\boxed{\\text{PASO 2: MULTIPLICAMOS POR EL CONJUGADO}} \\]  Multiplicamos numerador y denominador por el conjugado de \\( \\sqrt{2x} - 2 \\), que es \\( \\sqrt{2x} + 2 \\):  \\[ \\frac{x - 2}{\\sqrt{2x} - 2} \\cdot \\frac{\\sqrt{2x} + 2}{\\sqrt{2x} + 2} = \\frac{(x - 2)(\\sqrt{2x} + 2)}{(\\sqrt{2x} - 2)(\\sqrt{2x} + 2)} \\]  \\[ = \\frac{(x - 2)(\\sqrt{2x} + 2)}{2x - 4} \\]', 20, '2025-07-07 02:33:05', '2025-07-07 02:33:05'),
(372, 230, '\\[ \\boxed{\\text{PASO 3: SIMPLIFICAMOS}} \\]  Notamos que \\( 2x - 4 = 2(x - 2) \\), por lo tanto:  \\[ \\frac{(x - 2)(\\sqrt{2x} + 2)}{2(x - 2)} = \\frac{\\sqrt{2x} + 2}{2}, \\quad x \\ne 2 \\]', 30, '2025-07-07 02:33:05', '2025-07-07 02:33:05'),
(373, 230, '\\[ \\boxed{\\text{PASO 4: EVALUAMOS EL LÍMITE}} \\]  \\[ \\frac{\\sqrt{2(2)} + 2}{2} = \\frac{\\sqrt{4} + 2}{2} = \\frac{2 + 2}{2} = \\frac{4}{2} = 2 \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } 2} \\]', 40, '2025-07-07 02:33:05', '2025-07-07 02:33:05'),
(374, 231, '\\[ \\boxed{\\text{PASO 1: SUSTITUCIÓN DIRECTA}} \\]  \\[ \\frac{2 - 2}{\\sqrt{2(2)} - 2} = \\frac{0}{\\sqrt{4} - 2} = \\frac{0}{2 - 2} = \\frac{0}{0} \\]  Tenemos una indeterminación. Procedemos a racionalizar el denominador.', 10, '2025-07-07 02:33:05', '2025-07-07 02:33:05'),
(375, 231, '\\[ \\boxed{\\text{PASO 2: MULTIPLICAMOS POR EL CONJUGADO}} \\]  Multiplicamos numerador y denominador por el conjugado de \\( \\sqrt{2x} - 2 \\), que es \\( \\sqrt{2x} + 2 \\):  \\[ \\frac{x - 2}{\\sqrt{2x} - 2} \\cdot \\frac{\\sqrt{2x} + 2}{\\sqrt{2x} + 2} = \\frac{(x - 2)(\\sqrt{2x} + 2)}{(\\sqrt{2x} - 2)(\\sqrt{2x} + 2)} \\]  \\[ = \\frac{(x - 2)(\\sqrt{2x} + 2)}{2x - 4} \\]', 20, '2025-07-07 02:33:05', '2025-07-07 02:33:05'),
(376, 231, '\\[ \\boxed{\\text{PASO 3: SIMPLIFICAMOS}} \\]  Notamos que \\( 2x - 4 = 2(x - 2) \\), por lo tanto:  \\[ \\frac{(x - 2)(\\sqrt{2x} + 2)}{2(x - 2)} = \\frac{\\sqrt{2x} + 2}{2}, \\quad x \\ne 2 \\]', 30, '2025-07-07 02:33:05', '2025-07-07 02:33:05'),
(377, 231, '\\[ \\boxed{\\text{PASO 4: EVALUAMOS EL LÍMITE}} \\]  \\[ \\frac{\\sqrt{2(2)} + 2}{2} = \\frac{\\sqrt{4} + 2}{2} = \\frac{2 + 2}{2} = \\frac{4}{2} = 2 \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } 2} \\]', 40, '2025-07-07 02:33:05', '2025-07-07 02:33:05'),
(390, 232, '\\[ \\boxed{\\text{PASO 1: SUSTITUCIÓN DIRECTA}} \\]  \\[ \\frac{3 - \\sqrt{5 + 4}}{5 - 5} = \\frac{3 - \\sqrt{9}}{0} = \\frac{3 - 3}{0} = \\frac{0}{0} \\]  Obtenemos una indeterminación, por lo tanto, debemos racionalizar.', 10, '2025-07-08 03:02:18', '2025-07-08 03:02:18'),
(391, 232, '\\[ \\boxed{\\text{PASO 2: MULTIPLICAMOS POR EL CONJUGADO}} \\]  Multiplicamos numerador y denominador por el conjugado de \\( 3 - \\sqrt{x + 4} \\), que es \\( 3 + \\sqrt{x + 4} \\):  \\[ \\frac{3 - \\sqrt{x + 4}}{x - 5} \\cdot \\frac{3 + \\sqrt{x + 4}}{3 + \\sqrt{x + 4}} = \\frac{(3 - \\sqrt{x + 4})(3 + \\sqrt{x + 4})}{(x - 5)(3 + \\sqrt{x + 4})} \\]  \\[ = \\frac{9 - (x + 4)}{(x - 5)(3 + \\sqrt{x + 4})} \\]  \\[ = \\frac{9 - x - 4}{(x - 5)(3 + \\sqrt{x + 4})} = \\frac{5 - x}{(x - 5)(3 + \\sqrt{x + 4})} \\]', 20, '2025-07-08 03:02:18', '2025-07-08 03:02:18'),
(392, 232, '\\[ \\boxed{\\text{PASO 3: SIMPLIFICAMOS}} \\]  Observamos que \\( 5 - x = -(x - 5) \\), así que:  \\[ \\frac{-(x - 5)}{(x - 5)(3 + \\sqrt{x + 4})} = \\frac{-1}{3 + \\sqrt{x + 4}}, \\quad x \\ne 5 \\]', 30, '2025-07-08 03:02:18', '2025-07-08 03:02:18'),
(393, 232, '\\[ \\boxed{\\text{PASO 4: EVALUAMOS EL LÍMITE}} \\]  Sustituimos \\( x = 5 \\) en la expresión simplificada:  \\[ \\frac{-1}{3 + \\sqrt{5 + 4}} = \\frac{-1}{3 + \\sqrt{9}} = \\frac{-1}{3 + 3} = \\frac{-1}{6}={-0.1666} \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } \\frac{-1}{6}={-0.1666}} \\]', 40, '2025-07-08 03:02:18', '2025-07-08 03:02:18'),
(398, 234, '\\[ \\boxed{\\text{PASO 1: SUSTITUCIÓN DIRECTA}} \\]  \\[ \\frac{2 - \\sqrt{3 + 1}}{3 - 3} = \\frac{2 - \\sqrt{4}}{0} = \\frac{2 - 2}{0} = \\frac{0}{0} \\]  Esto es una indeterminación, así que debemos racionalizar el numerador.', 10, '2025-07-09 18:57:27', '2025-07-09 18:57:27'),
(399, 234, '\\[ \\boxed{\\text{PASO 2: MULTIPLICAMOS POR EL CONJUGADO DEL NUMERADOR}} \\]  Multiplicamos numerador y denominador por el conjugado de \\( 2 - \\sqrt{x + 1} \\), que es \\( 2 + \\sqrt{x + 1} \\):  \\[ \\frac{2 - \\sqrt{x + 1}}{x - 3} \\cdot \\frac{2 + \\sqrt{x + 1}}{2 + \\sqrt{x + 1}} = \\frac{(2 - \\sqrt{x + 1})(2 + \\sqrt{x + 1})}{(x - 3)(2 + \\sqrt{x + 1})} \\]  \\[ = \\frac{4 - (x + 1)}{(x - 3)(2 + \\sqrt{x + 1})} = \\frac{4 - x - 1}{(x - 3)(2 + \\sqrt{x + 1})} \\]  \\[ = \\frac{3 - x}{(x - 3)(2 + \\sqrt{x + 1})} \\]', 20, '2025-07-09 18:57:27', '2025-07-09 18:57:27'),
(400, 234, '\\[ \\boxed{\\text{PASO 3: SIMPLIFICAMOS}} \\]  Observamos que \\( 3 - x = -(x - 3) \\), así que:  \\[ \\frac{-(x - 3)}{(x - 3)(2 + \\sqrt{x + 1})} = \\frac{-1}{2 + \\sqrt{x + 1}}, \\quad x \\ne 3 \\]', 30, '2025-07-09 18:57:27', '2025-07-09 18:57:27'),
(401, 234, '\\[ \\boxed{\\text{PASO 4: EVALUAMOS EL LÍMITE}} \\]  Sustituimos \\( x = 3 \\) en la expresión simplificada:  \\[ \\frac{-1}{2 + \\sqrt{3 + 1}} = \\frac{-1}{2 + \\sqrt{4}} = \\frac{-1}{2 + 2} = \\frac{-1}{4}={-0.25} \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } \\frac{-1}{4}={-0.25}} \\]', 40, '2025-07-09 18:57:27', '2025-07-09 18:57:27'),
(405, 235, 'Resuelva para $ x $: $ y = 3x - 1 $', 10, '2025-07-11 11:31:29', '2025-07-11 11:31:29'),
(406, 235, 'x = $ \\frac{y + 1}{3} $', 20, '2025-07-11 11:31:29', '2025-07-11 11:31:29'),
(407, 235, '$ f^{-1}(x) = \\frac{x + 1}{3} $', 30, '2025-07-11 11:31:29', '2025-07-11 11:31:29'),
(408, 236, '\\[ \\boxed{\\text{PASO 1: SUSTITUCIÓN DIRECTA}} \\]  Como la función \\( sen(x) \\) es continua en todo su dominio, podemos simplemente evaluar el límite sustituyendo:  \\[ sen(2) \\]', 10, '2025-07-12 14:23:51', '2025-07-12 14:23:51'),
(409, 236, '\\[ \\boxed{\\text{PASO 2: EVALUAMOS CON CALCULADORA}} \\]  \\[ sen(2) \\approx 0.909 \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } 0.909} \\]', 20, '2025-07-12 14:23:51', '2025-07-12 14:23:51'),
(410, 237, '\\[ \\boxed{\\text{PASO 1: SUSTITUCIÓN DIRECTA}} \\]  Como la función \\( sen(x) \\) es continua en todo su dominio, podemos simplemente evaluar el límite sustituyendo:  \\[ sen(2) \\]', 10, '2025-07-12 14:26:24', '2025-07-12 14:26:24'),
(411, 237, '\\[ \\boxed{\\text{PASO 2: EVALUAMOS CON CALCULADORA}} \\]  \\[ sen(2) \\approx 0.909 \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } 0.909} \\]', 20, '2025-07-12 14:26:24', '2025-07-12 14:26:24'),
(412, 238, '\\[ \\boxed{\\text{PASO 1: SUSTITUCIÓN DIRECTA}} \\]  Como la función \\( sen(x) \\) es continua en todo su dominio, podemos simplemente evaluar el límite sustituyendo:  \\[ sen(2) \\]', 10, '2025-07-12 14:28:12', '2025-07-12 14:28:12'),
(413, 238, '\\[ \\boxed{\\text{PASO 2: EVALUAMOS CON CALCULADORA}} \\]  \\[ sen(2) \\approx 0.909 \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } 0.909} \\]', 20, '2025-07-12 14:28:12', '2025-07-12 14:28:12'),
(414, 239, '\\[ \\boxed{\\text{PASO 1: SUSTITUCIÓN DIRECTA}} \\]  La función \\( \\cos(x) \\) es continua, así que evaluamos directamente:  \\[ \\cos(3) \\]', 10, '2025-07-12 14:37:45', '2025-07-12 14:37:45'),
(415, 239, '\\[ \\boxed{\\text{PASO 2: EVALUAMOS CON CALCULADORA}} \\]  \\[ \\cos(3) \\approx -0.99 \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } -0.99} \\]', 20, '2025-07-12 14:37:45', '2025-07-12 14:37:45'),
(416, 240, '\\[ \\boxed{\\text{PASO 1: SUSTITUCIÓN DIRECTA}} \\]  La función \\( \\cos(5x) \\) es continua, así que evaluamos directamente:  \\[ \\cos(5 \\cdot 0) = \\cos(0) \\]', 10, '2025-07-12 14:43:32', '2025-07-12 14:43:32'),
(417, 240, '\\[ \\boxed{\\text{PASO 2: EVALUAMOS CON CALCULADORA}} \\]  \\[ \\cos(0) = 1 \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } 1} \\]', 20, '2025-07-12 14:43:32', '2025-07-12 14:43:32'),
(418, 241, '\\[ \\boxed{\\text{PASO 1: SUSTITUCIÓN DIRECTA}} \\] La función \\( \\cos(3x) \\) es continua en todo su dominio, por lo tanto, podemos evaluar el límite sustituyendo directamente:  \\[ \\lim_{x \\to 0} \\cos(3x) = \\cos(3 \\cdot 0) = \\cos(0) \\]', 10, '2025-07-13 14:30:07', '2025-07-13 14:30:07'),
(419, 241, '\\[ \\boxed{\\text{PASO 2: EVALUAMOS CON CALCULADORA}} \\] Sabemos que:  \\[ \\cos(0) = 1 \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } 1} \\]', 20, '2025-07-13 14:30:07', '2025-07-13 14:30:07'),
(420, 243, '\\[ \\boxed{\\text{PASO 1: SUSTITUCIÓN DIRECTA}} \\] La función \\( sen(7x) \\) es continua en todo su dominio, por lo tanto, podemos evaluar el límite sustituyendo directamente:  \\[ \\lim_{x \\to 0} sen(7x) = sen(7 \\cdot 0) = sen(0) \\]', 10, '2025-07-13 15:08:32', '2025-07-13 15:08:32'),
(421, 243, '\\[ \\boxed{\\text{PASO 2: EVALUAMOS CON CALCULADORA}} \\]  \\[ sen(0) = 0 \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } 0} \\]', 20, '2025-07-13 15:08:32', '2025-07-13 15:08:32'),
(422, 244, '\\[ \\boxed{\\text{PASO 1: SUSTITUCIÓN DIRECTA}} \\] La función \\( sen(2x) \\) es continua en todo su dominio, por lo tanto, podemos evaluar el límite sustituyendo directamente:  \\[ \\lim_{x \\to 0} sen(2x) = sen(2 \\cdot 0) = sen(0) \\]', 10, '2025-07-13 15:17:16', '2025-07-13 15:17:16'),
(423, 244, '\\[ \\boxed{\\text{PASO 2: EVALUAMOS CON CALCULADORA}} \\]  \\[ sen(0) = 0 \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } 0} \\]', 20, '2025-07-13 15:17:16', '2025-07-13 15:17:16'),
(428, 246, '\\[ \\boxed{\\text{PASO 1: IDENTIFICAMOS LA FORMA INDETERMINADA}} \\] Sustituimos directamente \\( x = 0 \\):  \\[ \\lim_{x \\to 0} \\frac{5sen(3x)}{x} = \\frac{5sen(3 \\cdot 0)}{0} = \\frac{5sen(0)}{0} = \\frac{0}{0} \\]  Tenemos una forma indeterminada, por lo tanto, aplicaremos una estrategia basada en la propiedad del límite trigonométrico.', 10, '2025-07-13 15:42:45', '2025-07-13 15:42:45'),
(429, 246, '\\[ \\boxed{\\text{PASO 2: FACTORIZAMOS LA CONSTANTE}} \\]  Sacamos el factor constante \\( 5 \\) fuera del límite:  \\[ \\lim_{x \\to 0} \\frac{5sen(3x)}{x} = 5 \\cdot \\lim_{x \\to 0} \\frac{sen(3x)}{x} \\]', 20, '2025-07-13 15:42:45', '2025-07-13 15:42:45'),
(430, 246, '\\[ \\boxed{\\text{PASO 3: REESCRIBIMOS LA EXPRESIÓN PARA APLICAR LA REGLA}} \\]  Multiplicamos y dividimos por 3 para obtener la forma \\( \\frac{sen(u)}{u} \\):  \\[ 5 \\cdot \\lim_{x \\to 0} \\frac{sen(3x)}{x} = 5 \\cdot \\lim_{x \\to 0} \\left( \\frac{sen(3x)}{3x} \\cdot 3 \\right) \\]  \\[ = 5 \\cdot 3 \\cdot \\lim_{x \\to 0} \\frac{sen(3x)}{3x} \\]', 30, '2025-07-13 15:42:45', '2025-07-13 15:42:45'),
(431, 246, '\\[ \\boxed{\\text{PASO 4: APLICAMOS LA PROPIEDAD DEL LÍMITE}} \\]  Sabemos que \\( \\lim_{u \\to 0} \\frac{sen(u)}{u} = 1 \\), por lo tanto:  \\[ \\lim_{x \\to 0} \\frac{sen(3x)}{3x} = 1 \\]  Entonces:  \\[ 5 \\cdot 3 \\cdot 1 = 15 \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } 15} \\]', 40, '2025-07-13 15:42:45', '2025-07-13 15:42:45'),
(432, 247, '\\[ \\boxed{\\text{PASO 1: IDENTIFICAMOS LA FORMA INDETERMINADA}} \\] Sustituimos directamente \\( x = 1 \\):  \\[ \\frac{(2 \\cdot 1 - 2)\\, cos(1 - 1)}{1 - 1} = \\frac{(2 - 2)\\, cos(0)}{0} = \\frac{0 \\cdot 1}{0} = \\frac{0}{0} \\]  Tenemos una forma indeterminada, por lo tanto, debemos simplificar la expresión.', 10, '2025-07-13 16:14:12', '2025-07-13 16:14:12'),
(433, 247, '\\[ \\boxed{\\text{PASO 2: FACTORIZAMOS Y SIMPLIFICAMOS}} \\]  Observamos que el numerador tiene un factor común con el denominador:  \\[ \\frac{(2x - 2)\\, cos(x - 1)}{x - 1} = \\frac{2(x - 1)\\, cos(x - 1)}{x - 1} \\]  Simplificamos el factor \\( x - 1 \\):  \\[ = 2 \\cdot cos(x - 1) \\]', 20, '2025-07-13 16:14:12', '2025-07-13 16:14:12'),
(434, 247, '\\[ \\boxed{\\text{PASO 3: APLICAMOS EL LÍMITE}} \\]  Ya no hay indeterminación, así que evaluamos directamente:  \\[ \\lim_{x \\to 1} 2 \\cdot cos(x - 1) = 2 \\cdot cos(1 - 1) = 2 \\cdot cos(0) \\]', 30, '2025-07-13 16:14:12', '2025-07-13 16:14:12'),
(435, 247, '\\[ \\boxed{\\text{PASO 4: EVALUAMOS CON CALCULADORA}} \\]  \\[ cos(0) = 1 \\quad \\Rightarrow \\quad 2 \\cdot 1 = 2 \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } 2} \\]', 40, '2025-07-13 16:14:12', '2025-07-13 16:14:12'),
(436, 248, '\\[ \\boxed{\\text{PASO 1: IDENTIFICAMOS LA FORMA INDETERMINADA}} \\] Sustituimos directamente \\( x = 2 \\):  \\[ \\frac{(3 \\cdot 2 - 6)\\, cos(2 - 2)}{2 - 2} = \\frac{(6 - 6)\\, cos(0)}{0} = \\frac{0 \\cdot 1}{0} = \\frac{0}{0} \\]  Tenemos una forma indeterminada, por lo tanto, debemos simplificar la expresión.', 10, '2025-07-13 16:29:01', '2025-07-13 16:29:01'),
(437, 248, '\\[ \\boxed{\\text{PASO 2: FACTORIZAMOS Y SIMPLIFICAMOS}} \\]  Observamos que el numerador tiene un factor común con el denominador:  \\[ \\frac{(3x - 6)\\, cos(x - 2)}{x - 2} = \\frac{3(x - 2)\\, cos(x - 2)}{x - 2} \\]  Simplificamos el factor \\( x - 2 \\):  \\[ = 3 \\cdot cos(x - 2) \\]', 20, '2025-07-13 16:29:01', '2025-07-13 16:29:01'),
(438, 248, '\\[ \\boxed{\\text{PASO 3: APLICAMOS EL LÍMITE}} \\]  Ya no hay indeterminación, así que evaluamos directamente:  \\[ \\lim_{x \\to 2} 3 \\cdot cos(x - 2) = 3 \\cdot cos(2 - 2) = 3 \\cdot cos(0) \\]', 30, '2025-07-13 16:29:01', '2025-07-13 16:29:01'),
(439, 248, '\\[ \\boxed{\\text{PASO 4: EVALUAMOS CON CALCULADORA}} \\]  \\[ cos(0) = 1 \\quad \\Rightarrow \\quad 3 \\cdot 1 = 3 \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } 3} \\]', 40, '2025-07-13 16:29:01', '2025-07-13 16:29:01'),
(444, 251, '\\[ \\boxed{\\text{PASO 1: IDENTIFICAMOS LA FORMA INDETERMINADA}} \\]  Sustituimos directamente \\( x = -5 \\):  \\[ \\frac{((-5)^2 - 25)\\, cos(-5 + 5)}{(-5)^2 + 7(-5) + 10} = \\frac{(25 - 25)\\, cos(0)}{25 - 35 + 10} = \\frac{0 \\cdot cos(0)}{0} = \\frac{0}{0} \\]  Obtenemos una forma indeterminada, por lo tanto, debemos simplificar la expresión.', 10, '2025-07-13 22:43:00', '2025-07-13 22:43:00'),
(445, 251, '\\[ \\boxed{\\text{PASO 2: FACTORIZAMOS NUMERADOR Y DENOMINADOR}} \\]  Factorizamos el numerador y el denominador:  \\[ x^2 - 25 = (x - 5)(x + 5), \\quad x^2 + 7x + 10 = (x + 5)(x + 2) \\]  Sustituimos en la expresión original:  \\[ \\frac{(x - 5)(x + 5)\\, cos(x + 5)}{(x + 5)(x + 2)} \\]', 20, '2025-07-13 22:43:00', '2025-07-13 22:43:00'),
(446, 251, '\\[ \\boxed{\\text{PASO 3: CANCELAMOS EL FACTOR COMÚN}} \\]  Cancelamos el factor común \\( x + 5 \\) en numerador y denominador:  \\[ = \\frac{(x - 5)\\, cos(x + 5)}{x + 2} \\]', 30, '2025-07-13 22:43:00', '2025-07-13 22:43:00'),
(447, 251, '\\[ \\boxed{\\text{PASO 4: APLICAMOS EL LÍMITE}} \\]  Evaluamos directamente la expresión simplificada en \\( x = -5 \\):  \\[ \\frac{(-5 - 5)\\, cos(-5 + 5)}{-5 + 2} = \\frac{(-10)\\, cos(0)}{-3} \\]', 40, '2025-07-13 22:43:00', '2025-07-13 22:43:00'),
(448, 251, '\\[ \\boxed{\\text{PASO 5: EVALUAMOS CON CALCULADORA}} \\]  \\[ cos(0) = 1 \\quad \\Rightarrow \\quad \\frac{-10 \\cdot 1}{-3} = \\frac{-10}{-3} \\approx 3.33 \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } 3.33} \\]', 50, '2025-07-13 22:43:00', '2025-07-13 22:43:00'),
(449, 245, '\\[ \\boxed{\\text{PASO 1: IDENTIFICAMOS LA FORMA INDETERMINADA}} \\] Sustituimos directamente \\( x = 0 \\):  \\[ \\lim_{x \\to 0} \\frac{3sen(4x)}{x} = \\frac{3sen(4 \\cdot 0)}{0} = \\frac{3sen(0)}{0} = \\frac{0}{0} \\]  Tenemos una forma indeterminada, así que debemos aplicar una propiedad de límites.', 20, '2025-07-14 16:18:46', '2025-07-14 16:18:46'),
(450, 245, '\\[ \\boxed{\\text{PASO 2: FACTORIZAMOS LA CONSTANTE}} \\]  Sacamos el factor constante \\( 3 \\) fuera del límite:  \\[ \\lim_{x \\to 0} \\frac{3sen(4x)}{x} = 3 \\cdot \\lim_{x \\to 0} \\frac{sen(4x)}{x} \\]', 30, '2025-07-14 16:18:46', '2025-07-14 16:18:46'),
(451, 245, '\\[ \\boxed{\\text{PASO 3: REESCRIBIMOS LA EXPRESIÓN PARA APLICAR LA REGLA}} \\]  Multiplicamos y dividimos por 4 para obtener la forma \\( \\frac{sen(u)}{u} \\):  \\[ 3 \\cdot \\lim_{x \\to 0} \\frac{sen(4x)}{x} = 3 \\cdot \\lim_{x \\to 0} \\left( \\frac{sen(4x)}{4x} \\cdot 4 \\right) \\]  \\[ = 3 \\cdot 4 \\cdot \\lim_{x \\to 0} \\frac{sen(4x)}{4x} \\]', 40, '2025-07-14 16:18:46', '2025-07-14 16:18:46'),
(452, 245, '\\[ \\boxed{\\text{PASO 4: APLICAMOS LA PROPIEDAD DEL LÍMITE}} \\]  Sabemos que \\( \\lim_{u \\to 0} \\frac{sen(u)}{u} = 1 \\), así que:  \\[ \\lim_{x \\to 0} \\frac{sen(4x)}{4x} = 1 \\]  Entonces:  \\[ 3 \\cdot 4 \\cdot 1 = 12 \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } 12} \\]', 40, '2025-07-14 16:18:46', '2025-07-14 16:18:46'),
(453, 252, '\\[ \\boxed{\\text{PASO 1: IDENTIFICAMOS LA FORMA INDETERMINADA}} \\]  Sustituimos directamente \\( x = -3 \\):  \\[ \\frac{6sen^2(-3+3)}{(-3)^2 + 6(-3) + 9} = \\frac{6sen^2(0)}{9 - 18 + 9} = \\frac{6 \\cdot 0^2}{0} = \\frac{0}{0} \\]  Obtenemos una forma indeterminada, por lo tanto, debemos simplificar la expresión.', 10, '2025-07-15 18:34:01', '2025-07-15 18:34:01'),
(454, 252, '\\[ \\boxed{\\text{PASO 2: FACTORIZAMOS EL DENOMINADOR}} \\]  El trinomio del denominador es un trinomio cuadrado perfecto:  \\[ x^2 + 6x + 9 = (x + 3)^2 \\]  Sustituimos en la expresión original:  \\[ \\frac{6sen^2(x + 3)}{(x + 3)^2} \\]', 20, '2025-07-15 18:34:01', '2025-07-15 18:34:01'),
(455, 252, '\\[ \\boxed{\\text{PASO 3: REESCRIBIR LA EXPRESIÓN USANDO UNA IDENTIDAD}} \\]  Recordamos que: \\[ \\operatorname{sen}^2(x + 3) = \\left[\\operatorname{sen}(x + 3)\\right]^2 \\] Entonces, la expresión se convierte en: \\[ 6 \\left(\\frac{\\operatorname{sen}(x + 3)}{x + 3}\\right)^2 \\]', 30, '2025-07-15 18:34:01', '2025-07-15 18:34:01'),
(456, 252, '\\[ \\boxed{\\text{PASO 4: APLICAR EL LÍMITE USANDO UNA IDENTIDAD NOTABLE}} \\]  Sabemos que: \\[ \\lim_{u \\to 0} \\frac{\\operatorname{sen}(u)}{u} = 1 \\] Haciendo el cambio $u = x + 3$, cuando $x \\to -3$, se tiene que $u \\to 0$. Aplicamos el límite: \\[ \\lim_{x \\to -3} 6 \\cdot \\left( \\frac{\\operatorname{sen}(x + 3)}{x + 3} \\right)^2 = 6 \\cdot (1)^2 = 6 \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } 6} \\]', 40, '2025-07-15 18:34:01', '2025-07-15 18:34:01'),
(457, 253, '\\[ \\boxed{\\text{PASO 1: IDENTIFICAMOS EL LÍMITE LATERAL A EVALUAR}} \\]  Nos piden evaluar el siguiente límite lateral:  \\[ \\lim_{x \\to 3^+} \\frac{1}{x - 3} \\]  Esto indica que debemos analizar el comportamiento de la función cuando \\( x \\) se aproxima a 3 **por la derecha**, es decir, con valores **mayores** que 3.', 10, '2025-07-15 19:00:34', '2025-07-15 19:00:34'),
(458, 253, '\\[ \\boxed{\\text{PASO 2: CONSTRUIMOS UNA TABLA DE VALORES DESDE LA DERECHA}} \\]  Seleccionamos valores de \\( x \\) **ligeramente mayores** a 3 para observar cómo se comporta \\( \\frac{1}{x - 3} \\):  \\[ \\begin{array}{|c|c|} \\hline x & \\frac{1}{x - 3} \\\\ \\hline 3.1 & \\frac{1}{3.1 - 3} = \\frac{1}{0.1} = 10 \\\\ 3.01 & \\frac{1}{3.01 - 3} = \\frac{1}{0.01} = 100 \\\\ 3.001 & \\frac{1}{3.001 - 3} = \\frac{1}{0.001} = 1000 \\\\ 3.0001 & \\frac{1}{3.0001 - 3} = \\frac{1}{0.0001} = 10000 \\\\ \\hline \\end{array} \\]  Observamos que conforme \\( x \\to 3^+ \\), el denominador se acerca a cero **por valores positivos** y la fracción crece rápidamente hacia \\( +\\infty \\).', 20, '2025-07-15 19:00:34', '2025-07-15 19:00:34'),
(459, 253, '\\[ \\boxed{\\text{PASO 3: ANALIZAMOS EL COMPORTAMIENTO DEL LÍMITE}} \\]  Sabemos que:  \\[ x \\to 3^+ \\quad \\Rightarrow \\quad x - 3 \\to 0^+ \\]  Por lo tanto:  \\[ \\frac{1}{x - 3} \\to +\\infty \\]   \\[ \\boxed{\\text{RESULTADO FINAL: } \\lim_{x \\to 3^+} \\frac{1}{x - 3} = +\\infty} \\]', 30, '2025-07-15 19:00:34', '2025-07-15 19:00:34'),
(463, 255, '\\[ \\boxed{\\text{PASO 1: IDENTIFICAMOS EL LÍMITE LATERAL A EVALUAR}} \\]  Nos piden evaluar el siguiente límite lateral:  \\[ \\lim_{x \\to 3^-} \\frac{1}{x - 3} \\]  Esto indica que debemos analizar el comportamiento de la función cuando \\( x \\) se aproxima a 3 **por la izquierda**, es decir, con valores **menores** que 3.', 10, '2025-07-15 19:10:11', '2025-07-15 19:10:11'),
(464, 255, '\\[ \\boxed{\\text{PASO 2: CONSTRUIMOS UNA TABLA DE VALORES DESDE LA IZQUIERDA}} \\]  Seleccionamos valores de \\( x \\) **ligeramente menores** a 3 para observar cómo se comporta \\( \\frac{1}{x - 3} \\):  \\[ \\begin{array}{|c|c|} \\hline x & \\frac{1}{x - 3} \\\\ \\hline 2.9 & \\frac{1}{2.9 - 3} = \\frac{1}{-0.1} = -10 \\\\ 2.99 & \\frac{1}{2.99 - 3} = \\frac{1}{-0.01} = -100 \\\\ 2.999 & \\frac{1}{2.999 - 3} = \\frac{1}{-0.001} = -1000 \\\\ 2.9999 & \\frac{1}{2.9999 - 3} = \\frac{1}{-0.0001} = -10000 \\\\ \\hline \\end{array} \\]  Observamos que conforme \\( x \\to 3^- \\), el denominador se acerca a cero **por valores negativos** y la fracción decrece rápidamente hacia \\( -\\infty \\).', 20, '2025-07-15 19:10:11', '2025-07-15 19:10:11'),
(465, 255, '\\[ \\boxed{\\text{PASO 3: ANALIZAMOS EL COMPORTAMIENTO DEL LÍMITE}} \\]  Sabemos que:  \\[ x \\to 3^- \\quad \\Rightarrow \\quad x - 3 \\to 0^- \\]  Por lo tanto:  \\[ \\frac{1}{x - 3} \\to -\\infty \\]   \\[ \\boxed{\\text{RESULTADO FINAL: } \\lim_{x \\to 3^-} \\frac{1}{x - 3} = -\\infty} \\]', 30, '2025-07-15 19:10:11', '2025-07-15 19:10:11'),
(466, 256, '\\[ \\boxed{\\text{PASO 1: IDENTIFICAMOS LA FORMA INDETERMINADA}} \\]  Sustituimos directamente \\( x = 3 \\):  \\[ \\frac{(3^2 - 9)\\cos(3 - 3)}{3^2 + 3 - 12} = \\frac{(9 - 9)\\cos(0)}{9 + 3 - 12} = \\frac{0 \\cdot \\cos(0)}{0} = \\frac{0}{0} \\]  Obtenemos una forma indeterminada, por lo tanto, debemos simplificar la expresión.', 10, '2025-07-15 19:30:22', '2025-07-15 19:30:22'),
(467, 256, '\\[ \\boxed{\\text{PASO 2: FACTORIZAMOS NUMERADOR Y DENOMINADOR}} \\]  Numerador: \\( x^2 - 9 = (x - 3)(x + 3) \\)   Denominador: \\( x^2 + x - 12 = (x - 3)(x + 4) \\)  Sustituimos en la expresión original:  \\[ \\frac{(x - 3)(x + 3)\\cos(x - 3)}{(x - 3)(x + 4)} \\]', 20, '2025-07-15 19:30:22', '2025-07-15 19:30:22'),
(468, 256, '\\[ \\boxed{\\text{PASO 3: CANCELAMOS EL FACTOR COMÚN}} \\]  Cancelamos el factor común \\( x - 3 \\) en numerador y denominador:  \\[ = \\frac{(x + 3)\\cos(x - 3)}{x + 4} \\]', 30, '2025-07-15 19:30:22', '2025-07-15 19:30:22'),
(469, 256, '\\[ \\boxed{\\text{PASO 4: APLICAMOS EL LÍMITE}} \\]  Evaluamos directamente la expresión simplificada en \\( x = 3 \\):  \\[ \\frac{(3 + 3)\\cos(3 - 3)}{3 + 4} = \\frac{6 \\cdot \\cos(0)}{7} \\]  \\[ \\cos(0) = 1 \\Rightarrow \\frac{6}{7} \\approx 0.857 \\]   \\[ \\boxed{\\text{RESULTADO FINAL: } 0.857} \\]', 40, '2025-07-15 19:30:22', '2025-07-15 19:30:22'),
(470, 257, '\\[ \\boxed{\\text{PASO 1: IDENTIFICACIÓN DE LA FORMA INDETERMINADA}} \\]  Sustituimos directamente $x = 2$ en la expresión original: \\[ \\frac{8\\operatorname{sen}^2(2 - 2)}{2^2 - 4(2) + 4} = \\frac{8\\operatorname{sen}^2(0)}{4 - 8 + 4} = \\frac{8 \\cdot 0}{0} = \\frac{0}{0} \\] Obtenemos una forma indeterminada $\\left(\\frac{0}{0}\\right)$, por lo tanto, debemos simplificar la expresión antes de aplicar el límite.', 10, '2025-07-15 20:52:54', '2025-07-15 20:52:54'),
(471, 257, '\\[ \\boxed{\\text{PASO 2: FACTORIZACIÓN DEL DENOMINADOR}} \\]  El trinomio del denominador es un trinomio cuadrado perfecto: \\[ x^2 - 4x + 4 = (x - 2)^2 \\] Sustituimos esta factorización en la expresión original: \\[ \\frac{8\\operatorname{sen}^2(x - 2)}{(x - 2)^2} \\]', 20, '2025-07-15 20:52:54', '2025-07-15 20:52:54'),
(472, 257, '\\[ \\boxed{\\text{PASO 3: REESCRITURA DE LA EXPRESIÓN USANDO UNA IDENTIDAD}} \\]  Recordamos la identidad trigonométrica $\\operatorname{sen}^2(\\theta) = [\\operatorname{sen}(\\theta)]^2$. Aplicándola a nuestro término $\\operatorname{sen}^2(x - 2)$: \\[ \\operatorname{sen}^2(x - 2) = [\\operatorname{sen}(x - 2)]^2 \\] Entonces, podemos reescribir la expresión de la siguiente manera: \\[ \\frac{8[\\operatorname{sen}(x - 2)]^2}{(x - 2)^2} = 8 \\cdot \\left( \\frac{\\operatorname{sen}(x - 2)}{x - 2} \\right)^2 \\]', 30, '2025-07-15 20:52:54', '2025-07-15 20:52:54'),
(473, 257, '\\[ \\boxed{\\text{PASO 4: APLICACIÓN DEL LÍMITE USANDO UNA IDENTIDAD NOTABLE}} \\]  Sabemos que el límite fundamental trigonométrico es: \\[ \\lim_{u \\to 0} \\frac{\\operatorname{sen}(u)}{u} = 1 \\] Para aplicar esta identidad, hacemos un cambio de variable. Sea $u = x - 2$. Cuando $x \\to 2$, entonces $u \\to 2 - 2$, lo que significa $u \\to 0$. Aplicamos el límite a nuestra expresión reescrita: \\[ \\lim_{x \\to 2} 8 \\cdot \\left( \\frac{\\operatorname{sen}(x - 2)}{x - 2} \\right)^2 \\] Sustituyendo el valor del límite notable: \\[ = 8 \\cdot (1)^2 = 8 \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } 8} \\]', 40, '2025-07-15 20:52:54', '2025-07-15 20:52:54'),
(478, 258, '\\[ \\boxed{\\text{PASO 1: IDENTIFICAMOS LA FORMA INDETERMINADA}} \\]  Sustituimos directamente \\( x = 1 \\):  \\[ \\frac{6\\tan(1 - 1)}{1^2 - 1} = \\frac{6\\tan(0)}{1 - 1} = \\frac{6 \\cdot 0}{0} = \\frac{0}{0} \\]  Obtenemos una forma indeterminada, por lo tanto, debemos simplificar la expresión.', 10, '2025-07-15 22:38:57', '2025-07-15 22:38:57'),
(479, 258, '\\[ \\boxed{\\text{PASO 2: FACTORIZAMOS EL DENOMINADOR}} \\]  Reconocemos que:  \\[ x^2 - 1 = (x - 1)(x + 1) \\]  Sustituimos en la expresión original:  \\[ \\frac{6\\tan(x - 1)}{(x - 1)(x + 1)} \\]', 20, '2025-07-15 22:38:57', '2025-07-15 22:38:57'),
(480, 258, '\\[ \\boxed{\\text{PASO 3: REESCRIBIMOS USANDO IDENTIDAD Y SEPARAMOS EL LÍMITE}} \\]  Agrupamos términos para utilizar la identidad:  \\[ \\frac{6\\tan(x - 1)}{(x - 1)(x + 1)} = 6 \\cdot \\left( \\frac{\\tan(x - 1)}{x - 1} \\right) \\cdot \\frac{1}{x + 1} \\]  \\[ \\boxed{\\text{PASO 4: APLICAMOS EL LÍMITE}} \\]  Recordamos que:  \\[ \\lim_{u \\to 0} \\frac{\\tan(u)}{u} = 1 \\]  Sea \\( u = x - 1 \\), entonces cuando \\( x \\to 1 \\), se tiene que \\( u \\to 0 \\). Aplicamos el límite:  \\[ \\lim_{x \\to 1} 6 \\cdot \\left( \\frac{\\tan(x - 1)}{x - 1} \\right) \\cdot \\frac{1}{x + 1} = 6 \\cdot 1 \\cdot \\frac{1}{2} = 3 \\] \\[ \\boxed{\\text{RESULTADO FINAL: } 3} \\]', 30, '2025-07-15 22:38:57', '2025-07-15 22:38:57'),
(481, 259, '\\[ \\boxed{\\text{PASO 1: IDENTIFICAMOS LA FORMA INDETERMINADA}} \\]  Sustituimos directamente \\( x = -5 \\):  \\[ \\frac{4\\tan(-5 + 5)}{(-5)^2 - 25} = \\frac{4\\tan(0)}{25 - 25} = \\frac{4 \\cdot 0}{0} = \\frac{0}{0} \\]  Obtenemos una forma indeterminada, por lo tanto, debemos simplificar la expresión.', 30, '2025-07-15 22:51:10', '2025-07-15 22:51:10'),
(482, 259, '\\[ \\boxed{\\text{PASO 2: FACTORIZAMOS EL DENOMINADOR}} \\]  Reconocemos que:  \\[ x^2 - 25 = (x - 5)(x + 5) \\]  Sustituimos en la expresión original:  \\[ \\frac{4\\tan(x + 5)}{(x - 5)(x + 5)} \\]', 20, '2025-07-15 22:51:10', '2025-07-15 22:51:10'),
(483, 259, '\\[ \\boxed{\\text{PASO 3: REESCRIBIMOS USANDO IDENTIDAD Y SEPARAMOS EL LÍMITE}} \\]  Agrupamos términos para utilizar una identidad trigonométrica:  \\[ \\frac{4\\tan(x + 5)}{(x + 5)(x - 5)} = 4 \\cdot \\left( \\frac{\\tan(x + 5)}{x + 5} \\right) \\cdot \\frac{1}{x - 5} \\] \\[ \\boxed{\\text{PASO 4: APLICAMOS EL LÍMITE}} \\]  Sabemos que:  \\[ \\lim_{u \\to 0} \\frac{\\tan(u)}{u} = 1 \\]  Sea \\( u = x + 5 \\), entonces cuando \\( x \\to -5 \\), se tiene que \\( u \\to 0 \\). Aplicamos el límite:  \\[ \\lim_{x \\to -5} 4 \\cdot \\left( \\frac{\\tan(x + 5)}{x + 5} \\right) \\cdot \\frac{1}{x - 5} = 4 \\cdot 1 \\cdot \\frac{1}{-10} = \\frac{-2}{5} \\] \\[ \\boxed{\\text{RESULTADO FINAL: } \\frac{-2}{5} \\approx -0.4} \\]', 30, '2025-07-15 22:51:10', '2025-07-15 22:51:10'),
(484, 260, '\\[ \\boxed{\\text{PASO 1: IDENTIFICAMOS EL TIPO DE LÍMITE}} \\]  Sustituimos directamente \\( x = 0 \\):  \\[ \\frac{0 \\cdot \\cot(0)}{2(0)^2 - 1} = \\frac{0 \\cdot \\infty}{-1} \\]  Tenemos un producto de \\( 0 \\cdot \\infty \\), que también es una forma indeterminada. Por lo tanto, reescribiremos la expresión para poder aplicar una identidad trigonométrica útil.', 10, '2025-07-15 23:05:13', '2025-07-15 23:05:13'),
(485, 260, '\\[ \\boxed{\\text{PASO 2: REESCRIBIMOS USANDO IDENTIDADES TRIGONOMÉTRICAS}} \\]  Recordamos que \\( \\cot x = \\frac{\\cos x}{\\sin x} \\), por lo tanto:  \\[ \\frac{x \\cot x}{2x^2 - 1} = \\frac{x \\cdot \\frac{\\cos x}{\\sin x}}{2x^2 - 1} = \\frac{x \\cos x}{(2x^2 - 1) \\sin x} \\]', 20, '2025-07-15 23:05:13', '2025-07-15 23:05:13'),
(486, 260, '\\[ \\boxed{\\text{PASO 3: SEPARAMOS Y APLICAMOS LÍMITES}} \\]  Dividimos la expresión en partes que podemos evaluar:  \\[ \\lim_{x \\to 0} \\frac{x \\cos x}{(2x^2 - 1)\\sin x} \\]  Sabemos que:  - \\( \\lim_{x \\to 0} \\cos x = 1 \\) - \\( \\lim_{x \\to 0} \\frac{x}{\\sin x} = 1 \\) - \\( \\lim_{x \\to 0} (2x^2 - 1) = -1 \\)  Entonces, reescribimos:  \\[ \\lim_{x \\to 0} \\frac{x}{\\sin x} \\cdot \\frac{\\cos x}{2x^2 - 1} \\]  Aplicamos los límites:  \\[ 1 \\cdot \\frac{1}{-1} = -1 \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } -1} \\]', 30, '2025-07-15 23:05:13', '2025-07-15 23:05:13'),
(487, 261, '\\[ \\boxed{\\text{PASO 1: IDENTIFICAMOS EL TIPO DE LÍMITE}} \\]  Sustituimos directamente \\( x = 0 \\):  \\[ \\frac{3(0)^2 \\cot(0)}{(0)^2 + 0} = \\frac{0 \\cdot \\infty}{0} = \\frac{0}{0} \\]  Obtenemos una forma indeterminada, por lo tanto, debemos simplificar la expresión. \\[ \\boxed{\\text{PASO 2: REESCRIBIMOS USANDO IDENTIDADES TRIGONOMÉTRICAS}} \\]  Recordamos que \\( \\cot x = \\frac{\\cos x}{\\sin x} \\), entonces:  \\[ \\frac{3x^2 \\cot x}{x^2 + x} = \\frac{3x^2 \\cdot \\frac{\\cos x}{\\sin x}}{x^2 + x} = \\frac{3x^2 \\cos x}{(x^2 + x)\\sin x} \\]', 10, '2025-07-16 00:22:35', '2025-07-16 00:22:35'),
(488, 261, '\\[ \\boxed{\\text{PASO 3: SEPARAMOS EN FACTORES PARA USAR LÍMITES CONOCIDOS}} \\]  Reescribimos la expresión para facilitar la aplicación del límite:  \\[ \\frac{3x^2 \\cos x}{(x^2 + x)\\sin x} = \\frac{x^2}{x^2 + x} \\cdot \\frac{\\cos x}{\\sin x} \\] \\[ \\boxed{\\text{PASO 4: APLICAMOS EL LÍMITE}} \\]  Sabemos que:  - \\( \\lim_{x \\to 0} \\frac{x^2}{x^2 + x} = \\lim_{x \\to 0} \\frac{x^2}{x(x + 1)} = \\lim_{x \\to 0} \\frac{x}{x + 1} = 0 \\) - \\( \\lim_{x \\to 0} \\frac{\\cos x}{\\sin x} = \\infty \\)  Entonces el producto es:  \\[ \\lim_{x \\to 0} \\left( \\frac{x^2}{x^2 + x} \\cdot \\frac{\\cos x}{\\sin x} \\right) = 0 \\cdot \\infty \\]  Tenemos otra forma indeterminada, así que debemos buscar una mejor estrategia.', 20, '2025-07-16 00:22:35', '2025-07-16 00:22:35'),
(489, 261, '\\[ \\boxed{\\text{PASO 5: FACTORIZAMOS Y USAMOS IDENTIDADES}} \\]  Multiplicamos y dividimos entre \\( x \\):  \\[ \\frac{3x^2 \\cot x}{x^2 + x} = \\frac{3x \\cdot x \\cdot \\cot x}{x(x + 1)} = \\frac{3x \\cdot \\cot x}{x + 1} \\]  Usamos la identidad: \\( \\lim_{x \\to 0} x \\cot x = 1 \\)  Entonces:  \\[ \\lim_{x \\to 0} \\frac{3x \\cot x}{x + 1} = \\frac{3 \\cdot 1}{1} = 3 \\] \\[ \\boxed{\\text{RESULTADO FINAL: } 3} \\]', 30, '2025-07-16 00:22:35', '2025-07-16 00:22:35'),
(490, 262, '\\[ \\boxed{\\text{PASO 1: IDENTIFICAMOS LA FORMA INDETERMINADA}} \\]  Sustituimos directamente \\( x = 2 \\):  \\[ \\frac{(2^3 - 8)\\sec(2 - 2)}{2^2 - 4} = \\frac{(8 - 8)\\sec(0)}{4 - 4} = \\frac{0 \\cdot \\sec(0)}{0} = \\frac{0}{0} \\]  Obtenemos una forma indeterminada, por lo tanto, debemos simplificar la expresión.', 20, '2025-07-16 03:07:58', '2025-07-16 03:07:58'),
(491, 262, '\\[ \\boxed{\\text{PASO 2: FACTORIZAMOS EL NUMERADOR Y DENOMINADOR}} \\]  Reconocemos que el numerador es una diferencia de cubos:  \\[ x^3 - 8 = (x - 2)(x^2 + 2x + 4), \\quad x^2 - 4 = (x - 2)(x + 2) \\]  Sustituimos en la expresión original:  \\[ \\frac{(x - 2)(x^2 + 2x + 4)\\sec(x - 2)}{(x - 2)(x + 2)} \\]', 30, '2025-07-16 03:07:58', '2025-07-16 03:07:58'),
(492, 262, '\\[ \\boxed{\\text{PASO 3: CANCELAMOS EL FACTOR COMÚN}} \\]  Cancelamos el factor común \\( x - 2 \\) en numerador y denominador:  \\[ \\frac{(x^2 + 2x + 4)\\sec(x - 2)}{x + 2} \\] \\[ \\boxed{\\text{PASO 4: APLICAMOS EL LÍMITE}} \\]  Evaluamos directamente la expresión simplificada en \\( x = 2 \\):  \\[ \\frac{(2^2 + 2(2) + 4)\\sec(2 - 2)}{2 + 2} = \\frac{(4 + 4 + 4)\\sec(0)}{4} = \\frac{12 \\cdot 1}{4} \\] \\[ \\boxed{\\text{RESULTADO FINAL: } 3} \\]', 30, '2025-07-16 03:07:58', '2025-07-16 03:07:58'),
(493, 263, '\\[ \\boxed{\\text{PASO 1: IDENTIFICAMOS LA FORMA INDETERMINADA}} \\]  Sustituimos directamente \\( x = 3 \\):  \\[ \\frac{(3^2 - 9)\\sec(3 - 3)}{3^3 - 27} = \\frac{(9 - 9)\\sec(0)}{27 - 27} = \\frac{0 \\cdot \\sec(0)}{0} = \\frac{0}{0} \\]  Obtenemos una forma indeterminada, por lo tanto, debemos simplificar la expresión.', 10, '2025-07-17 01:45:30', '2025-07-17 01:45:30'),
(494, 263, '\\[ \\boxed{\\text{PASO 2: FACTORIZAMOS EL NUMERADOR Y DENOMINADOR}} \\]  Factorizamos el numerador como una diferencia de cuadrados:  \\[ x^2 - 9 = (x - 3)(x + 3) \\]  Y el denominador como una diferencia de cubos:  \\[ x^3 - 27 = (x - 3)(x^2 + 3x + 9) \\]  Sustituimos en la expresión original:  \\[ \\frac{(x - 3)(x + 3)\\sec(x - 3)}{(x - 3)(x^2 + 3x + 9)} \\]', 20, '2025-07-17 01:45:30', '2025-07-17 01:45:30'),
(495, 263, '\\[ \\boxed{\\text{PASO 3: CANCELAMOS EL FACTOR COMÚN}} \\]  Cancelamos el factor común \\( x - 3 \\) en numerador y denominador:  \\[ \\frac{(x + 3)\\sec(x - 3)}{x^2 + 3x + 9} \\]  \\[ \\boxed{\\text{PASO 4: APLICAMOS EL LÍMITE}} \\]  Evaluamos directamente la expresión simplificada en \\( x = 3 \\):  \\[ \\frac{(3 + 3)\\sec(3 - 3)}{3^2 + 3(3) + 9} = \\frac{6 \\cdot \\sec(0)}{9 + 9 + 9} = \\frac{6 \\cdot 1}{27} \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } \\frac{2}{9} \\approx 0.222} \\]', 30, '2025-07-17 01:45:30', '2025-07-17 01:45:30');
INSERT INTO `problem_hints` (`id`, `problem_id`, `hint`, `sequence_id`, `created_at`, `updated_at`) VALUES
(496, 264, '\\[ \\boxed{\\text{PASO 1: IDENTIFICAMOS LA FORMA INDETERMINADA}} \\]  Sustituimos directamente \\( x = -1 \\):  \\[ \\frac{3(-1) + 3}{((-1)^2 + 2(-1) + 1)\\csc(-1 + 1)} = \\frac{-3 + 3}{(1 - 2 + 1)\\csc(0)} = \\frac{0}{0 \\cdot \\csc(0)} = \\frac{0}{0} \\]  Obtenemos una forma indeterminada, por lo tanto, debemos simplificar la expresión.', 20, '2025-07-17 04:00:39', '2025-07-17 04:00:39'),
(497, 264, '\\[ \\boxed{\\text{PASO 2: FACTORIZAMOS EL DENOMINADOR}} \\]  Factorizamos el trinomio cuadrado perfecto del denominador:  \\[ x^2 + 2x + 1 = (x + 1)^2 \\]  Sustituimos en la expresión original:  \\[ \\frac{3x + 3}{(x + 1)^2 \\csc(x + 1)} \\]  Observamos que el numerador también se puede factorizar:  \\[ 3x + 3 = 3(x + 1) \\]  Sustituimos ambas factorizaciones:  \\[ \\frac{3(x + 1)}{(x + 1)^2 \\csc(x + 1)} \\]  \\[ \\boxed{\\text{PASO 3: CANCELAMOS EL FACTOR COMÚN}} \\]  Cancelamos un factor \\( x + 1 \\) en numerador y denominador:  \\[ \\frac{3}{(x + 1)\\csc(x + 1)} \\]', 30, '2025-07-17 04:00:39', '2025-07-17 04:00:39'),
(498, 264, '\\[ \\boxed{\\text{PASO 4: APLICAMOS EL LÍMITE}} \\]  Evaluamos directamente en \\( x = -1 \\):  \\[ \\frac{3}{(-1 + 1)\\csc(-1 + 1)} = \\frac{3}{0 \\cdot \\csc(0)} = \\frac{3}{0} \\]  Dado que el numerador es un número diferente de cero y el denominador tiende a cero, analizamos el **comportamiento del límite** por la izquierda y por la derecha para determinar si el límite existe.  Cuando \\( x \\to -1 \\), se tiene que \\( x + 1 \\to 0 \\), entonces:  \\[ \\csc(x + 1) = \\frac{1}{\\sin(x + 1)} \\to \\infty \\]  Así que:  \\[ (x + 1)\\csc(x + 1) \\to 1 \\quad \\text{cuando } x \\to -1 \\]  Por lo tanto, el límite se vuelve:  \\[ \\lim_{x \\to -1} \\frac{3}{(x + 1)\\csc(x + 1)} = \\frac{3}{1} = 3 \\] \\[ \\boxed{\\text{RESULTADO FINAL: } 3} \\]', 30, '2025-07-17 04:00:39', '2025-07-17 04:00:39'),
(499, 265, '\\[ \\boxed{\\text{PASO 1: IDENTIFICAMOS LA FORMA INDETERMINADA}} \\]  Sustituimos directamente \\( x = -1 \\):  \\[ \\frac{2(-1) - 4}{((-1)^2 - 4(-1) + 4)\\csc(-1 - 2)} = \\frac{-2 - 4}{(1 + 4 + 4)\\csc(-3)} = \\frac{-6}{9 \\cdot \\csc(-3)} \\]  Sabemos que \\( \\csc(-3) = \\frac{1}{\\sin(-3)} = -\\frac{1}{\\sin(3)} \\), por lo tanto:  \\[ \\frac{-6}{9 \\cdot (-1/\\sin(3))} = \\frac{-6}{-9/\\sin(3)} = \\frac{-6 \\cdot \\sin(3)}{-9} = \\frac{6 \\cdot \\sin(3)}{9} \\]', 10, '2025-07-17 04:14:33', '2025-07-17 04:14:33'),
(500, 265, '\\[ \\boxed{\\text{PASO 2: SIMPLIFICAMOS LA EXPRESIÓN}} \\]  Simplificamos el resultado anterior:  \\[ \\frac{6 \\cdot \\sin(3)}{9} = \\frac{2 \\cdot \\sin(3)}{3} \\]', 20, '2025-07-17 04:14:33', '2025-07-17 04:14:33'),
(501, 265, '\\[ \\boxed{\\text{PASO 3: EVALUAMOS CON CALCULADORA}} \\]  Calculamos el valor numérico:  \\[ \\sin(3) \\approx 0.1411 \\quad \\Rightarrow \\quad \\frac{2 \\cdot 0.1411}{3} = \\frac{0.2822}{3} \\approx 0.094 \\] \\[ \\boxed{\\text{RESULTADO FINAL: } \\frac{2\\sin(3)}{3} \\approx 0.094} \\]', 30, '2025-07-17 04:14:33', '2025-07-17 04:14:33'),
(502, 266, '\\[ \\boxed{\\text{PASO 1: IDENTIFICAMOS EL COMPORTAMIENTO DEL DENOMINADOR}} \\]  Queremos calcular el límite de la función  \\[ f(x) = \\frac{1}{x^2 - 4} \\]  cuando \\( x \\to 2^- \\), es decir, cuando \\( x \\) se aproxima a 2 por la izquierda (valores menores que 2).   Notamos que:  \\[ x^2 - 4 = (x - 2)(x + 2) \\]  Cuando \\( x \\to 2^- \\), el término \\( x - 2 \\) es **ligeramente negativo**, y \\( x + 2 \\) es **positivo**, por lo tanto el producto \\( (x - 2)(x + 2) \\) será **ligeramente negativo**.', 10, '2025-07-17 04:31:05', '2025-07-17 04:31:05'),
(503, 266, '\\[ \\boxed{\\text{PASO 2: CONSTRUIMOS UNA TABLA DE VALORES}} \\]  Aproximamos el valor de la función para valores de \\( x \\) cercanos a 2 por la izquierda:  \\[ \\begin{array}{|c|c|} \\hline x & \\frac{1}{x^2 - 4} \\\\ \\hline 1.9 & \\frac{1}{(1.9)^2 - 4} = \\frac{1}{3.61 - 4} = \\frac{1}{-0.39} \\approx -2.564 \\\\ 1.99 & \\frac{1}{(1.99)^2 - 4} = \\frac{1}{3.9601 - 4} = \\frac{1}{-0.0399} \\approx -25.063 \\\\ 1.999 & \\frac{1}{(1.999)^2 - 4} = \\frac{1}{3.996001 - 4} = \\frac{1}{-0.003999} \\approx -250.06 \\\\ 1.9999 & \\frac{1}{(1.9999)^2 - 4} = \\frac{1}{3.99960001 - 4} = \\frac{1}{-0.00039999} \\approx -2500.06 \\\\ \\hline \\end{array} \\]', 20, '2025-07-17 04:31:05', '2025-07-17 04:31:05'),
(504, 266, '\\[ \\boxed{\\text{PASO 3: ANALIZAMOS LA TENDENCIA DE LOS VALORES}} \\]  Observamos que cuando \\( x \\) se aproxima a 2 por la izquierda, los valores de \\( f(x) \\) se vuelven cada vez **más negativos** y crecen en magnitud.  \\[ \\boxed{\\text{RESULTADO FINAL: } \\lim_{x \\to 2^-} \\frac{1}{x^2 - 4} = -\\infty} \\]', 30, '2025-07-17 04:31:05', '2025-07-17 04:31:05'),
(505, 267, '\\[ \\boxed{\\text{PASO 1: IDENTIFICAMOS EL COMPORTAMIENTO DEL DENOMINADOR}} \\]  Queremos calcular el límite de la función  \\[ f(x) = \\frac{1}{x^2 - 4} \\]  cuando \\( x \\to 2^+ \\), es decir, cuando \\( x \\) se aproxima a 2 por la derecha (valores mayores que 2).   Sabemos que:  \\[ x^2 - 4 = (x - 2)(x + 2) \\]  Cuando \\( x \\to 2^+ \\), el término \\( x - 2 \\) es **ligeramente positivo**, y \\( x + 2 \\) también es **positivo**, por lo tanto el producto \\( (x - 2)(x + 2) \\) será **ligeramente positivo**.', 10, '2025-07-17 04:44:00', '2025-07-17 04:44:00'),
(506, 267, '\\[ \\boxed{\\text{PASO 2: CONSTRUIMOS UNA TABLA DE VALORES}} \\]  Aproximamos el valor de la función para valores de \\( x \\) cercanos a 2 por la derecha:  \\[ \\begin{array}{|c|c|} \\hline x & \\frac{1}{x^2 - 4} \\\\ \\hline 2.1 & \\frac{1}{(2.1)^2 - 4} = \\frac{1}{4.41 - 4} = \\frac{1}{0.41} \\approx 2.439 \\\\ 2.01 & \\frac{1}{(2.01)^2 - 4} = \\frac{1}{4.0401 - 4} = \\frac{1}{0.0401} \\approx 24.938 \\\\ 2.001 & \\frac{1}{(2.001)^2 - 4} = \\frac{1}{4.004001 - 4} = \\frac{1}{0.004001} \\approx 249.94 \\\\ 2.0001 & \\frac{1}{(2.0001)^2 - 4} = \\frac{1}{4.00040001 - 4} = \\frac{1}{0.00040001} \\approx 2499.94 \\\\ \\hline \\end{array} \\]', 20, '2025-07-17 04:44:00', '2025-07-17 04:44:00'),
(507, 267, '\\[ \\boxed{\\text{PASO 3: ANALIZAMOS LA TENDENCIA DE LOS VALORES}} \\]  Observamos que cuando \\( x \\) se aproxima a 2 por la derecha, los valores de \\( f(x) \\) se vuelven **cada vez más grandes** positivamente.  \\[ \\boxed{\\text{RESULTADO FINAL: } \\lim_{x \\to 2^+} \\frac{1}{x^2 - 4} = +\\infty} \\]', 30, '2025-07-17 04:44:00', '2025-07-17 04:44:00'),
(508, 268, '\\[ \\boxed{\\text{PASO 1: IDENTIFICAMOS LA FORMA DE LA FUNCIÓN}} \\]  Tenemos la función:  \\[ f(x) = \\frac{1}{x} \\]  Y queremos evaluar el siguiente límite lateral:  \\[ \\lim_{x \\to +\\infty} \\frac{1}{x} \\]', 10, '2025-07-18 00:42:21', '2025-07-18 00:42:21'),
(509, 268, '\\[ \\boxed{\\text{PASO 2: ANALIZAMOS EL COMPORTAMIENTO DE LA FUNCIÓN}} \\]  Cuando \\( x \\to +\\infty \\), el denominador crece sin límite. Como el numerador es constante (1), la fracción se hace cada vez más pequeña positivamente:  \\[ \\frac{1}{x} \\to 0^+ \\quad \\text{(positivo y pequeño)} \\]', 20, '2025-07-18 00:42:21', '2025-07-18 00:42:21'),
(510, 268, '\\[ \\boxed{\\text{PASO 3: CONCLUSIÓN}} \\]  Por lo tanto, el valor del límite es:  \\[ \\lim_{x \\to +\\infty} \\frac{1}{x} = 0 \\]', 30, '2025-07-18 00:42:21', '2025-07-18 00:42:21'),
(511, 269, '\\[ \\boxed{\\text{PASO 1: IDENTIFICAMOS LA FORMA DE LA FUNCIÓN}} \\]  Tenemos la función:  \\[ f(x) = \\frac{1}{x} \\]  Y queremos evaluar el siguiente límite lateral:  \\[ \\lim_{x \\to -\\infty} \\frac{1}{x} \\]', 10, '2025-07-18 00:47:51', '2025-07-18 00:47:51'),
(512, 269, '\\[ \\boxed{\\text{PASO 2: ANALIZAMOS EL COMPORTAMIENTO DE LA FUNCIÓN}} \\]  Cuando \\( x \\to -\\infty \\), el denominador se hace muy grande en valor absoluto pero negativo. Como el numerador es constante (1), la fracción se hace cada vez más pequeña en magnitud, pero negativa:  \\[ \\frac{1}{x} \\to 0^- \\quad \\text{(negativo y pequeño)} \\]', 20, '2025-07-18 00:47:51', '2025-07-18 00:47:51'),
(513, 269, '\\[ \\boxed{\\text{PASO 3: CONCLUSIÓN}} \\]  Por lo tanto, el valor del límite es:  \\[ \\lim_{x \\to -\\infty} \\frac{1}{x} = 0 \\]', 30, '2025-07-18 00:47:51', '2025-07-18 00:47:51'),
(517, 270, '\\[ \\boxed{\\text{PASO 1: IDENTIFICAMOS LA FORMA DE LA FUNCIÓN}} \\]  Tenemos la función racional:  \\[ f(x) = \\frac{3x - 5}{9x + 7} \\]  Queremos calcular el siguiente límite:  \\[ \\lim_{x \\to \\infty} \\frac{3x - 5}{9x + 7} \\]', 10, '2025-07-18 01:48:43', '2025-07-18 01:48:43'),
(518, 270, '\\[ \\boxed{\\text{PASO 2: DIVIDIMOS ENTRE LA MAYOR POTENCIA DE } x} \\]  Tanto en el numerador como en el denominador, la mayor potencia de \\( x \\) es \\( x \\). Dividimos todos los términos entre \\( x \\):  \\[ \\lim_{x \\to \\infty} \\frac{3x - 5}{9x + 7} =  \\lim_{x \\to \\infty} \\frac{x(3 - \\frac{5}{x})}{x(9 + \\frac{7}{x})} \\]  Cancelamos el factor común \\( x \\):  \\[ = \\lim_{x \\to \\infty} \\frac{3 - \\frac{5}{x}}{9 + \\frac{7}{x}} \\]', 20, '2025-07-18 01:48:43', '2025-07-18 01:48:43'),
(519, 270, '\\[ \\boxed{\\text{PASO 3: EVALUAMOS EL LÍMITE}} \\]  Cuando \\( x \\to \\infty \\), se tiene que \\( \\frac{5}{x} \\to 0 \\) y \\( \\frac{7}{x} \\to 0 \\). Entonces:  \\[ \\frac{3 - \\frac{5}{x}}{9 + \\frac{7}{x}} \\to \\frac{3 - 0}{9 + 0} = \\frac{3}{9} = \\frac{1}{3} \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } \\frac{1}{3} \\approx 0.333} \\]', 30, '2025-07-18 01:48:43', '2025-07-18 01:48:43'),
(520, 271, '\\[ \\boxed{\\text{PASO 1: IDENTIFICAMOS EL LÍMITE A CALCULAR}} \\]  \\[ \\lim_{x \\to \\infty} \\frac{2x - 8}{x + 5} \\]', 10, '2025-07-19 05:48:41', '2025-07-19 05:48:41'),
(521, 271, '\\[ \\boxed{\\text{PASO 2: DIVIDIMOS NUMERADOR Y DENOMINADOR ENTRE } x} \\]  Dividimos todos los términos entre \\( x \\), la mayor potencia presente en el denominador:  \\[ = \\lim_{x \\to \\infty} \\frac{x(2 - \\frac{8}{x})}{x(1 + \\frac{5}{x})} \\]  Simplificamos los factores comunes:  \\[ = \\lim_{x \\to \\infty} \\frac{2 - \\frac{8}{x}}{1 + \\frac{5}{x}} \\]', 20, '2025-07-19 05:48:41', '2025-07-19 05:48:41'),
(522, 271, '\\[ \\boxed{\\text{PASO 3: APLICAMOS EL LÍMITE}} \\]  Cuando \\( x \\to \\infty \\), se cumple que \\( \\frac{8}{x} \\to 0 \\) y \\( \\frac{5}{x} \\to 0 \\). Por lo tanto:  \\[ = \\frac{2 - 0}{1 + 0} = \\frac{2}{1} = 2 \\] \\[ \\boxed{\\text{RESULTADO FINAL: } \\lim_{x \\to \\infty} \\frac{2x - 8}{x + 5} = 2} \\]', 30, '2025-07-19 05:48:41', '2025-07-19 05:48:41'),
(523, 272, '\\[ \\boxed{\\text{PASO 1: IDENTIFICAMOS EL LÍMITE A CALCULAR}} \\]  \\[ \\lim_{x \\to \\infty} \\frac{4x^3 - 7}{3x^2 + 2x} \\]', 10, '2025-07-19 15:50:11', '2025-07-19 15:50:11'),
(524, 272, '\\[ \\boxed{\\text{PASO 2: IDENTIFICAMOS LOS GRADOS DEL POLINOMIO}} \\]  El numerador tiene grado 3 y el denominador grado 2. Como el grado del numerador es mayor que el del denominador:  \\[ \\lim_{x \\to \\infty} \\frac{4x^3 - 7}{3x^2 + 2x} = \\infty \\]  Esto se debe a que para valores de \\( x \\) muy grandes, el término dominante en el numerador es \\( 4x^3 \\) y en el denominador es \\( 3x^2 \\), por lo que la expresión crece sin límite.', 20, '2025-07-19 15:50:11', '2025-07-19 15:50:11'),
(525, 272, '\\[ \\boxed{\\text{PASO 3: DIVIDIMOS ENTRE LA MAYOR POTENCIA DEL DENOMINADOR}} \\]  Dividimos numerador y denominador entre \\( x^2 \\):  \\[ = \\lim_{x \\to \\infty} \\frac{4x^3 - 7}{3x^2 + 2x} = \\lim_{x \\to \\infty} \\frac{x^2\\left(4x - \\frac{7}{x^2}\\right)}{x^2(3 + \\frac{2}{x})} \\]  Simplificamos los factores comunes:  \\[ = \\lim_{x \\to \\infty} \\frac{4x - \\frac{7}{x^2}}{3 + \\frac{2}{x}} \\]', 30, '2025-07-19 15:50:11', '2025-07-19 15:50:11'),
(526, 272, '\\[ \\boxed{\\text{PASO 4: APLICAMOS EL LÍMITE}} \\]  Cuando \\( x \\to \\infty \\), se cumple que \\( \\frac{7}{x^2} \\to 0 \\) y \\( \\frac{2}{x} \\to 0 \\). Por lo tanto:  \\[ = \\frac{4x - 0}{3 + 0} = \\frac{4x}{3} \\to \\infty \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } \\lim_{x \\to \\infty} \\frac{4x^3 - 7}{3x^2 + 2x} = +\\infty} \\]', 40, '2025-07-19 15:50:11', '2025-07-19 15:50:11'),
(527, 273, '\\[ \\boxed{\\text{PASO 1: IDENTIFICAR LA FORMA DE LA FUNCIÓN}} \\]  La función es una exponencial con base constante \\(3\\) y exponente una función cuadrática: \\[ f(x) = a^{u(x)} \\quad \\text{donde } a = 3 \\text{ y } u(x) = x^2 - 9x \\]', 10, '2025-07-19 18:54:08', '2025-07-19 18:54:08'),
(528, 273, '\\[ \\boxed{\\text{PASO 2: REGLA DE LA DERIVADA EXPONENCIAL}} \\]  La derivada de una función de la forma \\( a^{u(x)} \\) es: \\[ \\frac{d}{dx} \\left[ a^{u(x)} \\right] = a^{u(x)} \\cdot \\ln(a) \\cdot u\'(x) \\]  Aplicamos esta fórmula:  \\[ u(x) = x^2 - 9x \\Rightarrow u\'(x) = 2x - 9 \\]', 20, '2025-07-19 18:54:08', '2025-07-19 18:54:08'),
(529, 273, '\\[ \\boxed{\\text{PASO 3: SUSTITUCIÓN EN LA FÓRMULA}} \\]  \\[ f\'(x) = 3^{x^2 - 9x} \\cdot \\ln(3) \\cdot (2x - 9) \\]', 30, '2025-07-19 18:54:08', '2025-07-19 18:54:08'),
(530, 273, '\\[ \\boxed{\\text{RESULTADO FINAL: } f\'(x) = 3^{x^2 - 9x} \\cdot \\ln(3) \\cdot (2x - 9)} \\]', 40, '2025-07-19 18:54:08', '2025-07-19 18:54:08'),
(531, 274, '\\[ \\boxed{\\text{PASO 1: IDENTIFICAR LA ESTRUCTURA DE LA FUNCIÓN}} \\]  La función es una exponencial con base constante \\(5\\) y un exponente que depende de \\(x\\):   \\[ f(x) = a^{u(x)}, \\quad \\text{donde } a = 5 \\text{ y } u(x) = x^3 + x \\]', 10, '2025-07-19 19:14:48', '2025-07-19 19:14:48'),
(532, 274, '\\[ \\boxed{\\text{PASO 2: USAR LA REGLA DE DERIVACIÓN DE EXPONENCIALES}} \\]  Recordamos que: \\[ \\frac{d}{dx}[a^{u(x)}] = a^{u(x)} \\cdot \\ln(a) \\cdot u\'(x) \\]', 20, '2025-07-19 19:14:48', '2025-07-19 19:14:48'),
(533, 274, '\\[ \\boxed{\\text{PASO 3: DERIVAR EL EXPONENTE } u(x)} \\]  \\[ u(x) = x^3 + x \\Rightarrow u\'(x) = 3x^2 + 1 \\]', 30, '2025-07-19 19:14:48', '2025-07-19 19:14:48'),
(534, 274, '\\[ \\boxed{\\text{PASO 4: SUSTITUIR EN LA FÓRMULA DE DERIVACIÓN}} \\]  \\[ f\'(x) = 5^{x^3 + x} \\cdot \\ln(5) \\cdot (3x^2 + 1) \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } f\'(x) = 5^{x^3 + x} \\cdot \\ln(5) \\cdot (3x^2 + 1)} \\]', 40, '2025-07-19 19:14:48', '2025-07-19 19:14:48'),
(535, 275, '\\[ \\boxed{\\text{PASO 1: IDENTIFICAR LA ESTRUCTURA DE LA FUNCIÓN}} \\]  La función es de la forma exponencial con base \\( e \\), y exponente \\( u(x) = \\csc(x^3) \\). Sabemos que:  \\[ \\frac{d}{dx}\\left(e^{u(x)}\\right) = e^{u(x)} \\cdot u\'(x) \\]', 10, '2025-07-19 19:33:16', '2025-07-19 19:33:16'),
(536, 275, '\\[ \\boxed{\\text{PASO 2: DERIVAR EL EXPONENTE } u(x) = \\csc(x^3)} \\]  Recordamos que: \\[ \\frac{d}{dx}[\\csc(u)] = -\\csc(u) \\cdot \\cot(u) \\cdot u\' \\]  Aplicamos la regla de la cadena con \\( u = x^3 \\Rightarrow u\' = 3x^2 \\), por lo tanto: \\[ \\frac{d}{dx}[\\csc(x^3)] = -\\csc(x^3) \\cdot \\cot(x^3) \\cdot 3x^2 \\]', 20, '2025-07-19 19:33:16', '2025-07-19 19:33:16'),
(537, 275, '\\[ \\boxed{\\text{PASO 3: SUSTITUIR EN LA DERIVADA DE LA FUNCIÓN EXPONENCIAL}} \\]  \\[ f\'(x) = e^{\\csc(x^3)} \\cdot \\left[ -\\csc(x^3) \\cdot \\cot(x^3) \\cdot 3x^2 \\right] \\]  \\[ f\'(x) = -3x^2 \\cdot e^{\\csc(x^3)} \\cdot \\csc(x^3) \\cdot \\cot(x^3) \\]', 30, '2025-07-19 19:33:16', '2025-07-19 19:33:16'),
(538, 275, '\\[ \\boxed{\\text{RESULTADO FINAL: } f\'(x) = -3x^2 \\cdot e^{\\csc(x^3)} \\cdot \\csc(x^3) \\cdot \\cot(x^3)} \\]', 40, '2025-07-19 19:33:16', '2025-07-19 19:33:16'),
(542, 278, '\\[ \\boxed{\\text{PASO 1: IDENTIFICAMOS EL LÍMITE A CALCULAR}} \\]  \\[ \\lim_{x \\to \\infty} \\frac{7x^4 + 5}{9 - 3x} \\]', 10, '2025-07-19 20:45:02', '2025-07-19 20:45:02'),
(543, 278, '\\[ \\boxed{\\text{PASO 2: IDENTIFICAMOS LOS GRADOS DEL POLINOMIO}} \\]  El grado del numerador es 4 y el del denominador es 1. Como el grado del numerador es mayor al del denominador, el cociente crecerá sin límite. Analizaremos el signo para determinar si el límite tiende a \\( +\\infty \\) o a \\( -\\infty \\).', 20, '2025-07-19 20:45:02', '2025-07-19 20:45:02'),
(544, 278, '\\[ \\boxed{\\text{PASO 3: ANALIZAMOS SIGNO Y COMPORTAMIENTO AL INFINITO}} \\]  Para valores muy grandes de \\( x \\):  \\[ 7x^4 + 5 > 0 \\quad \\text{(siempre positivo)} \\\\ 9 - 3x < 0 \\quad \\text{(tiende a } -\\infty \\text{)} \\]  Por lo tanto:  \\[ \\frac{\\text{positivo}}{\\text{negativo}} = \\text{negativo} \\Rightarrow \\text{la expresión tiende a } -\\infty \\]   \\[ \\boxed{\\text{RESULTADO FINAL:} \\lim_{x \\to \\infty} \\frac{7x^4 + 5}{9 - 3x} = -\\infty} \\]', 30, '2025-07-19 20:45:02', '2025-07-19 20:45:02'),
(545, 279, '\\[ \\boxed{\\text{PASO 1: IDENTIFICAMOS EL LÍMITE A CALCULAR}} \\]  \\[ \\lim_{x \\to \\infty} \\frac{5x^3 - 9x^5}{3x^5 + 4x^2 - 8} \\]', 10, '2025-07-19 21:07:03', '2025-07-19 21:07:03'),
(546, 279, '\\[ \\boxed{\\text{PASO 2: IDENTIFICAMOS EL GRADO MÁS ALTO}} \\]  El grado más alto tanto en el numerador como en el denominador es 5:  \\[ \\frac{-9x^5 + 5x^3}{3x^5 + 4x^2 - 8} \\]  Sacamos factor común \\( x^5 \\) en numerador y denominador:  \\[ \\frac{x^5(-9 + \\frac{5}{x^2})}{x^5(3 + \\frac{4}{x^3} - \\frac{8}{x^5})} \\]', 20, '2025-07-19 21:07:03', '2025-07-19 21:07:03'),
(547, 279, '\\[ \\boxed{\\text{PASO 3: SIMPLIFICAMOS LA EXPRESIÓN}} \\]  Cancelamos el factor común \\( x^5 \\):  \\[ \\lim_{x \\to \\infty} \\frac{-9 + \\frac{5}{x^2}}{3 + \\frac{4}{x^3} - \\frac{8}{x^5}} \\]', 30, '2025-07-19 21:07:03', '2025-07-19 21:07:03'),
(548, 279, '\\[ \\boxed{\\text{PASO 4: APLICAMOS EL LÍMITE}} \\]  Cuando \\( x \\to \\infty \\), los términos con potencias negativas tienden a cero:  \\[ \\frac{-9 + 0}{3 + 0 - 0} = \\frac{-9}{3} = -3 \\]  \\[ \\boxed{\\text{RESULTADO FINAL:} \\lim_{x \\to \\infty} \\frac{5x^3 - 9x^5}{3x^5 + 4x^2 - 8} = -3} \\]', 40, '2025-07-19 21:07:03', '2025-07-19 21:07:03'),
(549, 280, '\\[ \\boxed{\\text{PASO 1: IDENTIFICAMOS EL LÍMITE A CALCULAR}} \\]  \\[ \\lim_{x \\to \\infty} \\frac{7x - 9x^2 - 3x^6}{6x^6 + 5x^4 - 4} \\]', 20, '2025-07-19 21:27:36', '2025-07-19 21:27:36'),
(550, 280, '\\[ \\boxed{\\text{PASO 2: IDENTIFICAMOS EL TÉRMINO DE MAYOR GRADO}} \\]  El término de mayor grado en el numerador es \\( -3x^6 \\), y en el denominador es \\( 6x^6 \\). Dividimos todos los términos entre \\( x^6 \\):  \\[ = \\lim_{x \\to \\infty} \\frac{\\frac{7}{x^5} - \\frac{9}{x^4} - 3}{6 + \\frac{5}{x^2} - \\frac{4}{x^6}} \\]', 30, '2025-07-19 21:27:36', '2025-07-19 21:27:36'),
(551, 280, '\\[ \\boxed{\\text{PASO 3: APLICAMOS EL LÍMITE A CADA TÉRMINO}} \\]  Cuando \\( x \\to \\infty \\), los términos con potencias negativas tienden a 0:  \\[ = \\frac{0 - 0 - 3}{6 + 0 - 0} = \\frac{-3}{6} = -\\frac{1}{2} \\]  \\[ \\boxed{\\text{RESULTADO FINAL:} \\lim_{x \\to \\infty} \\frac{7x - 9x^2 - 3x^6}{6x^6 + 5x^4 - 4} = -\\frac{1}{2} = -0.5} \\]', 40, '2025-07-19 21:27:36', '2025-07-19 21:27:36'),
(552, 281, '\\[ \\boxed{\\text{PASO 1: ESCRIBIMOS LA DEFINICIÓN DE DERIVADA}} \\]  La derivada de una función \\( f(x) \\) por definición es:  \\[ f\'(x) = \\lim_{h \\to 0} \\frac{f(x + h) - f(x)}{h} \\]', 10, '2025-07-19 21:42:59', '2025-07-19 21:42:59'),
(553, 281, '\\[ \\boxed{\\text{PASO 2: SUSTITUIMOS LA FUNCIÓN EN LA DEFINICIÓN}} \\]  Dada la función:  \\[ f(x) = 4x^2 - 6x - 8 \\]  Evaluamos \\( f(x + h) \\):  \\[ f(x + h) = 4(x + h)^2 - 6(x + h) - 8 \\]  Expandimos los términos:  \\[ = 4(x^2 + 2xh + h^2) - 6x - 6h - 8 \\] \\[ = 4x^2 + 8xh + 4h^2 - 6x - 6h - 8 \\] \\[ \\boxed{\\text{PASO 3: SUSTITUIMOS EN LA FÓRMULA DE LA DERIVADA}} \\]  \\[ f\'(x) = \\lim_{h \\to 0} \\frac{f(x + h) - f(x)}{h} \\] \\[ = \\lim_{h \\to 0} \\frac{[4x^2 + 8xh + 4h^2 - 6x - 6h - 8] - [4x^2 - 6x - 8]}{h} \\]  Cancelamos términos comunes:  \\[ f\'(x) = \\lim_{h \\to 0} \\frac{8xh + 4h^2 - 6h}{h} \\]', 20, '2025-07-19 21:42:59', '2025-07-19 21:42:59'),
(554, 281, '\\[ \\boxed{\\text{PASO 4: SIMPLIFICAMOS LA EXPRESIÓN}} \\]  Factorizamos \\( h \\) en el numerador:  \\[ = \\lim_{h \\to 0} \\frac{h(8x + 4h - 6)}{h} \\]  Cancelamos \\( h \\):  \\[ = \\lim_{h \\to 0} (8x + 4h - 6) \\] \\[ \\boxed{\\text{PASO 5: APLICAMOS EL LÍMITE}} \\]  \\[ f\'(x) = 8x - 6 \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } f\'(x) = 8x - 6} \\]', 30, '2025-07-19 21:42:59', '2025-07-19 21:42:59'),
(555, 282, '\\[ \\boxed{\\text{PASO 1: ESCRIBIMOS LA DEFINICIÓN DE DERIVADA}} \\]  La derivada de una función \\( f(x) \\) por definición es:  \\[ f\'(x) = \\lim_{h \\to 0} \\frac{f(x + h) - f(x)}{h} \\]', 10, '2025-07-19 21:57:06', '2025-07-19 21:57:06'),
(556, 282, '\\[ \\boxed{\\text{PASO 2: SUSTITUIMOS LA FUNCIÓN EN LA DEFINICIÓN}} \\]  Dada la función:  \\[ f(x) = 3x^2 + 4x - 5 \\]  Evaluamos \\( f(x + h) \\):  \\[ f(x + h) = 3(x + h)^2 + 4(x + h) - 5 \\]  Expandimos los términos:  \\[ = 3(x^2 + 2xh + h^2) + 4x + 4h - 5 \\] \\[ = 3x^2 + 6xh + 3h^2 + 4x + 4h - 5 \\]    \\[ \\boxed{\\text{PASO 3: SUSTITUIMOS EN LA FÓRMULA DE LA DERIVADA}} \\]  \\[ f\'(x) = \\lim_{h \\to 0} \\frac{f(x + h) - f(x)}{h} \\] \\[ = \\lim_{h \\to 0} \\frac{[3x^2 + 6xh + 3h^2 + 4x + 4h - 5] - [3x^2 + 4x - 5]}{h} \\]  Cancelamos términos comunes:  \\[ f\'(x) = \\lim_{h \\to 0} \\frac{6xh + 3h^2 + 4h}{h} \\]', 20, '2025-07-19 21:57:06', '2025-07-19 21:57:06'),
(557, 282, '\\[ \\boxed{\\text{PASO 4: SIMPLIFICAMOS LA EXPRESIÓN}} \\]  Factorizamos \\( h \\) en el numerador:  \\[ = \\lim_{h \\to 0} \\frac{h(6x + 3h + 4)}{h} \\]  Cancelamos \\( h \\):  \\[ = \\lim_{h \\to 0} (6x + 3h + 4) \\]   \\[ \\boxed{\\text{PASO 5: APLICAMOS EL LÍMITE}} \\]  \\[ f\'(x) = 6x + 4 \\]    \\[ \\boxed{\\text{RESULTADO FINAL: } f\'(x) = 6x + 4} \\]', 30, '2025-07-19 21:57:06', '2025-07-19 21:57:06'),
(558, 283, '\\[ \\boxed{\\text{PASO 1: ESCRIBIMOS LA DEFINICIÓN DE DERIVADA}} \\]  La derivada de una función \\( g(x) \\) por definición es:  \\[ g\'(x) = \\lim_{h \\to 0} \\frac{g(x + h) - g(x)}{h} \\]', 10, '2025-07-19 22:52:53', '2025-07-19 22:52:53'),
(559, 283, '\\[ \\boxed{\\text{PASO 2: SUSTITUIMOS LA FUNCIÓN EN LA DEFINICIÓN}} \\]  Dada la función:  \\[ g(x) = 5x^3 - 2 \\]  Evaluamos \\( g(x + h) \\):  \\[ g(x + h) = 5(x + h)^3 - 2 \\]  Desarrollamos el cubo:  \\[ (x + h)^3 = x^3 + 3x^2h + 3xh^2 + h^3 \\]  Entonces:  \\[ g(x + h) = 5(x^3 + 3x^2h + 3xh^2 + h^3) - 2 \\] \\[ = 5x^3 + 15x^2h + 15xh^2 + 5h^3 - 2 \\]   \\[ \\boxed{\\text{PASO 3: SUSTITUIMOS EN LA FÓRMULA DE LA DERIVADA}} \\]  \\[ g\'(x) = \\lim_{h \\to 0} \\frac{[5x^3 + 15x^2h + 15xh^2 + 5h^3 - 2] - [5x^3 - 2]}{h} \\]  Cancelamos términos comunes:  \\[ g\'(x) = \\lim_{h \\to 0} \\frac{15x^2h + 15xh^2 + 5h^3}{h} \\]', 20, '2025-07-19 22:52:53', '2025-07-19 22:52:53'),
(560, 283, '\\[ \\boxed{\\text{PASO 4: SIMPLIFICAMOS LA EXPRESIÓN}} \\]  Factorizamos \\( h \\) en el numerador:  \\[ = \\lim_{h \\to 0} \\frac{h(15x^2 + 15xh + 5h^2)}{h} \\]  Cancelamos \\( h \\):  \\[ = \\lim_{h \\to 0} (15x^2 + 15xh + 5h^2) \\]   \\[ \\boxed{\\text{PASO 5: APLICAMOS EL LÍMITE}} \\]  \\[ g\'(x) = 15x^2 \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } g\'(x) = 15x^2} \\]', 30, '2025-07-19 22:52:53', '2025-07-19 22:52:53'),
(561, 284, '\\[ \\boxed{\\text{PASO 1: ESCRIBIMOS LA DEFINICIÓN DE DERIVADA}} \\]  La derivada de una función \\( h(x) \\) por definición es:  \\[ h\'(x) = \\lim_{h \\to 0} \\frac{h(x + h) - h(x)}{h} \\]', 10, '2025-07-19 23:29:23', '2025-07-19 23:29:23'),
(562, 284, '\\[ \\boxed{\\text{PASO 2: SUSTITUIMOS LA FUNCIÓN EN LA DEFINICIÓN}} \\]  Dada la función:  \\[ h(x) = 5x^3 - 4x^2 + 2x - 6 \\]  Evaluamos \\( h(x + h) \\):  \\[ h(x + h) = 5(x + h)^3 - 4(x + h)^2 + 2(x + h) - 6 \\]  Desarrollamos los binomios:  \\[ (x + h)^3 = x^3 + 3x^2h + 3xh^2 + h^3 \\] \\[ (x + h)^2 = x^2 + 2xh + h^2 \\]  Sustituimos:  \\[ h(x + h) = 5(x^3 + 3x^2h + 3xh^2 + h^3) - 4(x^2 + 2xh + h^2) + 2x + 2h - 6 \\]  Distribuimos:  \\[ = 5x^3 + 15x^2h + 15xh^2 + 5h^3 - 4x^2 - 8xh - 4h^2 + 2x + 2h - 6 \\]    \\[ \\boxed{\\text{PASO 3: SUSTITUIMOS EN LA FÓRMULA DE LA DERIVADA}} \\]  \\[ h\'(x) = \\lim_{h \\to 0} \\frac{[5x^3 + 15x^2h + 15xh^2 + 5h^3 - 4x^2 - 8xh - 4h^2 + 2x + 2h - 6] - [5x^3 - 4x^2 + 2x - 6]}{h} \\]  Cancelamos los términos comunes:  \\[ h\'(x) = \\lim_{h \\to 0} \\frac{15x^2h + 15xh^2 + 5h^3 - 8xh - 4h^2 + 2h}{h} \\]', 20, '2025-07-19 23:29:23', '2025-07-19 23:29:23'),
(563, 284, '\\[ \\boxed{\\text{PASO 4: SIMPLIFICAMOS LA EXPRESIÓN}} \\]  Agrupamos términos:  \\[ = \\lim_{h \\to 0} \\frac{h(15x^2 + 15xh + 5h^2 - 8x - 4h + 2)}{h} \\]  Cancelamos el \\( h \\):  \\[ = \\lim_{h \\to 0} (15x^2 + 15xh + 5h^2 - 8x - 4h + 2) \\]  ---  \\[ \\boxed{\\text{PASO 5: APLICAMOS EL LÍMITE}} \\]  \\[ h\'(x) = 15x^2 - 8x + 2 \\]   \\[ \\boxed{\\text{RESULTADO FINAL: } h\'(x) = 15x^2 - 8x + 2} \\]', 30, '2025-07-19 23:29:23', '2025-07-19 23:29:23'),
(564, 286, '\\[ \\boxed{\\text{PASO 1: ESCRIBIMOS LA DEFINICIÓN DE DERIVADA}} \\]  La derivada de una función \\( y = f(x) \\) por definición es:  \\[ f\'(x) = \\lim_{h \\to 0} \\frac{f(x + h) - f(x)}{h} \\]  \\[ \\boxed{\\text{PASO 2: SUSTITUIMOS LA FUNCIÓN EN LA DEFINICIÓN}} \\]  Dada la función:  \\[ f(x) = \\frac{2}{x - 1} \\]  Evaluamos \\( f(x + h) \\):  \\[ f(x + h) = \\frac{2}{(x + h) - 1} = \\frac{2}{x + h - 1} \\]  Entonces sustituimos en la definición:  \\[ f\'(x) = \\lim_{h \\to 0} \\frac{\\frac{2}{x + h - 1} - \\frac{2}{x - 1}}{h} \\]', 10, '2025-07-20 00:28:45', '2025-07-20 00:28:45'),
(565, 286, '\\[ \\boxed{\\text{PASO 3: REDUCIMOS LA EXPRESIÓN}} \\]  Hacemos la resta del numerador usando mínimo común denominador:  \\[ = \\lim_{h \\to 0} \\frac{\\left( \\frac{2(x - 1) - 2(x + h - 1)}{(x + h - 1)(x - 1)} \\right)}{h} \\]  Expandimos el numerador:  \\[ = \\lim_{h \\to 0} \\frac{\\frac{2(x - 1) - 2x - 2h + 2}{(x + h - 1)(x - 1)}}{h} \\]  Simplificamos el numerador:  \\[ 2(x - 1) - 2x - 2h + 2 = 2x - 2 - 2x - 2h + 2 = -2h \\]  Sustituimos:  \\[ = \\lim_{h \\to 0} \\frac{\\frac{-2h}{(x + h - 1)(x - 1)}}{h} \\]   \\[ \\boxed{\\text{PASO 4: SIMPLIFICAMOS LA EXPRESIÓN}} \\]  Multiplicamos por el inverso de \\( h \\):  \\[ = \\lim_{h \\to 0} \\left( \\frac{-2h}{(x + h - 1)(x - 1)} \\cdot \\frac{1}{h} \\right) \\]  Cancelamos \\( h \\):  \\[ = \\lim_{h \\to 0} \\frac{-2}{(x + h - 1)(x - 1)} \\]', 20, '2025-07-20 00:28:45', '2025-07-20 00:28:45'),
(566, 286, '\\[ \\boxed{\\text{PASO 5: APLICAMOS EL LÍMITE}} \\]  Sustituimos \\( h = 0 \\):  \\[ f\'(x) = \\frac{-2}{(x - 1)^2} \\]   \\[ \\boxed{\\text{RESULTADO FINAL: } f\'(x) = \\frac{-2}{(x - 1)^2}} \\]', 30, '2025-07-20 00:28:45', '2025-07-20 00:28:45'),
(567, 287, '\\[ \\boxed{\\text{PASO 1: ESCRIBIMOS LA DEFINICIÓN DE DERIVADA}} \\]  La derivada de una función \\( f(x) \\) por definición es:  \\[ f\'(x) = \\lim_{h \\to 0} \\frac{f(x + h) - f(x)}{h} \\]  \\[ \\boxed{\\text{PASO 2: SUSTITUIMOS LA FUNCIÓN EN LA DEFINICIÓN}} \\]  Dada la función:  \\[ f(x) = \\frac{4}{x + 2} \\]  Evaluamos \\( f(x + h) \\):  \\[ f(x + h) = \\frac{4}{(x + h) + 2} = \\frac{4}{x + h + 2} \\]  Sustituimos en la definición:  \\[ f\'(x) = \\lim_{h \\to 0} \\frac{\\frac{4}{x + h + 2} - \\frac{4}{x + 2}}{h} \\]', 10, '2025-07-20 00:43:27', '2025-07-20 00:43:27'),
(568, 287, '\\[ \\boxed{\\text{PASO 3: REDUCIMOS LA EXPRESIÓN}} \\]  Utilizamos mínimo común denominador en el numerador:  \\[ = \\lim_{h \\to 0} \\frac{4\\left(\\frac{(x + 2) - (x + h + 2)}{(x + h + 2)(x + 2)}\\right)}{h} \\]  Simplificamos el numerador:  \\[ (x + 2) - (x + h + 2) = -h \\]  \\[ = \\lim_{h \\to 0} \\frac{4\\left(\\frac{-h}{(x + h + 2)(x + 2)}\\right)}{h} \\]   \\[ \\boxed{\\text{PASO 4: SIMPLIFICAMOS LA EXPRESIÓN}} \\]  Multiplicamos por el inverso de \\( h \\):  \\[ = \\lim_{h \\to 0} \\left( \\frac{-4h}{(x + h + 2)(x + 2)} \\cdot \\frac{1}{h} \\right) \\]  Cancelamos \\( h \\):  \\[ = \\lim_{h \\to 0} \\frac{-4}{(x + h + 2)(x + 2)} \\]', 20, '2025-07-20 00:43:27', '2025-07-20 00:43:27'),
(569, 287, '\\[ \\boxed{\\text{PASO 5: APLICAMOS EL LÍMITE}} \\]  Sustituimos \\( h = 0 \\):  \\[ f\'(x) = \\frac{-4}{(x + 2)^2} \\]  \\[ \\boxed{\\text{RESULTADO FINAL: } f\'(x) = \\frac{-4}{(x + 2)^2}} \\]', 30, '2025-07-20 00:43:27', '2025-07-20 00:43:27'),
(573, 289, '\\[ \\boxed{\\text{PASO 1: ESCRIBIMOS LA DEFINICIÓN DE DERIVADA}} \\]  La derivada de una función \\( f(x) \\) por definición es:  \\[ f\'(x) = \\lim_{h \\to 0} \\frac{f(x+h) - f(x)}{h} \\]', 10, '2025-07-20 01:27:18', '2025-07-20 01:27:18'),
(574, 289, '\\[ \\boxed{\\text{PASO 2: SUSTITUIMOS LA FUNCIÓN EN LA DEFINICIÓN}} \\]  Dada la función:  \\[ f(x) = \\sqrt{x} \\]  Sustituimos en la fórmula:  \\[ f\'(x) = \\lim_{h \\to 0} \\frac{\\sqrt{x+h} - \\sqrt{x}}{h} \\]', 20, '2025-07-20 01:27:18', '2025-07-20 01:27:18'),
(575, 289, '\\[ \\boxed{\\text{PASO 3: RACIONALIZAMOS EL NUMERADOR}} \\]  Multiplicamos por el conjugado del numerador:  \\[ f\'(x) = \\lim_{h \\to 0} \\frac{\\sqrt{x+h} - \\sqrt{x}}{h} \\cdot \\frac{\\sqrt{x+h} + \\sqrt{x}}{\\sqrt{x+h} + \\sqrt{x}} \\]  Aplicamos identidad notable \\( (a - b)(a + b) = a^2 - b^2 \\):  \\[ = \\lim_{h \\to 0} \\frac{(x+h) - x}{h(\\sqrt{x+h} + \\sqrt{x})} \\]  \\[ = \\lim_{h \\to 0} \\frac{h}{h(\\sqrt{x+h} + \\sqrt{x})} \\]    \\[ \\boxed{\\text{PASO 4: CANCELAMOS h Y APLICAMOS EL LÍMITE}} \\]  Cancelamos \\( h \\):  \\[ = \\lim_{h \\to 0} \\frac{1}{\\sqrt{x+h} + \\sqrt{x}} \\]  Aplicamos el límite:  \\[ f\'(x) = \\frac{1}{2\\sqrt{x}} \\]   \\[ \\boxed{\\text{RESULTADO FINAL:} \\quad f\'(x) = \\frac{1}{2\\sqrt{x}}} \\]', 30, '2025-07-20 01:27:18', '2025-07-20 01:27:18'),
(576, 290, '\\[ \\boxed{\\text{PASO 1: IDENTIFICAMOS LA FUNCIÓN Y SU INCREMENTO}} \\]  La función dada es:  \\[ y = f(x) = x^2 - 3x + 1 \\]  El incremento de la función \\( \\Delta y \\) cuando la variable \\( x \\) cambia a \\( x + \\Delta x \\), se define como:  \\[ \\Delta y = f(x + \\Delta x) - f(x) \\]', 10, '2025-07-20 01:52:09', '2025-07-20 01:52:09'),
(577, 290, '\\[ \\boxed{\\text{PASO 2: EVALUAMOS } f(x + \\Delta x)} \\]  Sustituimos en la función:  \\[ f(x + \\Delta x) = (x + \\Delta x)^2 - 3(x + \\Delta x) + 1 \\]  Expandimos los términos:  \\[ = x^2 + 2x\\Delta x + (\\Delta x)^2 - 3x - 3\\Delta x + 1 \\]', 20, '2025-07-20 01:52:09', '2025-07-20 01:52:09'),
(578, 290, '\\[ \\boxed{\\text{PASO 3: CALCULAMOS } \\Delta y = f(x + \\Delta x) - f(x)} \\]  Sabemos que:  \\[ f(x) = x^2 - 3x + 1 \\]  Entonces:  \\[ \\Delta y = \\left[ x^2 + 2x\\Delta x + (\\Delta x)^2 - 3x - 3\\Delta x + 1 \\right] - \\left[ x^2 - 3x + 1 \\right] \\]  Cancelamos los términos comunes:  \\[ \\Delta y = 2x\\Delta x + (\\Delta x)^2 - 3\\Delta x \\]  \\[ \\boxed{\\text{PASO 4: FACTORIZAMOS EL INCREMENTO}} \\]  Factor común \\( \\Delta x \\):  \\[ \\Delta y = \\Delta x \\left( 2x + \\Delta x - 3 \\right) \\]   \\[ \\boxed{\\text{RESULTADO FINAL: } \\Delta y = \\Delta x (2x + \\Delta x - 3)} \\]', 30, '2025-07-20 01:52:09', '2025-07-20 01:52:09'),
(579, 291, '\\[ \\boxed{\\text{PASO 1: ESCRIBIMOS LA FÓRMULA DEL INCREMENTO DE UNA FUNCIÓN}} \\]  El incremento de la función \\( f(x) \\) se define como:  \\[ \\Delta y = f(x + \\Delta x) - f(x) \\]', 10, '2025-07-20 02:07:50', '2025-07-20 02:07:50'),
(580, 291, '\\[ \\boxed{\\text{PASO 2: SUSTITUIMOS LA FUNCIÓN } f(x) = x^2 - 5x + 2} \\]  Calculamos \\( f(x + \\Delta x) \\):  \\[ f(x + \\Delta x) = (x + \\Delta x)^2 - 5(x + \\Delta x) + 2 \\]  Desarrollamos cada parte:  \\[ = x^2 + 2x\\Delta x + (\\Delta x)^2 - 5x - 5\\Delta x + 2 \\]', 20, '2025-07-20 02:07:50', '2025-07-20 02:07:50'),
(581, 291, '\\[ \\boxed{\\text{PASO 3: CALCULAMOS EL INCREMENTO}} \\]  \\[ \\Delta y = f(x + \\Delta x) - f(x) \\] \\[ = \\left[ x^2 + 2x\\Delta x + (\\Delta x)^2 - 5x - 5\\Delta x + 2 \\right] - \\left[ x^2 - 5x + 2 \\right] \\]  Cancelamos los términos comunes:  \\[ \\Delta y = 2x\\Delta x + (\\Delta x)^2 - 5\\Delta x \\]', 30, '2025-07-20 02:07:50', '2025-07-20 02:07:50'),
(582, 291, '\\[ \\boxed{\\text{PASO 4: FACTORIZAMOS EL RESULTADO}} \\]  \\[ \\Delta y = \\Delta x(2x + \\Delta x - 5) \\]   \\[ \\boxed{\\text{RESULTADO FINAL:} \\quad \\Delta y = \\Delta x(2x + \\Delta x - 5)} \\]', 40, '2025-07-20 02:07:50', '2025-07-20 02:07:50'),
(583, 292, '\\[ \\boxed{\\text{PASO 1: ESCRIBIMOS LA FÓRMULA DEL INCREMENTO DE UNA FUNCIÓN}} \\]  El incremento de la función \\( f(x) \\) se define como:  \\[ \\Delta y = f(x + \\Delta x) - f(x) \\]', 10, '2025-07-20 02:14:29', '2025-07-20 02:14:29'),
(584, 292, '\\[ \\boxed{\\text{PASO 2: SUSTITUIMOS LA FUNCIÓN } f(x) = 3x^2 + 2x - 5} \\]  Calculamos \\( f(x + \\Delta x) \\):  \\[ f(x + \\Delta x) = 3(x + \\Delta x)^2 + 2(x + \\Delta x) - 5 \\]  Desarrollamos cada parte:  \\[ = 3(x^2 + 2x\\Delta x + (\\Delta x)^2) + 2x + 2\\Delta x - 5 \\] \\[ = 3x^2 + 6x\\Delta x + 3(\\Delta x)^2 + 2x + 2\\Delta x - 5 \\]', 20, '2025-07-20 02:14:29', '2025-07-20 02:14:29'),
(585, 292, '\\[ \\boxed{\\text{PASO 3: CALCULAMOS EL INCREMENTO}} \\]  \\[ \\Delta y = f(x + \\Delta x) - f(x) \\]  \\[ = [3x^2 + 6x\\Delta x + 3(\\Delta x)^2 + 2x + 2\\Delta x - 5] - [3x^2 + 2x - 5] \\]  Cancelamos términos comunes:  \\[ \\Delta y = 6x\\Delta x + 3(\\Delta x)^2 + 2\\Delta x \\]', 30, '2025-07-20 02:14:29', '2025-07-20 02:14:29'),
(586, 292, '\\[ \\boxed{\\text{PASO 4: FACTORIZAMOS EL RESULTADO}} \\]  \\[ \\Delta y = \\Delta x(6x + 3\\Delta x + 2) \\]  \\[ \\boxed{\\text{RESULTADO FINAL:} \\quad \\Delta y = \\Delta x(6x + 3\\Delta x + 2)} \\]', 40, '2025-07-20 02:14:29', '2025-07-20 02:14:29'),
(587, 293, '\\[ \\boxed{\\text{PASO 1: ESCRIBIMOS LA FÓRMULA DEL INCREMENTO}} \\]  El incremento de una función \\( f(x) \\) está dado por:  \\[ \\Delta y = f(x + \\Delta x) - f(x) \\]', 10, '2025-07-20 02:22:03', '2025-07-20 02:22:03'),
(588, 293, '\\[ \\boxed{\\text{PASO 2: SUSTITUIMOS LA FUNCIÓN } f(x) = 2x^2 - 3x - 4} \\]  Calculamos \\( f(x + \\Delta x) \\):  \\[ f(x + \\Delta x) = 2(x + \\Delta x)^2 - 3(x + \\Delta x) - 4 \\]  Expandimos:  \\[ = 2(x^2 + 2x\\Delta x + (\\Delta x)^2) - 3x - 3\\Delta x - 4 \\] \\[ = 2x^2 + 4x\\Delta x + 2(\\Delta x)^2 - 3x - 3\\Delta x - 4 \\]', 20, '2025-07-20 02:22:03', '2025-07-20 02:22:03'),
(589, 293, '\\[ \\boxed{\\text{PASO 3: CALCULAMOS EL INCREMENTO}} \\]  \\[ \\Delta y = f(x + \\Delta x) - f(x) \\]  \\[ = [2x^2 + 4x\\Delta x + 2(\\Delta x)^2 - 3x - 3\\Delta x - 4] - [2x^2 - 3x - 4] \\]  Cancelamos términos comunes:  \\[ \\Delta y = 4x\\Delta x + 2(\\Delta x)^2 - 3\\Delta x \\]', 30, '2025-07-20 02:22:03', '2025-07-20 02:22:03'),
(590, 293, '\\[ \\boxed{\\text{PASO 4: FACTORIZAMOS EL INCREMENTO}} \\]  Factor común \\( \\Delta x \\):  \\[ \\Delta y = \\Delta x(4x + 2\\Delta x - 3) \\]   \\[ \\boxed{\\text{RESULTADO FINAL:} \\quad \\Delta y = \\Delta x(4x + 2\\Delta x - 3)} \\]', 40, '2025-07-20 02:22:03', '2025-07-20 02:22:03'),
(591, 294, 'Recuerda que la derivada de una constante es siempre cero.', 1, '2025-07-20 14:04:14', '2025-07-20 14:04:14'),
(592, 294, 'La constante 3 no depende de x, por lo que su tasa de cambio es cero.', 2, '2025-07-20 14:04:14', '2025-07-20 14:04:14'),
(593, 294, 'No apliques reglas de potencias ni producto: no son necesarias en este caso.', 3, '2025-07-20 14:04:14', '2025-07-20 14:04:14'),
(594, 295, 'Paso 1: Identifica que -5 es una constante. No contiene la variable x.', 1, '2025-07-20 22:41:28', '2025-07-20 22:41:28'),
(595, 295, 'Paso 2: La derivada de cualquier constante es igual a 0.', 2, '2025-07-20 22:41:28', '2025-07-20 22:41:28'),
(596, 295, 'Paso 3: Por lo tanto, la derivada de -5 es 0.', 3, '2025-07-20 22:41:28', '2025-07-20 22:41:28'),
(597, 296, 'Paso 1: \\( f(x) = 2x \\) es una función lineal de la forma \\( ax \\), donde \\( a = 2 \\).', 1, '2025-07-20 23:04:35', '2025-07-20 23:04:35'),
(598, 296, 'Paso 2: La derivada de \\( ax \\) respecto a \\( x \\) es simplemente \\( a \\).', 2, '2025-07-20 23:04:35', '2025-07-20 23:04:35'),
(599, 296, 'Paso 3: Por lo tanto, \\( f\'(x) = 2 \\).', 3, '2025-07-20 23:04:35', '2025-07-20 23:04:35'),
(600, 297, 'Paso 1: \\( f(x) = 5x \\) es una función lineal.', 1, '2025-07-20 23:14:25', '2025-07-20 23:14:25'),
(601, 297, 'Paso 2: La derivada de \\( ax \\), donde \\( a \\) es constante, es \\( a \\).', 2, '2025-07-20 23:14:25', '2025-07-20 23:14:25'),
(602, 297, 'Paso 3: Entonces \\( f\'(x) = 5 \\).', 3, '2025-07-20 23:14:25', '2025-07-20 23:14:25'),
(603, 299, 'Paso 1: Identifica que \\( f(x) = x^5 \\) es una potencia de la forma \\( x^n \\).', 1, '2025-07-20 23:26:41', '2025-07-20 23:26:41'),
(604, 299, 'Paso 2: Aplica la regla de potencias: \\( \\frac{d}{dx}x^n = nx^{n-1} \\).', 2, '2025-07-20 23:26:41', '2025-07-20 23:26:41'),
(605, 299, 'Paso 3: Sustituye \\( n = 5 \\): \\( f\'(x) = 5x^4 \\).', 3, '2025-07-20 23:26:41', '2025-07-20 23:26:41'),
(606, 300, 'Paso 1: \\( f(x) = x^3 \\) es una potencia del tipo \\( x^n \\) donde \\( n = 3 \\).', 1, '2025-07-20 23:53:29', '2025-07-20 23:53:29'),
(607, 300, 'Paso 2: La derivada de \\( x^n \\) se calcula con la fórmula \\( \\frac{d}{dx}x^n = nx^{n-1} \\).', 2, '2025-07-20 23:53:29', '2025-07-20 23:53:29'),
(608, 300, 'Paso 3: Aplicando la fórmula: \\( f\'(x) = 3x^2 \\).', 3, '2025-07-20 23:53:29', '2025-07-20 23:53:29'),
(609, 301, 'Paso 1: La derivada de una suma se obtiene derivando cada término por separado.', 1, '2025-07-21 00:01:25', '2025-07-21 00:01:25'),
(610, 301, 'Paso 2: Aplica la regla de potencia: \\( \\frac{d}{dx}x^n = nx^{n-1} \\) a cada término.', 2, '2025-07-21 00:01:25', '2025-07-21 00:01:25'),
(611, 301, 'Paso 3: Deriva cada término: \\( 4x^3 \\to 12x^2 \\), \\( 8x^2 \\to 16x \\), \\( -5x \\to -5 \\), \\( 9 \\to 0 \\).', 3, '2025-07-21 00:01:25', '2025-07-21 00:01:25'),
(612, 301, 'Paso 4: Junta las derivadas: \\( f\'(x) = 12x^2 + 16x - 5 \\).', 4, '2025-07-21 00:01:25', '2025-07-21 00:01:25'),
(613, 302, 'Paso 1: La derivada se obtiene aplicando la regla de potencias a cada término del polinomio.', 1, '2025-07-21 00:24:38', '2025-07-21 00:24:38'),
(614, 302, 'Paso 3: \\( 5x^3 \\to 15x^2 \\), \\( 13x^2 \\to 26x \\), \\( -2x \\to -2 \\), \\( 11 \\to 0 \\)', 3, '2025-07-21 00:24:38', '2025-07-21 00:29:34'),
(615, 302, 'Paso 2: Deriva término por término usando la fórmula \\( \\frac{d}{dx}x^n = nx^{n-1} \\).', 2, '2025-07-21 00:24:38', '2025-07-21 00:29:34'),
(616, 302, 'Paso 4: Resultado final: \\( f\'(x) = 15x^2 + 26x - 2 \\)', 4, '2025-07-21 00:24:38', '2025-07-21 00:24:38'),
(617, 303, 'Paso 1: La derivada de una suma es la suma de las derivadas de cada término.', 1, '2025-07-21 03:00:18', '2025-07-21 03:00:18'),
(618, 303, 'Paso 2: Aplica la fórmula \\( \\frac{d}{dx}x^n = nx^{n-1} \\) a cada término.', 2, '2025-07-21 03:00:18', '2025-07-21 03:00:18'),
(619, 303, 'Paso 3: \\( x^7 \\to 7x^6 \\), \\( -3x^5 \\to -15x^4 \\), \\( x \\to 1 \\), \\( -10 \\to 0 \\).', 3, '2025-07-21 03:00:18', '2025-07-21 03:00:18'),
(620, 303, 'Paso 4: Resultado final: \\( f\'(x) = 7x^6 - 15x^4 + 1 \\).', 4, '2025-07-21 03:00:18', '2025-07-21 03:00:18'),
(621, 304, '\\[ \\boxed{\\text{PASO 1: IDENTIFICACIÓN DE LA ESTRUCTURA DEL POLINOMIO}} \\]\\\\\r\nLa función \\( f(x) = x^9 + 4x^7 - x - 1 \\) contiene cuatro términos con potencias y constantes.', 1, '2025-07-21 12:33:59', '2025-07-21 12:33:59'),
(622, 304, '\\[ \\boxed{\\text{PASO 2: APLICAR LA REGLA DE POTENCIA}} \\]\\\\\r\nUtilizamos la fórmula: \\( \\frac{d}{dx}x^n = nx^{n-1} \\) en cada término.\\\\\r\n\\( x^9 \\to 9x^8 \\), \\( 4x^7 \\to 28x^6 \\), \\( -x \\to -1 \\), \\( -1 \\to 0 \\)', 2, '2025-07-21 12:33:59', '2025-07-21 12:33:59'),
(623, 304, '\\[ \\boxed{\\text{PASO 3: AGRUPAR LAS DERIVADAS}} \\]\\\\\r\nUnimos cada derivada obtenida: \\\\ \r\n\\[ f\'(x) = 9x^8 + 28x^6 - 1 \\]', 3, '2025-07-21 12:33:59', '2025-07-21 12:33:59'),
(624, 304, '\\[ \\boxed{\\text{RESULTADO FINAL: } f\'(x) = 9x^8 + 28x^6 - 1} \\]', 4, '2025-07-21 12:33:59', '2025-07-21 12:33:59'),
(625, 305, '\\[ \\boxed{\\text{PASO 1: REESCRIBIR LA FUNCIÓN COMO POTENCIA NEGATIVA}} \\] \\\\ \r\nLa función \\( f(x) = \\frac{1}{x^3} \\) puede reescribirse como \\( f(x) = x^{-3} \\).', 1, '2025-07-21 12:42:48', '2025-07-21 12:42:48'),
(626, 305, '\\[ \\boxed{\\text{PASO 2: APLICAR LA REGLA DE POTENCIAS}} \\] \\\\ \r\nRecordemos que: \\( \\frac{d}{dx}x^n = nx^{n-1} \\), \\\\ \r\npor lo tanto: \\( \\frac{d}{dx}x^{-3} = -3x^{-4} \\).', 2, '2025-07-21 12:42:48', '2025-07-21 12:42:48'),
(627, 305, '\\[ \\boxed{\\text{PASO 3: REEXPRESAR EN NOTACIÓN DE FRACCIÓN}} \\] \\\\ \r\nEl resultado \\( -3x^{-4} \\) equivale a \\( -\\frac{3}{x^4} \\).', 3, '2025-07-21 12:42:48', '2025-07-21 12:42:48'),
(628, 305, '\\[ \\boxed{\\text{RESULTADO FINAL: } f\'(x) = -\\frac{3}{x^4}} \\]', 4, '2025-07-21 12:42:48', '2025-07-21 12:42:48'),
(629, 306, 'Paso 1: \\[ f(x) = \\frac{1}{x^2} = x^{-2} \\]', 1, '2025-07-21 13:18:52', '2025-07-21 13:18:52'),
(630, 306, 'Paso 2: \\[ \\boxed{\\text{Aplica la regla de potencias}} \\] \n\n\\[ \\frac{d}{dx}(x^n) = nx^{n-1} \\]', 2, '2025-07-21 13:18:52', '2025-07-21 13:18:52'),
(631, 306, 'Paso 3: \\[ f\'(x) = -2x^{-3} \\]', 3, '2025-07-21 13:18:52', '2025-07-21 13:18:52'),
(632, 306, 'Paso 4: \\[ f\'(x) = -\\frac{2}{x^3} \\] es la forma simplificada y final.', 4, '2025-07-21 13:18:52', '2025-07-21 13:18:52'),
(633, 307, '\r\n\\[\r\n\\boxed{\\text{PASO 1: REESCRIBIR LA FUNCIÓN EN FORMA DE POTENCIA}}\r\n\\]\r\nLa función original es:\r\n\\[\r\nf(x) = \\frac{3}{2x^4} = \\frac{3}{2} \\cdot x^{-4}\r\n\\]\r\nAsí podemos aplicar la regla de derivación de potencias.\r\n', 1, '2025-07-21 13:29:40', '2025-07-21 13:29:40'),
(634, 307, '\r\n\\[\r\n\\boxed{\\text{PASO 2: APLICAR LA REGLA DE POTENCIAS}}\r\n\\]\r\nRecordamos la regla:\r\n\\[\r\n\\frac{d}{dx}(x^n) = nx^{n-1}\r\n\\]\r\nAquí: \\( f(x) = \\frac{3}{2}x^{-4} \\), entonces:\r\n\\[\r\nf\'(x) = \\frac{3}{2} \\cdot (-4)x^{-5}\r\n\\]\r\n', 2, '2025-07-21 13:29:40', '2025-07-21 13:29:40'),
(635, 307, '\r\n\\[\r\n\\boxed{\\text{PASO 3: SIMPLIFICAR LA EXPRESIÓN}}\r\n\\]\r\nMultiplicamos los coeficientes:\r\n\\[\r\n\\frac{3}{2} \\cdot (-4) = -6\r\n\\quad \\Rightarrow \\quad\r\nf\'(x) = -6x^{-5}\r\n\\]\r\n', 3, '2025-07-21 13:29:40', '2025-07-21 13:29:40'),
(636, 307, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL:}}\r\n\\quad\r\nf\'(x) = -\\frac{6}{x^5}\r\n\\]\r\n', 4, '2025-07-21 13:29:40', '2025-07-21 13:29:40'),
(637, 308, '\r\n\\[\r\n\\boxed{\\text{PASO 1: ESCRIBIR LA FUNCIÓN COMO POTENCIA}}\r\n\\]\r\nLa función es:\r\n\\[\r\nf(x) = \\frac{2}{3x^2} = \\frac{2}{3} \\cdot x^{-2}\r\n\\]\r\nEsto permite usar la regla de derivación de potencias.\r\n', 1, '2025-07-21 13:34:40', '2025-07-21 13:34:40'),
(638, 308, '\r\n\\[\r\n\\boxed{\\text{PASO 2: APLICAR LA REGLA DE DERIVADAS}}\r\n\\]\r\nUsamos:\r\n\\[\r\n\\frac{d}{dx}(x^n) = nx^{n-1}\r\n\\]\r\nEntonces:\r\n\\[\r\nf(x) = \\frac{2}{3}x^{-2} \\Rightarrow f\'(x) = \\frac{2}{3} \\cdot (-2)x^{-3}\r\n\\]\r\n', 2, '2025-07-21 13:34:40', '2025-07-21 13:34:40'),
(639, 308, '\r\n\\[\r\n\\boxed{\\text{PASO 3: SIMPLIFICAR LOS COEFICIENTES}}\r\n\\]\r\n\\[\r\n\\frac{2}{3} \\cdot (-2) = -\\frac{4}{3}\r\n\\Rightarrow f\'(x) = -\\frac{4}{3}x^{-3}\r\n\\]\r\n', 3, '2025-07-21 13:34:40', '2025-07-21 13:34:40'),
(640, 308, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL:}}\r\n\\quad\r\nf\'(x) = -\\frac{4}{3x^3}\r\n\\]\r\n', 4, '2025-07-21 13:34:40', '2025-07-21 13:34:40'),
(641, 309, '\r\n\\[\r\n\\boxed{\\text{PASO 1: REESCRIBIR LA FUNCIÓN USANDO POTENCIAS DE } x}\r\n\\]\r\n\\[\r\nf(x) = \\frac{3}{x^2} - \\frac{6}{5x^3} - \\frac{7}{5}\r\n= 3x^{-2} - \\frac{6}{5}x^{-3} - \\frac{7}{5}\r\n\\]\r\nAsí podemos aplicar la regla de derivación de potencias.\r\n', 1, '2025-07-21 13:41:56', '2025-07-21 13:41:56'),
(642, 309, '\r\n\\[\r\n\\boxed{\\text{PASO 2: DERIVAR CADA TÉRMINO INDIVIDUALMENTE}}\r\n\\]\r\nUsamos la regla:\r\n\\[\r\n\\frac{d}{dx}(x^n) = nx^{n-1}\r\n\\]\r\nEntonces:\r\n\\[\r\n\\frac{d}{dx}(3x^{-2}) = -6x^{-3}, \\quad\r\n\\frac{d}{dx}\\left(\\frac{6}{5}x^{-3}\\right) = \\frac{18}{5}x^{-4}, \\quad\r\n\\frac{d}{dx}\\left(\\frac{-7}{5}\\right) = 0\r\n\\]\r\n', 2, '2025-07-21 13:41:56', '2025-07-21 13:41:56'),
(643, 309, '\r\n\\[\r\n\\boxed{\\text{PASO 3: SUMAR LAS DERIVADAS}}\r\n\\]\r\n\\[\r\nf\'(x) = -6x^{-3} + \\frac{18}{5}x^{-4}\r\n\\]\r\nY ahora expresamos con potencias positivas:\r\n\\[\r\nf\'(x) = -\\frac{6}{x^3} + \\frac{18}{5x^4}\r\n\\]\r\n', 3, '2025-07-21 13:41:56', '2025-07-21 13:41:56'),
(644, 309, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL:}}\r\n\\quad\r\nf\'(x) = -\\frac{6}{x^3} + \\frac{18}{5x^4}\r\n\\]\r\n', 4, '2025-07-21 13:41:56', '2025-07-21 13:41:56'),
(649, 311, '\r\n\\[\r\n\\boxed{\\text{PASO 1: IDENTIFICAR EL TIPO DE FUNCIÓN}}\r\n\\]\r\n\\[\r\nf(x) = sen(3x^5)\r\n\\]\r\nSe trata de una **función compuesta**: una función seno cuyo argumento es otra función: \\( u(x) = 3x^5 \\).\r\n', 1, '2025-07-21 14:11:53', '2025-07-21 14:11:53'),
(650, 311, '\r\n\\[\r\n\\boxed{\\text{PASO 2: APLICAR LA REGLA DE LA CADENA}}\r\n\\]\r\nLa derivada de \\( sen(u) \\) es:\r\n\\[\r\nf\'(x) = cos(u) \\cdot u\'(x)\r\n\\]\r\nDonde \\( u(x) = 3x^5 \\) y \\( u\'(x) = 15x^4 \\).\r\n', 2, '2025-07-21 14:11:53', '2025-07-21 14:11:53'),
(651, 311, '\r\n\\[\r\n\\boxed{\\text{PASO 3: SUSTITUIR Y MULTIPLICAR}}\r\n\\]\r\nSustituimos:\r\n\\[\r\nf\'(x) = cos(3x^5) \\cdot 15x^4 = 15x^4 cos(3x^5)\r\n\\]\r\n', 3, '2025-07-21 14:11:53', '2025-07-21 14:11:53'),
(652, 311, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL:}}\r\n\\quad\r\nf\'(x) = 15x^4 cos(3x^5)\r\n\\]\r\n', 4, '2025-07-21 14:11:53', '2025-07-21 14:11:53'),
(657, 313, '\r\n\\[\r\n\\text{\\textbf{PASO 1: REESCRIBIR LA RAÍZ COMO POTENCIA}} \\\\\r\nf(x) = \\sqrt{x} = x^{1/2}\r\n\\]\r\n', 1, '2025-07-21 15:19:55', '2025-07-21 15:19:55'),
(658, 313, '\r\n\\[\r\n\\text{\\textbf{PASO 2: APLICAR LA REGLA DE POTENCIAS}} \\\\\r\n\\text{La derivada de } x^n \\text{ es:} \\\\\r\nf\'(x) = nx^{n - 1}\r\n\\]\r\n', 2, '2025-07-21 15:19:55', '2025-07-21 15:19:55'),
(659, 313, '\r\n\\[\r\n\\text{\\textbf{PASO 3: SUSTITUIR }} n = \\frac{1}{2} \\\\\r\nf\'(x) = \\frac{1}{2}x^{-1/2}\r\n\\]\r\n', 3, '2025-07-21 15:19:55', '2025-07-21 15:19:55'),
(660, 313, '\r\n\\[\r\n\\text{\\textbf{RESULTADO FINAL:}} \\\\\r\nf\'(x) = \\frac{1}{2\\sqrt{x}}\r\n\\]\r\n', 4, '2025-07-21 15:19:55', '2025-07-21 15:19:55'),
(661, 314, '\r\n\\[\r\n\\text{\\textbf{PASO 1: REESCRIBIR LA RAÍZ COMO POTENCIA}} \\\\\r\nf(x) = \\sqrt[3]{x} = x^{1/3}\r\n\\]\r\n', 1, '2025-07-21 17:37:39', '2025-07-21 17:37:39'),
(662, 314, '\r\n\\[\r\n\\text{\\textbf{PASO 2: APLICAR LA REGLA DE POTENCIAS}} \\\\\r\n\\text{La derivada de } x^n \\text{ es:} \\\\\r\nf\'(x) = nx^{n - 1}\r\n\\]\r\n', 2, '2025-07-21 17:37:39', '2025-07-21 17:37:39'),
(663, 314, '\r\n\\[\r\n\\text{\\textbf{PASO 3: SUSTITUIR }} n = \\frac{1}{3} \\\\\r\nf\'(x) = \\frac{1}{3}x^{-2/3}\r\n\\]\r\n', 3, '2025-07-21 17:37:39', '2025-07-21 17:37:39'),
(664, 314, '\r\n\\[\r\n\\text{\\textbf{RESULTADO FINAL:}} \\\\\r\nf\'(x) = \\frac{1}{3\\sqrt[3]{x^2}}\r\n\\]\r\n', 4, '2025-07-21 17:37:39', '2025-07-21 17:37:39'),
(665, 315, '\r\n\\[\r\n\\text{\\textbf{PASO 1: REESCRIBIR LA RAÍZ COMO POTENCIA}} \\\\\r\nf(x) = \\sqrt[5]{x^2} = x^{2/5}\r\n\\]\r\n', 1, '2025-07-21 18:08:08', '2025-07-21 18:08:08'),
(666, 315, '\r\n\\[\r\n\\text{\\textbf{PASO 2: APLICAR LA REGLA DE POTENCIAS}} \\\\\r\n\\text{La derivada de } x^n \\text{ es:} \\\\\r\nf\'(x) = nx^{n - 1}\r\n\\]\r\n', 2, '2025-07-21 18:08:08', '2025-07-21 18:08:08'),
(667, 315, '\r\n\\[\r\n\\text{\\textbf{PASO 3: SUSTITUIR }} n = \\frac{2}{5} \\\\\r\n\\text{Entonces, } n-1 = \\frac{2}{5} - 1 = \\frac{2}{5} - \\frac{5}{5} = -\\frac{3}{5} \\\\\r\nf\'(x) = \\frac{2}{5}x^{-3/5}\r\n\\]\r\n', 3, '2025-07-21 18:08:08', '2025-07-21 18:08:08'),
(668, 315, '\r\n\\[\r\n\\text{\\textbf{RESULTADO FINAL:}} \\\\\r\n\\text{Convertimos el exponente negativo/fraccionario a su forma radical:} \\\\\r\nf\'(x) = \\frac{2}{5\\sqrt[5]{x^3}}\r\n\\]\r\n', 4, '2025-07-21 18:08:08', '2025-07-21 18:08:08'),
(669, 316, '\r\n\\[\r\n\\text{\\textbf{PASO 1: REESCRIBIR LA RAÍZ COMO POTENCIA}} \\\\\r\nf(x) = \\sqrt[4]{x^3} = x^{3/4}\r\n\\]\r\n', 1, '2025-07-21 18:22:09', '2025-07-21 18:22:09'),
(670, 316, '\r\n\\[\r\n\\text{\\textbf{PASO 2: APLICAR LA REGLA DE POTENCIAS}} \\\\\r\n\\text{La derivada de } x^n \\text{ es:} \\\\\r\nf\'(x) = nx^{n - 1}\r\n\\]\r\n', 2, '2025-07-21 18:22:09', '2025-07-21 18:22:09'),
(671, 316, '\r\n\\[\r\n\\text{\\textbf{PASO 3: SUSTITUIR }} n = \\frac{3}{4} \\\\\r\n\\text{Entonces, } n-1 = \\frac{3}{4} - 1 = \\frac{3}{4} - \\frac{4}{4} = -\\frac{1}{4} \\\\\r\nf\'(x) = \\frac{3}{4}x^{-1/4}\r\n\\]\r\n', 3, '2025-07-21 18:22:09', '2025-07-21 18:22:09'),
(672, 316, '\r\n\\[\r\n\\text{\\textbf{RESULTADO FINAL:}} \\\\\r\n\\text{Convertimos el exponente negativo/fraccionario a su forma radical:} \\\\\r\nf\'(x) = \\frac{3}{4\\sqrt[4]{x}}\r\n\\]\r\n', 4, '2025-07-21 18:22:09', '2025-07-21 18:22:09'),
(673, 317, '\r\n\\[\r\n\\boxed{\\text{PASO 1: IDENTIFICAR LA ESTRUCTURA DE LA FUNCIÓN}}\r\n\\]\r\n\r\nLa función \\( f(p) = 2^{3p - sen p} \\) es una función exponencial con base constante \\(2\\) y un exponente variable \\( u(p) = 3p - sen p \\).\r\n', 1, '2025-07-22 00:31:25', '2025-07-22 00:31:25'),
(674, 317, '\r\n\\[\r\n\\boxed{\\text{PASO 2: APLICAR LA REGLA DE DERIVACIÓN DE EXPONENCIALES}}\r\n\\]\r\n\r\nSi \\( f(p) = a^{u(p)} \\), entonces:\r\n\\[\r\nf\'(p) = a^{u(p)} \\cdot \\ln(a) \\cdot u\'(p)\r\n\\]\r\nCon \\( a = 2 \\), se obtiene:\r\n\\[\r\nf\'(p) = 2^{u(p)} \\cdot \\ln(2) \\cdot u\'(p)\r\n\\]\r\n', 2, '2025-07-22 00:31:25', '2025-07-22 00:31:25'),
(675, 317, '\r\n\\[\r\n\\boxed{\\text{PASO 3: DERIVAR EL EXPONENTE } u(p) = 3p - sen p}\r\n\\]\r\n\r\nLa derivada de \\( u(p) \\) es:\r\n\\[\r\nu\'(p) = 3 - cos p\r\n\\]\r\n', 3, '2025-07-22 00:31:25', '2025-07-22 00:31:25'),
(676, 317, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\n\r\nSustituyendo todo en la fórmula:\r\n\\[\r\nf\'(p) = 2^{3p - sen p} \\cdot \\ln(2) \\cdot (3 - cos p)\r\n\\]\r\n', 4, '2025-07-22 00:31:25', '2025-07-22 00:31:25'),
(677, 318, '\r\n\\[\r\n\\boxed{\\text{PASO 1: IDENTIFICAR EL TIPO DE FUNCIÓN}}\r\n\\]\r\n\r\nLa función \\( f(q) = 5^{2q - cos q} \\) es una función exponencial con base constante \\(5\\) y un exponente que depende de \\(q\\).\r\n', 1, '2025-07-22 00:38:31', '2025-07-22 00:38:31'),
(678, 318, '\r\n\\[\r\n\\boxed{\\text{PASO 2: APLICAR LA REGLA DE DERIVACIÓN DE EXPONENCIALES}}\r\n\\]\r\n\r\nSi \\( f(q) = a^{u(q)} \\), entonces su derivada es:\r\n\\[\r\nf\'(q) = a^{u(q)} \\cdot \\ln(a) \\cdot u\'(q)\r\n\\]\r\nAquí, \\( a = 5 \\) y \\( u(q) = 2q - cos q \\)\r\n', 2, '2025-07-22 00:38:31', '2025-07-22 00:38:31'),
(679, 318, '\r\n\\[\r\n\\boxed{\\text{PASO 3: DERIVAR EL EXPONENTE } u(q) = 2q - cos q}\r\n\\]\r\n\r\n\\[\r\nu\'(q) = 2 + sen q\r\n\\]\r\n', 3, '2025-07-22 00:38:31', '2025-07-22 00:38:31');
INSERT INTO `problem_hints` (`id`, `problem_id`, `hint`, `sequence_id`, `created_at`, `updated_at`) VALUES
(680, 318, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\n\r\nSustituyendo todo en la fórmula de derivación:\r\n\\[\r\nf\'(q) = 5^{2q - cos q} \\cdot \\ln(5) \\cdot (2 + sen q)\r\n\\]\r\n', 4, '2025-07-22 00:38:31', '2025-07-22 00:38:31'),
(681, 319, '\r\n\\[\r\n\\boxed{\\text{PASO 1: IDENTIFICAR LA FUNCIÓN}}\r\n\\]\r\nLa función \\( y = e^{2x - 1} \\) es una exponencial con base \\( e \\), y un exponente que depende de \\( x \\).\r\n', 1, '2025-07-22 00:42:24', '2025-07-22 00:42:24'),
(682, 319, '\r\n\\[\r\n\\boxed{\\text{PASO 2: USAR LA REGLA DE LA CADENA}}\r\n\\]\r\nSi \\( y = e^{u(x)} \\), entonces su derivada es:\r\n\\[\r\ny\' = e^{u(x)} \\cdot u\'(x)\r\n\\]\r\nDonde \\( u(x) = 2x - 1 \\)\r\n', 2, '2025-07-22 00:42:24', '2025-07-22 00:42:24'),
(683, 319, '\r\n\\[\r\n\\boxed{\\text{PASO 3: DERIVAR EL EXPONENTE}}\r\n\\]\r\n\\[\r\nu(x) = 2x - 1 \\Rightarrow u\'(x) = 2\r\n\\]\r\n', 3, '2025-07-22 00:42:24', '2025-07-22 00:42:24'),
(684, 319, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\n\\[\r\ny\' = e^{2x - 1} \\cdot 2\r\n\\]\r\n', 4, '2025-07-22 00:42:24', '2025-07-22 00:42:24'),
(685, 320, '\r\n\\[\r\n\\boxed{\\text{PASO 1: IDENTIFICAR LA FUNCIÓN}}\r\n\\]\r\nLa función \\( y = e^{3x^2 + 2} \\) es una exponencial con base \\( e \\), donde el exponente es una función compuesta: \\( 3x^2 + 2 \\).\r\n', 1, '2025-07-22 00:45:57', '2025-07-22 00:45:57'),
(686, 320, '\r\n\\[\r\n\\boxed{\\text{PASO 2: USAR LA REGLA DE LA CADENA}}\r\n\\]\r\nSi \\( y = e^{u(x)} \\), entonces su derivada es:\r\n\\[\r\ny\' = e^{u(x)} \\cdot u\'(x)\r\n\\]\r\nCon \\( u(x) = 3x^2 + 2 \\)\r\n', 2, '2025-07-22 00:45:57', '2025-07-22 00:45:57'),
(687, 320, '\r\n\\[\r\n\\boxed{\\text{PASO 3: DERIVAR EL EXPONENTE}}\r\n\\]\r\n\\[\r\nu(x) = 3x^2 + 2 \\Rightarrow u\'(x) = 6x\r\n\\]\r\n', 3, '2025-07-22 00:45:57', '2025-07-22 00:45:57'),
(688, 320, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\n\\[\r\ny\' = e^{3x^2 + 2} \\cdot 6x\r\n\\]\r\n', 4, '2025-07-22 00:45:57', '2025-07-22 00:45:57'),
(689, 321, '\r\n\\[\r\n\\text{\\textbf{PASO 1: REESCRIBIR LA FUNCIÓN USANDO EXPONENTES FRACCIONARIOS}} \\\\\r\nf(x) = 2x^{2/3} - 4x^{3/2} + 7^{1/2}\r\n\\]\r\n', 1, '2025-07-23 01:34:53', '2025-07-23 01:34:53'),
(690, 321, '\r\n\\[\r\n\\text{\\textbf{PASO 2: APLICAR LA REGLA DE LA SUMA/RESTA Y LA REGLA DE POTENCIAS}} \\\\\r\n\\text{La derivada de una suma/resta es la suma/resta de las derivadas.} \\\\\r\n\\text{La derivada de } x^n \\text{ es:} \\quad f\'(x) = nx^{n - 1} \\\\\r\n\\text{La derivada de una constante es } 0.\r\n\\]\r\n', 2, '2025-07-23 01:34:53', '2025-07-23 01:34:53'),
(691, 321, '\r\n\\[\r\n\\text{\\textbf{PASO 3: DERIVAR EL PRIMER TÉRMINO}} \\\\\r\n\\text{Término:} \\quad 2x^{2/3} \\\\\r\n\\text{Aplicando la regla de potencias } (n=2/3): \\\\\r\n2 \\cdot \\frac{2}{3}x^{(2/3) - 1} = \\frac{4}{3}x^{-1/3} \\\\\r\n\\text{En forma radical:} \\quad \\frac{4}{3\\sqrt[3]{x}}\r\n\\]\r\n', 3, '2025-07-23 01:34:53', '2025-07-23 01:34:53'),
(692, 321, '\r\n\\[\r\n\\text{\\textbf{PASO 4: DERIVAR EL SEGUNDO TÉRMINO}} \\\\\r\n\\text{Término:} \\quad -4x^{3/2} \\\\\r\n\\text{Aplicando la regla de potencias } (n=3/2): \\\\\r\n-4 \\cdot \\frac{3}{2}x^{(3/2) - 1} = -6x^{1/2} \\\\\r\n\\text{En forma radical:} \\quad -6\\sqrt{x}\r\n\\]\r\n', 4, '2025-07-23 01:34:53', '2025-07-23 01:34:53'),
(693, 321, '\r\n\\[\r\n\\text{\\textbf{PASO 5: DERIVAR EL TERCER TÉRMINO (CONSTANTE)}} \\\\\r\n\\text{Término:} \\quad \\sqrt{7} \\\\\r\n\\text{La derivada de cualquier constante es } 0.\r\n\\]\r\n', 5, '2025-07-23 01:34:53', '2025-07-23 01:34:53'),
(694, 321, '\r\n\\[\r\n\\text{\\textbf{RESULTADO FINAL:}} \\\\\r\n\\text{Combinamos las derivadas de cada término:} \\\\\r\nf\'(x) = \\frac{4}{3\\sqrt[3]{x}} - 6\\sqrt{x} + 0 \\\\\r\nf\'(x) = \\frac{4}{3\\sqrt[3]{x}} - 6\\sqrt{x}\r\n\\]\r\n', 6, '2025-07-23 01:34:53', '2025-07-23 01:34:53'),
(695, 322, '\r\n\\[\r\n\\boxed{\\text{PASO 1: IDENTIFICA LAS FUNCIONES COMPUESTAS}}\r\n\\]\r\nTenemos una suma de dos funciones compuestas:\r\n\\[\r\ny = \\tan(2^{3x+5}) + \\ln(\\sec(e^{7x-3}))\r\n\\]\r\nDebemos derivar cada término usando la regla de la cadena.\r\n', 1, '2025-07-23 04:18:25', '2025-07-23 04:18:25'),
(696, 322, '\r\n\\[\r\n\\boxed{\\text{PASO 2: DERIVA } \\tan(2^{3x+5})}\r\n\\]\r\nSabemos que:\r\n\\[\r\n\\frac{d}{dx} \\tan(u) = \\sec^2(u) \\cdot u\'(x)\r\n\\]\r\nAquí, \\( u = 2^{3x+5} \\), y su derivada es:\r\n\\[\r\nu\'(x) = 2^{3x+5} \\cdot \\ln(2) \\cdot 3\r\n\\]\r\n', 2, '2025-07-23 04:18:25', '2025-07-23 04:18:25'),
(697, 322, '\r\n\\[\r\n\\boxed{\\text{PASO 3: DERIVA } \\ln(\\sec(e^{7x-3}))}\r\n\\]\r\nLa derivada de \\( \\ln(f(x)) \\) es:\r\n\\[\r\n\\frac{1}{f(x)} \\cdot f\'(x)\r\n\\]\r\nEntonces:\r\n\\[\r\n\\frac{d}{dx} \\ln(\\sec(e^{7x-3})) = \\frac{1}{\\sec(e^{7x-3})} \\cdot \\sec(e^{7x-3}) \\cdot \\tan(e^{7x-3}) \\cdot e^{7x-3} \\cdot 7\r\n\\]\r\nSimplificando:\r\n\\[\r\n= \\tan(e^{7x-3}) \\cdot e^{7x-3} \\cdot 7\r\n\\]\r\n', 3, '2025-07-23 04:18:25', '2025-07-23 04:18:25'),
(698, 322, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\nSumamos ambos términos:\r\n\\[\r\ny\' = \\sec^2(2^{3x+5}) \\cdot 2^{3x+5} \\cdot \\ln(2) \\cdot 3 + \\tan(e^{7x-3}) \\cdot e^{7x-3} \\cdot 7\r\n\\]\r\n', 4, '2025-07-23 04:18:25', '2025-07-23 04:18:25'),
(699, 323, '\r\n\\[\r\n\\boxed{\\text{PASO 1: IDENTIFICAR LAS FUNCIONES COMPUESTAS}}\r\n\\]\r\nTenemos una suma:\r\n\\[\r\ny = \\cos(3^{4 - 3x}) + \\ln(e^{2x^2 - 1})\r\n\\]\r\nAplicaremos la regla de la cadena en ambos términos.\r\n', 1, '2025-07-23 04:24:05', '2025-07-23 04:24:05'),
(700, 323, '\r\n\\[\r\n\\boxed{\\text{PASO 2: DERIVADA DE } \\cos(3^{4 - 3x})}\r\n\\]\r\nLa derivada de \\( \\cos(u) \\) es:\r\n\\[\r\n\\frac{d}{dx}\\cos(u) = -\\sin(u) \\cdot u\'(x)\r\n\\]\r\nDonde \\( u = 3^{4 - 3x} \\), cuya derivada es:\r\n\\[\r\nu\' = 3^{4 - 3x} \\cdot \\ln(3) \\cdot (-3)\r\n\\]\r\n', 2, '2025-07-23 04:24:05', '2025-07-23 04:24:05'),
(701, 323, '\r\n\\[\r\n\\boxed{\\text{PASO 3: DERIVADA DE } \\ln(e^{2x^2 - 1})}\r\n\\]\r\nUsamos la propiedad:\r\n\\[\r\n\\ln(e^{f(x)}) = f(x)\r\n\\Rightarrow \\frac{d}{dx} \\ln(e^{2x^2 - 1}) = \\frac{d}{dx}(2x^2 - 1) = 4x\r\n\\]\r\n', 3, '2025-07-23 04:24:05', '2025-07-23 04:24:05'),
(702, 323, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\nSumamos las derivadas:\r\n\\[\r\ny\' = -\\sin(3^{4 - 3x}) \\cdot 3^{4 - 3x} \\cdot \\ln(3) \\cdot (-3) + 4x\r\n\\]\r\n', 4, '2025-07-23 04:24:05', '2025-07-23 04:24:05'),
(703, 324, '\r\n\\[\r\n\\boxed{\\text{PASO 1: IDENTIFICAR LA FUNCIÓN COMPUESTA}}\r\n\\]\r\nTenemos una función exponencial compuesta:\r\n\\[\r\ng(x) = e^{sen(2x^2)}\r\n\\]\r\nAplicaremos la regla de la cadena.\r\n', 1, '2025-07-23 04:31:15', '2025-07-23 04:31:15'),
(704, 324, '\r\n\\[\r\n\\boxed{\\text{PASO 2: DERIVADA DE } e^{f(x)}}\r\n\\]\r\nLa derivada de una exponencial es:\r\n\\[\r\n\\frac{d}{dx}e^{f(x)} = e^{f(x)} \\cdot f\'(x)\r\n\\]\r\nDonde \\( f(x) = sen(2x^2) \\)\r\n', 2, '2025-07-23 04:31:15', '2025-07-23 04:31:15'),
(705, 324, '\r\n\\[\r\n\\boxed{\\text{PASO 3: DERIVADA DE } sen(2x^2)}\r\n\\]\r\nLa derivada de \\( sen(u) \\) es:\r\n\\[\r\n\\frac{d}{dx}sen(u) = cos(u) \\cdot u\'(x)\r\n\\]\r\nAquí, \\( u = 2x^2 \\), por lo tanto:\r\n\\[\r\n\\frac{d}{dx}sen(2x^2) = cos(2x^2) \\cdot 4x\r\n\\]\r\n', 3, '2025-07-23 04:31:15', '2025-07-23 04:31:15'),
(706, 324, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\nSustituimos en la fórmula completa:\r\n\\[\r\ng\'(x) = e^{sen(2x^2)} \\cdot cos(2x^2) \\cdot 4x\r\n\\]\r\n', 4, '2025-07-23 04:31:15', '2025-07-23 04:31:15'),
(707, 325, '\r\n\\[\r\n\\boxed{\\text{PASO 1: IDENTIFICAR EL TIPO DE FUNCIÓN}}\r\n\\]\r\nLa función \\( f(x) = x^{3x} \\) tiene la variable en la base y el exponente.\r\nPara derivarla, primero aplicamos logaritmos:\r\n\\[\r\n\\ln f(x) = 3x \\ln x\r\n\\]\r\n', 1, '2025-07-23 04:35:17', '2025-07-23 04:35:17'),
(708, 325, '\r\n\\[\r\n\\boxed{\\text{PASO 2: DERIVADA IMPLÍCITA}}\r\n\\]\r\nDerivamos ambos lados con respecto a \\( x \\):\r\n\\[\r\n\\frac{f\'(x)}{f(x)} = \\frac{d}{dx}(3x \\ln x)\r\n\\]\r\nAplicamos regla del producto:\r\n\\[\r\n\\frac{d}{dx}(3x \\ln x) = 3 \\ln x + 3\r\n\\]\r\n', 2, '2025-07-23 04:35:17', '2025-07-23 04:35:17'),
(709, 325, '\r\n\\[\r\n\\boxed{\\text{PASO 3: DESPEJAR } f\'(x)}\r\n\\]\r\nMultiplicamos ambos lados por \\( f(x) = x^{3x} \\):\r\n\\[\r\nf\'(x) = x^{3x}(3\\ln x + 3)\r\n\\]\r\n', 3, '2025-07-23 04:35:17', '2025-07-23 04:35:17'),
(710, 325, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\nLa derivada de \\( f(x) = x^{3x} \\) es:\r\n\\[\r\nf\'(x) = x^{3x}(3\\ln x + 3)\r\n\\]\r\n', 4, '2025-07-23 04:35:17', '2025-07-23 04:35:17'),
(711, 326, '\r\n\\[\r\n\\boxed{\\text{PASO 1: TRANSFORMACIÓN LOGARÍTMICA}}\r\n\\]\r\nLa función \\( f(x) = x^{2x} \\) tiene la variable tanto en la base como en el exponente. Aplicamos logaritmos:\r\n\\[\r\n\\ln f(x) = 2x \\ln x\r\n\\]\r\n', 1, '2025-07-23 04:37:06', '2025-07-23 04:37:06'),
(712, 326, '\r\n\\[\r\n\\boxed{\\text{PASO 2: DERIVACIÓN IMPLÍCITA}}\r\n\\]\r\nDerivamos ambos lados con respecto a \\( x \\):\r\n\\[\r\n\\frac{f\'(x)}{f(x)} = \\frac{d}{dx}(2x \\ln x)\r\n\\]\r\nAplicamos la regla del producto:\r\n\\[\r\n\\frac{d}{dx}(2x \\ln x) = 2\\ln x + 2\r\n\\]\r\n', 2, '2025-07-23 04:37:06', '2025-07-23 04:37:06'),
(713, 326, '\r\n\\[\r\n\\boxed{\\text{PASO 3: DESPEJAR LA DERIVADA}}\r\n\\]\r\nMultiplicamos ambos lados por \\( f(x) = x^{2x} \\):\r\n\\[\r\nf\'(x) = x^{2x}(2\\ln x + 2)\r\n\\]\r\n', 3, '2025-07-23 04:37:06', '2025-07-23 04:37:06'),
(714, 326, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\nPor lo tanto, la derivada de \\( f(x) = x^{2x} \\) es:\r\n\\[\r\nf\'(x) = x^{2x}(2\\ln x + 2)\r\n\\]\r\n', 4, '2025-07-23 04:37:06', '2025-07-23 04:37:06'),
(715, 327, '\r\n\\[\r\n\\text{\\textbf{PASO 1: REESCRIBIR LA FUNCIÓN USANDO EXPONENTES FRACCIONARIOS}} \\\\\r\nf(x) = 3x^{5/3} - 2x^{3/2}\r\n\\]\r\n', 1, '2025-07-23 14:35:16', '2025-07-23 14:35:16'),
(716, 327, '\r\n\\[\r\n\\text{\\textbf{PASO 2: APLICAR LA REGLA DE LA SUMA/RESTA Y LA REGLA DE POTENCIAS}} \\\\\r\n\\text{La derivada de una suma/resta es la suma/resta de las derivadas.} \\\\\r\n\\text{La derivada de } x^n \\text{ es:} \\quad f\'(x) = nx^{n - 1}\r\n\\]\r\n', 2, '2025-07-23 14:35:16', '2025-07-23 14:35:16'),
(717, 327, '\r\n\\[\r\n\\text{\\textbf{PASO 3: DERIVAR EL PRIMER TÉRMINO}} \\\\\r\n\\text{Término:} \\quad 3x^{5/3} \\\\\r\n\\text{Aplicando la regla de potencias } (n=5/3): \\\\\r\n3 \\cdot \\frac{5}{3}x^{(5/3) - 1} = 5x^{2/3} \\\\\r\n\\text{En forma radical:} \\quad 5\\sqrt[3]{x^2}\r\n\\]\r\n', 3, '2025-07-23 14:35:16', '2025-07-23 14:35:16'),
(718, 327, '\r\n\\[\r\n\\text{\\textbf{PASO 4: DERIVAR EL SEGUNDO TÉRMINO}} \\\\\r\n\\text{Término:} \\quad -2x^{3/2} \\\\\r\n\\text{Aplicando la regla de potencias } (n=3/2): \\\\\r\n-2 \\cdot \\frac{3}{2}x^{(3/2) - 1} = -3x^{1/2} \\\\\r\n\\text{En forma radical:} \\quad -3\\sqrt{x}\r\n\\]\r\n', 4, '2025-07-23 14:35:16', '2025-07-23 14:35:16'),
(719, 327, '\r\n\\[\r\n\\text{\\textbf{RESULTADO FINAL:}} \\\\\r\n\\text{Combinamos las derivadas de cada término:} \\\\\r\nf\'(x) = 5\\sqrt[3]{x^2} - 3\\sqrt{x}\r\n\\]\r\n', 5, '2025-07-23 14:35:16', '2025-07-23 14:35:16'),
(720, 328, '\r\n\\[\r\n\\text{\\textbf{PASO 1: IDENTIFICAR LAS PARTES u(x) y v(x)}} \\\\\r\nu(x) = 2x - 3x^2 \\\\\r\nv(x) = x + 2x^5\r\n\\]\r\n', 1, '2025-07-23 17:49:25', '2025-07-23 17:49:25'),
(721, 328, '\r\n\\[\r\n\\text{\\textbf{PASO 2: APLICAR LA REGLA DEL PRODUCTO}} \\\\\r\n\\text{Si } f(x) = u(x)v(x), \\text{ entonces } f\'(x) = u\'(x)v(x) + u(x)v\'(x)\r\n\\]\r\n', 2, '2025-07-23 17:49:25', '2025-07-23 17:49:25'),
(722, 328, '\r\n\\[\r\n\\text{\\textbf{PASO 3: CALCULAR LAS DERIVADAS u\'(x) y v\'(x)}} \\\\\r\nu\'(x) = \\frac{d}{dx}(2x - 3x^2) = 2 - 6x \\\\\r\nv\'(x) = \\frac{d}{dx}(x + 2x^5) = 1 + 10x^4\r\n\\]\r\n', 3, '2025-07-23 17:49:25', '2025-07-23 17:49:25'),
(723, 328, '\r\n\\[\r\n\\text{\\textbf{PASO 4: SUSTITUIR EN LA FÓRMULA DE LA REGLA DEL PRODUCTO}} \\\\\r\nf\'(x) = (2 - 6x)(x + 2x^5) + (2x - 3x^2)(1 + 10x^4)\r\n\\]\r\n', 4, '2025-07-23 17:49:25', '2025-07-23 17:49:25'),
(724, 328, '\r\n\\[\r\n\\text{\\textbf{PASO 5: EXPANDIR LOS PRODUCTOS}} \\\\\r\n(2 - 6x)(x + 2x^5) = 2x + 4x^5 - 6x^2 - 12x^6 \\\\\r\n(2x - 3x^2)(1 + 10x^4) = 2x + 20x^5 - 3x^2 - 30x^6\r\n\\]\r\n', 5, '2025-07-23 17:49:25', '2025-07-23 17:49:25'),
(725, 328, '\r\n\\[\r\n\\text{\\textbf{PASO 6: COMBINAR TÉRMINOS SEMEJANTES Y SIMPLIFICAR}} \\\\\r\nf\'(x) = (2x + 4x^5 - 6x^2 - 12x^6) + (2x + 20x^5 - 3x^2 - 30x^6) \\\\\r\nf\'(x) = -42x^6 + 24x^5 - 9x^2 + 4x\r\n\\]\r\n', 6, '2025-07-23 17:49:25', '2025-07-23 17:49:25'),
(726, 329, '\r\n\\[\r\n\\text{\\textbf{PASO 1: IDENTIFICAR LAS PARTES u(x) y v(x)}} \\\\\r\nu(x) = 3x - 2x^2 \\\\\r\nv(x) = x + 3x^5\r\n\\]\r\n', 1, '2025-07-23 17:59:13', '2025-07-23 17:59:13'),
(727, 329, '\r\n\\[\r\n\\text{\\textbf{PASO 2: APLICAR LA REGLA DEL PRODUCTO}} \\\\\r\n\\text{Si } f(x) = u(x)v(x), \\text{ entonces } f\'(x) = u\'(x)v(x) + u(x)v\'(x)\r\n\\]\r\n', 2, '2025-07-23 17:59:13', '2025-07-23 17:59:13'),
(728, 329, '\r\n\\[\r\n\\text{\\textbf{PASO 3: CALCULAR LAS DERIVADAS u\'(x) y v\'(x)}} \\\\\r\nu\'(x) = \\frac{d}{dx}(3x - 2x^2) = 3 - 4x \\\\\r\nv\'(x) = \\frac{d}{dx}(x + 3x^5) = 1 + 15x^4\r\n\\]\r\n', 3, '2025-07-23 17:59:13', '2025-07-23 17:59:13'),
(729, 329, '\r\n\\[\r\n\\text{\\textbf{PASO 4: SUSTITUIR EN LA FÓRMULA DE LA REGLA DEL PRODUCTO}} \\\\\r\nf\'(x) = (3 - 4x)(x + 3x^5) + (3x - 2x^2)(1 + 15x^4)\r\n\\]\r\n', 4, '2025-07-23 17:59:13', '2025-07-23 17:59:13'),
(730, 329, '\r\n\\[\r\n\\text{\\textbf{PASO 5: EXPANDIR LOS PRODUCTOS}} \\\\\r\n(3 - 4x)(x + 3x^5) = 3x + 9x^5 - 4x^2 - 12x^6 \\\\\r\n(3x - 2x^2)(1 + 15x^4) = 3x + 45x^5 - 2x^2 - 30x^6\r\n\\]\r\n', 5, '2025-07-23 17:59:13', '2025-07-23 17:59:13'),
(731, 329, '\r\n\\[\r\n\\text{\\textbf{PASO 6: COMBINAR TÉRMINOS SEMEJANTES Y SIMPLIFICAR}} \\\\\r\nf\'(x) = (3x + 9x^5 - 4x^2 - 12x^6) + (3x + 45x^5 - 2x^2 - 30x^6) \\\\\r\nf\'(x) = -42x^6 + 54x^5 - 6x^2 + 6x\r\n\\]\r\n', 6, '2025-07-23 17:59:13', '2025-07-23 17:59:13'),
(732, 330, '\r\n\\[\r\n\\text{\\textbf{PASO 1: IDENTIFICAR LAS PARTES u(x) y v(x)}} \\\\\r\nu(x) = x^2 + 3x - 1 \\\\\r\nv(x) = 2x - 1\r\n\\]\r\n', 1, '2025-07-23 18:33:54', '2025-07-23 18:33:54'),
(733, 330, '\r\n\\[\r\n\\text{\\textbf{PASO 2: APLICAR LA REGLA DEL PRODUCTO}} \\\\\r\n\\text{Si } f(x) = u(x)v(x), \\text{ entonces } f\'(x) = u\'(x)v(x) + u(x)v\'(x)\r\n\\]\r\n', 2, '2025-07-23 18:33:54', '2025-07-23 18:33:54'),
(734, 330, '\r\n\\[\r\n\\text{\\textbf{PASO 3: CALCULAR LAS DERIVADAS u\'(x) y v\'(x)}} \\\\\r\nu\'(x) = \\frac{d}{dx}(x^2 + 3x - 1) = 2x + 3 \\\\\r\nv\'(x) = \\frac{d}{dx}(2x - 1) = 2\r\n\\]\r\n', 3, '2025-07-23 18:33:54', '2025-07-23 18:33:54'),
(735, 330, '\r\n\\[\r\n\\text{\\textbf{PASO 4: SUSTITUIR EN LA FÓRMULA DE LA REGLA DEL PRODUCTO}} \\\\\r\nf\'(x) = (2x + 3)(2x - 1) + (x^2 + 3x - 1)(2)\r\n\\]\r\n', 4, '2025-07-23 18:33:54', '2025-07-23 18:33:54'),
(736, 330, '\r\n\\[\r\n\\text{\\textbf{PASO 5: EXPANDIR LOS PRODUCTOS}} \\\\\r\n(2x + 3)(2x - 1) = 4x^2 - 2x + 6x - 3 = 4x^2 + 4x - 3 \\\\\r\n(x^2 + 3x - 1)(2) = 2x^2 + 6x - 2\r\n\\]\r\n', 5, '2025-07-23 18:33:54', '2025-07-23 18:33:54'),
(737, 330, '\r\n\\[\r\n\\text{\\textbf{PASO 6: COMBINAR TÉRMINOS SEMEJANTES Y SIMPLIFICAR}} \\\\\r\nf\'(x) = (4x^2 + 4x - 3) + (2x^2 + 6x - 2) \\\\\r\nf\'(x) = 6x^2 + 10x - 5\r\n\\]\r\n', 6, '2025-07-23 18:33:54', '2025-07-23 18:33:54'),
(738, 333, '\r\n\\[\r\n\\text{\\textbf{PASO 1: IDENTIFICAR LAS PARTES u(x) y v(x)}} \\\\\r\nu(x) = x^2 - 2x + 3 \\\\\r\nv(x) = x + 1\r\n\\]\r\n', 1, '2025-07-23 19:27:36', '2025-07-23 19:27:36'),
(739, 333, '\r\n\\[\r\n\\text{\\textbf{PASO 2: APLICAR LA REGLA DEL PRODUCTO}} \\\\\r\n\\text{Si } f(x) = u(x)v(x), \\text{ entonces } f\'(x) = u\'(x)v(x) + u(x)v\'(x)\r\n\\]\r\n', 2, '2025-07-23 19:27:36', '2025-07-23 19:27:36'),
(740, 333, '\r\n\\[\r\n\\text{\\textbf{PASO 3: CALCULAR LAS DERIVADAS u\'(x) y v\'(x)}} \\\\\r\nu\'(x) = \\frac{d}{dx}(x^2 - 2x + 3) = 2x - 2 \\\\\r\nv\'(x) = \\frac{d}{dx}(x + 1) = 1\r\n\\]\r\n', 3, '2025-07-23 19:27:36', '2025-07-23 19:27:36'),
(741, 333, '\r\n\\[\r\n\\text{\\textbf{PASO 4: SUSTITUIR EN LA FÓRMULA DE LA REGLA DEL PRODUCTO}} \\\\\r\nf\'(x) = (2x - 2)(x + 1) + (x^2 - 2x + 3)(2)\r\n\\]\r\n', 4, '2025-07-23 19:27:36', '2025-07-23 19:27:36'),
(742, 333, '\r\n\\[\r\n\\text{\\textbf{PASO 5: EXPANDIR LOS PRODUCTOS}} \\\\\r\n(2x - 2)(x + 1) = 2x^2 + 2x - 2x - 2 = 2x^2 - 2 \\\\\r\n(x^2 - 2x + 3)(1) = x^2 - 2x + 3\r\n\\]\r\n', 5, '2025-07-23 19:27:36', '2025-07-23 19:27:36'),
(743, 333, '\r\n\\[\r\n\\text{\\textbf{PASO 6: COMBINAR TÉRMINOS SEMEJANTES Y SIMPLIFICAR}} \\\\\r\nf\'(x) = (2x^2 - 2) + (x^2 - 2x + 3) \\\\\r\nf\'(x) = 3x^2 - 2x + 1\r\n\\]\r\n', 6, '2025-07-23 19:27:36', '2025-07-23 19:27:36'),
(744, 334, '\r\n\\[\r\n\\text{\\textbf{PASO 1: SIMPLIFICAR LA FUNCIÓN PRIMERO}} \\\\\r\n\\text{Factoriza y cancela el término } x \\text{ en el numerador y denominador (asumiendo } x \\neq 0 \\text{):} \\\\\r\nf(x) = \\frac{x(x-3)}{2x} \\\\\r\nf(x) = \\frac{x-3}{2} \\\\\r\nf(x) = \\frac{1}{2}x - \\frac{3}{2}\r\n\\]\r\n', 1, '2025-07-24 14:58:08', '2025-07-24 14:58:08'),
(745, 334, '\r\n\\[\r\n\\text{\\textbf{PASO 2: APLICAR LAS REGLAS DE DERIVACIÓN}} \\\\\r\n\\text{La derivada de } cx \\text{ es } c. \\\\\r\n\\text{La derivada de una constante es } 0.\r\n\\]\r\n', 2, '2025-07-24 14:58:08', '2025-07-24 14:58:08'),
(746, 334, '\r\n\\[\r\n\\text{\\textbf{PASO 3: DERIVAR CADA TÉRMINO}} \\\\\r\n\\text{Derivada de } \\frac{1}{2}x \\text{ es } \\frac{1}{2}. \\\\\r\n\\text{Derivada de } -\\frac{3}{2} \\text{ (constante) es } 0.\r\n\\]\r\n', 3, '2025-07-24 14:58:08', '2025-07-24 14:58:08'),
(747, 334, '\r\n\\[\r\n\\text{\\textbf{RESULTADO FINAL:}} \\\\\r\nf\'(x) = \\frac{1}{2} - 0 \\\\\r\nf\'(x) = \\frac{1}{2}\r\n\\]\r\n', 4, '2025-07-24 14:58:08', '2025-07-24 14:58:08'),
(748, 335, '\r\n\\[\r\n\\text{\\textbf{PASO 1: SIMPLIFICAR LA FUNCIÓN PRIMERO}} \\\\\r\n\\text{Factoriza el término } x \\text{ en el numerador y cancela:} \\\\\r\nf(x) = \\frac{x(3x-2)}{3x} \\\\\r\n\\text{(Asumiendo } x \\neq 0 \\text{)} \\\\\r\nf(x) = \\frac{3x-2}{3} \\\\\r\nf(x) = \\frac{3x}{3} - \\frac{2}{3} \\\\\r\nf(x) = x - \\frac{2}{3}\r\n\\]\r\n', 1, '2025-07-24 15:42:04', '2025-07-24 15:42:04'),
(749, 335, '\r\n\\[\r\n\\text{\\textbf{PASO 2: APLICAR LAS REGLAS BÁSICAS DE DERIVACIÓN}} \\\\\r\n\\text{La derivada de } x \\text{ es } 1. \\\\\r\n\\text{La derivada de una constante es } 0.\r\n\\]\r\n', 2, '2025-07-24 15:42:04', '2025-07-24 15:42:04'),
(750, 335, '\r\n\\[\r\n\\text{\\textbf{PASO 3: DERIVAR CADA TÉRMINO}} \\\\\r\n\\frac{d}{dx}(x) = 1 \\\\\r\n\\frac{d}{dx}\\left(-\\frac{2}{3}\\right) = 0\r\n\\]\r\n', 3, '2025-07-24 15:42:04', '2025-07-24 15:42:04'),
(751, 335, '\r\n\\[\r\n\\text{\\textbf{RESULTADO FINAL:}} \\\\\r\nf\'(x) = 1 - 0 \\\\\r\nf\'(x) = 1\r\n\\]\r\n', 4, '2025-07-24 15:42:04', '2025-07-24 15:42:04'),
(752, 336, '\r\n\\[\r\n\\text{\\textbf{PASO 1: IDENTIFICAR LAS PARTES u(x) y v(x)}} \\\\\r\nu(x) = 2x^2 + 3x - 1 \\\\\r\nv(x) = x^3 - 8\r\n\\]\r\n', 1, '2025-07-24 20:05:57', '2025-07-24 20:05:57'),
(753, 336, '\r\n\\[\r\n\\text{\\textbf{PASO 2: APLICAR LA REGLA DEL COCIENTE}} \\\\\r\n\\text{Si } f(x) = \\frac{u(x)}{v(x)}, \\text{ entonces } f\'(x) = \\frac{u\'(x)v(x) - u(x)v\'(x)}{(v(x))^2}\r\n\\]\r\n', 2, '2025-07-24 20:05:57', '2025-07-24 20:05:57'),
(754, 336, '\r\n\\[\r\n\\text{\\textbf{PASO 3: CALCULAR LAS DERIVADAS u\'(x) y v\'(x)}} \\\\\r\nu\'(x) = \\frac{d}{dx}(2x^2 + 3x - 1) = 4x + 3 \\\\\r\nv\'(x) = \\frac{d}{dx}(x^3 - 8) = 3x^2\r\n\\]\r\n', 3, '2025-07-24 20:05:57', '2025-07-24 20:05:57'),
(755, 336, '\r\n\\[\r\n\\text{\\textbf{PASO 4: SUSTITUIR EN LA FÓRMULA DE LA REGLA DEL COCIENTE}} \\\\\r\nf\'(x) = \\frac{(4x + 3)(x^3 - 8) - (2x^2 + 3x - 1)(3x^2)}{(x^3 - 8)^2}\r\n\\]\r\n', 4, '2025-07-24 20:05:57', '2025-07-24 20:05:57'),
(756, 336, '\r\n\\[\r\n\\text{\\textbf{PASO 5: EXPANDIR LOS PRODUCTOS EN EL NUMERADOR}} \\\\\r\n(4x + 3)(x^3 - 8) = 4x^4 - 32x + 3x^3 - 24 \\\\\r\n(2x^2 + 3x - 1)(3x^2) = 6x^4 + 9x^3 - 3x^2 \\\\\r\n\\text{Numerador} = (4x^4 - 32x + 3x^3 - 24) - (6x^4 + 9x^3 - 3x^2)\r\n\\]\r\n', 5, '2025-07-24 20:05:57', '2025-07-24 20:05:57'),
(757, 336, '\r\n\\[\r\n\\text{\\textbf{PASO 6: SIMPLIFICAR Y COMBINAR TÉRMINOS EN EL NUMERADOR}} \\\\\r\n\\text{Numerador} = 4x^4 - 32x + 3x^3 - 24 - 6x^4 - 9x^3 + 3x^2 \\\\\r\n\\text{Numerador} = -2x^4 - 6x^3 + 3x^2 - 32x - 24\r\n\\]\r\n', 6, '2025-07-24 20:05:57', '2025-07-24 20:05:57'),
(758, 336, '\r\n\\[\r\n\\text{\\textbf{RESULTADO FINAL:}} \\\\\r\nf\'(x) = \\frac{-2x^4 - 6x^3 + 3x^2 - 32x - 24}{(x^3 - 8)^2}\r\n\\]\r\n', 7, '2025-07-24 20:05:57', '2025-07-24 20:05:57'),
(759, 337, '\r\n\\[\r\n\\text{\\textbf{PASO 1: IDENTIFICAR LAS PARTES u(x) y v(x)}} \\\\\r\nu(x) = 3x^2 - 2x + 1 \\\\\r\nv(x) = x^2 - 4\r\n\\]\r\n', 1, '2025-07-24 21:07:29', '2025-07-24 21:07:29'),
(760, 337, '\r\n\\[\r\n\\text{\\textbf{PASO 2: APLICAR LA REGLA DEL COCIENTE}} \\\\\r\n\\text{Si } f(x) = \\frac{u(x)}{v(x)}, \\text{ entonces } f\'(x) = \\frac{u\'(x)v(x) - u(x)v\'(x)}{(v(x))^2}\r\n\\]\r\n', 2, '2025-07-24 21:07:29', '2025-07-24 21:07:29'),
(761, 337, '\r\n\\[\r\n\\text{\\textbf{PASO 3: CALCULAR LAS DERIVADAS u\'(x) y v\'(x)}} \\\\\r\nu\'(x) = \\frac{d}{dx}(3x^2 - 2x + 1) = 6x - 2 \\\\\r\nv\'(x) = \\frac{d}{dx}(x^2 - 4) = 2x\r\n\\]\r\n', 3, '2025-07-24 21:07:29', '2025-07-24 21:07:29'),
(762, 337, '\r\n\\[\r\n\\text{\\textbf{PASO 4: SUSTITUIR EN LA FÓRMULA DE LA REGLA DEL COCIENTE}} \\\\\r\nf\'(x) = \\frac{(6x - 2)(x^2 - 4) - (3x^2 - 2x + 1)(2x)}{(x^2 - 4)^2}\r\n\\]\r\n', 4, '2025-07-24 21:07:29', '2025-07-24 21:07:29'),
(763, 337, '\r\n\\[\r\n\\text{\\textbf{PASO 5: EXPANDIR LOS PRODUCTOS EN EL NUMERADOR}} \\\\\r\n(6x - 2)(x^2 - 4) = 6x^3 - 24x - 2x^2 + 8 \\\\\r\n(3x^2 - 2x + 1)(2x) = 6x^3 - 4x^2 + 2x \\\\\r\n\\text{Numerador} = (6x^3 - 2x^2 - 24x + 8) - (6x^3 - 4x^2 + 2x)\r\n\\]\r\n', 5, '2025-07-24 21:07:29', '2025-07-24 21:07:29'),
(764, 337, '\r\n\\[\r\n\\text{\\textbf{PASO 6: SIMPLIFICAR Y COMBINAR TÉRMINOS EN EL NUMERADOR}} \\\\\r\n\\text{Numerador} = 6x^3 - 2x^2 - 24x + 8 - 6x^3 + 4x^2 - 2x \\\\\r\n\\text{Numerador} = 2x^2 - 26x + 8\r\n\\]\r\n', 6, '2025-07-24 21:07:29', '2025-07-24 21:07:29'),
(765, 337, '\r\n\\[\r\n\\text{\\textbf{RESULTADO FINAL:}} \\\\\r\nf\'(x) = \\frac{2x^2 - 26x + 8}{(x^2 - 4)^2}\r\n\\]\r\n', 7, '2025-07-24 21:07:29', '2025-07-24 21:07:29'),
(766, 338, '\r\n\\[\r\n\\text{\\textbf{PASO 1: IDENTIFICAR LA FORMA DE LA FUNCIÓN}} \\\\\r\n\\text{La función es de la forma } f(x) = [g(x)]^n\r\n\\]\r\n', 1, '2025-07-24 21:19:28', '2025-07-24 21:19:28'),
(767, 338, '\r\n\\[\r\n\\text{\\textbf{PASO 2: APLICAR LA REGLA DE LA CADENA}} \\\\\r\n\\text{La derivada se calcula como: } f\'(x) = n[g(x)]^{n-1} \\cdot g\'(x)\r\n\\]\r\n', 2, '2025-07-24 21:19:28', '2025-07-24 21:19:28'),
(768, 338, '\r\n\\[\r\n\\text{\\textbf{PASO 3: IDENTIFICAR g(x) y n}} \\\\\r\ng(x) = 2x^2 - 5x + 1 \\\\\r\nn = 5\r\n\\]\r\n', 3, '2025-07-24 21:19:28', '2025-07-24 21:19:28'),
(769, 338, '\r\n\\[\r\n\\text{\\textbf{PASO 4: CALCULAR LA DERIVADA DE g(x)}} \\\\\r\ng\'(x) = \\frac{d}{dx}(2x^2 - 5x + 1) = 4x - 5\r\n\\]\r\n', 4, '2025-07-24 21:19:28', '2025-07-24 21:19:28'),
(770, 338, '\r\n\\[\r\n\\text{\\textbf{PASO 5: SUSTITUIR EN LA FÓRMULA DE LA REGLA DE LA CADENA}} \\\\\r\nf\'(x) = 5(2x^2 - 5x + 1)^{5-1} (4x - 5)\r\n\\]\r\n', 5, '2025-07-24 21:19:28', '2025-07-24 21:19:28'),
(771, 338, '\r\n\\[\r\n\\text{\\textbf{PASO 6: SIMPLIFICAR}} \\\\\r\nf\'(x) = 5(2x^2 - 5x + 1)^4 (4x - 5)\r\n\\]\r\n', 6, '2025-07-24 21:19:28', '2025-07-24 21:19:28'),
(772, 339, '\r\n\\[\r\n\\text{\\textbf{PASO 1: IDENTIFICAR LA FORMA DE LA FUNCIÓN}} \\\\\r\n\\text{La función es de la forma } f(x) = [g(x)]^n\r\n\\]\r\n', 1, '2025-07-24 21:23:02', '2025-07-24 21:23:02'),
(773, 339, '\r\n\\[\r\n\\text{\\textbf{PASO 2: APLICAR LA REGLA DE LA CADENA}} \\\\\r\n\\text{La derivada se calcula como: } f\'(x) = n[g(x)]^{n-1} \\cdot g\'(x)\r\n\\]\r\n', 2, '2025-07-24 21:23:02', '2025-07-24 21:23:02'),
(774, 339, '\r\n\\[\r\n\\text{\\textbf{PASO 3: IDENTIFICAR g(x) y n}} \\\\\r\ng(x) = 2x^3 - 3x - 2 \\\\\r\nn = 4\r\n\\]\r\n', 3, '2025-07-24 21:23:02', '2025-07-24 21:23:02'),
(775, 339, '\r\n\\[\r\n\\text{\\textbf{PASO 4: CALCULAR LA DERIVADA DE g(x)}} \\\\\r\ng\'(x) = \\frac{d}{dx}(2x^3 - 3x - 2) = 6x^2 - 3\r\n\\]\r\n', 4, '2025-07-24 21:23:02', '2025-07-24 21:23:02'),
(776, 339, '\r\n\\[\r\n\\text{\\textbf{PASO 5: SUSTITUIR EN LA FÓRMULA DE LA REGLA DE LA CADENA}} \\\\\r\nf\'(x) = 4(2x^3 - 3x - 2)^{4-1} (6x^2 - 3) \\\\\r\nf\'(x) = 4(2x^3 - 3x - 2)^3 (6x^2 - 3)\r\n\\]\r\n', 5, '2025-07-24 21:23:02', '2025-07-24 21:23:02'),
(777, 339, '\r\n\\[\r\n\\text{\\textbf{PASO 6: SIMPLIFICAR LA EXPRESIÓN (Factorizar)}} \\\\\r\n\\text{Observa que } (6x^2 - 3) \\text{ se puede factorizar como } 3(2x^2 - 1). \\\\\r\nf\'(x) = 4(2x^3 - 3x - 2)^3 \\cdot 3(2x^2 - 1)\r\n\\]\r\n', 6, '2025-07-24 21:23:02', '2025-07-24 21:23:02'),
(778, 339, '\r\n\\[\r\n\\text{\\textbf{RESULTADO FINAL:}} \\\\\r\nf\'(x) = 12(2x^3 - 3x - 2)^3 (2x^2 - 1)\r\n\\]\r\n', 7, '2025-07-24 21:23:02', '2025-07-24 21:23:02'),
(779, 340, '\r\n\\[\r\n\\text{\\textbf{PASO 1: IDENTIFICAR LA FORMA DE LA FUNCIÓN}} \\\\\r\n\\text{La función es de la forma } f(x) = [g(x)]^n\r\n\\]\r\n', 1, '2025-07-25 01:02:53', '2025-07-25 01:02:53'),
(780, 340, '\r\n\\[\r\n\\text{\\textbf{PASO 2: APLICAR LA REGLA DE LA CADENA}} \\\\\r\n\\text{La derivada se calcula como: } f\'(x) = n[g(x)]^{n-1} \\cdot g\'(x)\r\n\\]\r\n', 2, '2025-07-25 01:02:53', '2025-07-25 01:02:53'),
(781, 340, '\r\n\\[\r\n\\text{\\textbf{PASO 3: IDENTIFICAR g(x) y n}} \\\\\r\ng(x) = 3 - 2x - 3x^2 \\\\\r\nn = 2\r\n\\]\r\n', 3, '2025-07-25 01:02:53', '2025-07-25 01:02:53'),
(782, 340, '\r\n\\[\r\n\\text{\\textbf{PASO 4: CALCULAR LA DERIVADA DE g(x)}} \\\\\r\ng\'(x) = \\frac{d}{dx}(3 - 2x - 3x^2) = -2 - 6x\r\n\\]\r\n', 4, '2025-07-25 01:02:53', '2025-07-25 01:02:53'),
(783, 340, '\r\n\\[\r\n\\text{\\textbf{PASO 5: SUSTITUIR EN LA FÓRMULA DE LA REGLA DE LA CADENA}} \\\\\r\nf\'(x) = 2(3 - 2x - 3x^2)^{2-1} (-2 - 6x) \\\\\r\nf\'(x) = 2(3 - 2x - 3x^2)(-2 - 6x)\r\n\\]\r\n', 5, '2025-07-25 01:02:53', '2025-07-25 01:02:53'),
(784, 340, '\r\n\\[\r\n\\text{\\textbf{PASO 6: EXPANDIR Y SIMPLIFICAR LA EXPRESIÓN}} \\\\\r\n\\text{Primero, factoriza } -2 \\text{ del segundo término: } \\\\\r\nf\'(x) = 2(3 - 2x - 3x^2) \\cdot [-2(1 + 3x)] \\\\\r\nf\'(x) = -4(3 - 2x - 3x^2)(1 + 3x) \\\\\r\n\\text{Ahora, expande los binomios:} \\\\\r\n(3 - 2x - 3x^2)(1 + 3x) = 3(1) + 3(3x) - 2x(1) - 2x(3x) - 3x^2(1) - 3x^2(3x) \\\\\r\n= 3 + 9x - 2x - 6x^2 - 3x^2 - 9x^3 \\\\\r\n= -9x^3 - 9x^2 + 7x + 3\r\n\\]\r\n', 6, '2025-07-25 01:02:53', '2025-07-25 01:02:53'),
(785, 340, '\r\n\\[\r\n\\text{\\textbf{PASO 7: MULTIPLICAR POR EL COEFICIENTE EXTERNO FINAL}} \\\\\r\nf\'(x) = -4(-9x^3 - 9x^2 + 7x + 3) \\\\\r\nf\'(x) = 36x^3 + 36x^2 - 28x - 12\r\n\\]\r\n', 7, '2025-07-25 01:02:53', '2025-07-25 01:02:53'),
(786, 341, '\r\n\\[\r\n\\text{\\textbf{PASO 1: IDENTIFICAR LA FORMA DE LA FUNCIÓN}} \\\\\r\n\\text{La función es de la forma } f(x) = [g(x)]^n\r\n\\]\r\n', 1, '2025-07-25 01:32:26', '2025-07-25 01:32:26'),
(787, 341, '\r\n\\[\r\n\\text{\\textbf{PASO 2: APLICAR LA REGLA DE LA CADENA}} \\\\\r\n\\text{La derivada se calcula como: } f\'(x) = n[g(x)]^{n-1} \\cdot g\'(x)\r\n\\]\r\n', 2, '2025-07-25 01:32:26', '2025-07-25 01:32:26'),
(788, 341, '\r\n\\[\r\n\\text{\\textbf{PASO 3: IDENTIFICAR g(x) y n}} \\\\\r\ng(x) = 1 - 3x - 2x^2 \\\\\r\nn = 2\r\n\\]\r\n', 3, '2025-07-25 01:32:26', '2025-07-25 01:32:26'),
(789, 341, '\r\n\\[\r\n\\text{\\textbf{PASO 4: CALCULAR LA DERIVADA DE g(x)}} \\\\\r\ng\'(x) = \\frac{d}{dx}(1 - 3x - 2x^2) = -3 - 4x\r\n\\]\r\n', 4, '2025-07-25 01:32:26', '2025-07-25 01:32:26'),
(790, 341, '\r\n\\[\r\n\\text{\\textbf{PASO 5: SUSTITUIR EN LA FÓRMULA DE LA REGLA DE LA CADENA}} \\\\\r\nf\'(x) = 2(1 - 3x - 2x^2)^{2-1} (-3 - 4x) \\\\\r\nf\'(x) = 2(1 - 3x - 2x^2)(-3 - 4x)\r\n\\]\r\n', 5, '2025-07-25 01:32:26', '2025-07-25 01:32:26'),
(791, 341, '\r\n\\[\r\n\\text{\\textbf{PASO 6: SIMPLIFICAR EL COEFICIENTE EXTERNO}} \\\\\r\n\\text{Factoriza } -1 \\text{ de } (-3 - 4x): \\\\\r\nf\'(x) = 2(1 - 3x - 2x^2) \\cdot (-1)(3 + 4x) \\\\\r\nf\'(x) = -2(1 - 3x - 2x^2)(3 + 4x)\r\n\\]\r\n', 6, '2025-07-25 01:32:26', '2025-07-25 01:32:26'),
(792, 341, '\r\n\\[\r\n\\text{\\textbf{PASO 7: EXPANDIR LOS BINOMIOS}} \\\\\r\n(1 - 3x - 2x^2)(3 + 4x) = \\\\\r\n1(3) + 1(4x) - 3x(3) - 3x(4x) - 2x^2(3) - 2x^2(4x) \\\\\r\n= 3 + 4x - 9x - 12x^2 - 6x^2 - 8x^3 \\\\\r\n= -8x^3 - 18x^2 - 5x + 3\r\n\\]\r\n', 7, '2025-07-25 01:32:26', '2025-07-25 01:32:26'),
(793, 341, '\r\n\\[\r\n\\text{\\textbf{PASO 8: MULTIPLICAR POR EL COEFICIENTE EXTERNO FINAL}} \\\\\r\nf\'(x) = -2(-8x^3 - 18x^2 - 5x + 3) \\\\\r\nf\'(x) = 16x^3 + 36x^2 + 10x - 6\r\n\\]\r\n', 8, '2025-07-25 01:32:26', '2025-07-25 01:32:26'),
(794, 342, '\r\n\\[\r\n\\text{\\textbf{PASO 1: REESCRIBIR LA FUNCIÓN CON EXPONENTE FRACCIONARIO}} \\\\\r\nf(x) = (4x-5)^{1/2}\r\n\\]\r\n', 1, '2025-07-26 00:52:43', '2025-07-26 00:52:43'),
(795, 342, '\r\n\\[\r\n\\text{\\textbf{PASO 2: IDENTIFICAR LA FORMA DE LA FUNCIÓN}} \\\\\r\n\\text{La función es de la forma } f(x) = [g(x)]^n \\text{, donde:}\\\r\ng(x) = 4x-5 \\\\\r\nn = \\frac{1}{2}\r\n\\]\r\n', 2, '2025-07-26 00:52:43', '2025-07-26 00:52:43'),
(796, 342, '\r\n\\[\r\n\\text{\\textbf{PASO 3: APLICAR LA REGLA DE LA CADENA}} \\\\\r\n\\text{La derivada se calcula como: } f\'(x) = n[g(x)]^{n-1} \\cdot g\'(x)\r\n\\]\r\n', 3, '2025-07-26 00:52:43', '2025-07-26 00:52:43'),
(797, 342, '\r\n\\[\r\n\\text{\\textbf{PASO 4: CALCULAR LA DERIVADA DE g(x)}} \\\\\r\ng\'(x) = \\frac{d}{dx}(4x-5) = 4\r\n\\]\r\n', 4, '2025-07-26 00:52:43', '2025-07-26 00:52:43'),
(798, 342, '\r\n\\[\r\n\\text{\\textbf{PASO 5: SUSTITUIR EN LA FÓRMULA DE LA REGLA DE LA CADENA}} \\\\\r\nf\'(x) = \\frac{1}{2}(4x-5)^{(\\frac{1}{2}-1)} \\cdot (4) \\\\\r\nf\'(x) = \\frac{1}{2}(4x-5)^{-\\frac{1}{2}} \\cdot 4\r\n\\]\r\n', 5, '2025-07-26 00:52:43', '2025-07-26 00:52:43'),
(799, 342, '\r\n\\[\r\n\\text{\\textbf{PASO 6: SIMPLIFICAR Y REESCRIBIR CON EXPONENTE POSITIVO}} \\\\\r\nf\'(x) = \\frac{4}{2}(4x-5)^{-\\frac{1}{2}} \\\\\r\nf\'(x) = 2(4x-5)^{-\\frac{1}{2}} \\\\\r\nf\'(x) = \\frac{2}{(4x-5)^{1/2}}\r\n\\]\r\n', 6, '2025-07-26 00:52:43', '2025-07-26 00:52:43'),
(800, 342, '\r\n\\[\r\n\\text{\\textbf{PASO 7: EXPRESAR EN FORMA DE RAÍZ CUADRADA}} \\\\\r\nf\'(x) = \\frac{2}{\\sqrt{4x-5}}\r\n\\]\r\n', 7, '2025-07-26 00:52:43', '2025-07-26 00:52:43'),
(801, 343, '\r\n\\[\r\n\\text{\\textbf{PASO 1: REESCRIBIR LA FUNCIÓN CON EXPONENTE FRACCIONARIO}} \\\\\r\nf(x) = (6x+1)^{1/2}\r\n\\]\r\n', 1, '2025-07-26 00:55:06', '2025-07-26 00:55:06'),
(802, 343, '\r\n\\[\r\n\\text{\\textbf{PASO 2: IDENTIFICAR LA FORMA DE LA FUNCIÓN}} \\\\\r\n\\text{La función es de la forma } f(x) = [g(x)]^n \\text{, donde:}\\\r\ng(x) = 6x+1 \\\\\r\nn = \\frac{1}{2}\r\n\\]\r\n', 2, '2025-07-26 00:55:06', '2025-07-26 00:55:06'),
(803, 343, '\r\n\\[\r\n\\text{\\textbf{PASO 3: APLICAR LA REGLA DE LA CADENA}} \\\\\r\n\\text{La derivada se calcula como: } f\'(x) = n[g(x)]^{n-1} \\cdot g\'(x)\r\n\\]\r\n', 3, '2025-07-26 00:55:06', '2025-07-26 00:55:06'),
(804, 343, '\r\n\\[\r\n\\text{\\textbf{PASO 4: CALCULAR LA DERIVADA DE g(x)}} \\\\\r\ng\'(x) = \\frac{d}{dx}(6x+1) = 6\r\n\\]\r\n', 4, '2025-07-26 00:55:06', '2025-07-26 00:55:06'),
(805, 343, '\r\n\\[\r\n\\text{\\textbf{PASO 5: SUSTITUIR EN LA FÓRMULA DE LA REGLA DE LA CADENA}} \\\\\r\nf\'(x) = \\frac{1}{2}(6x+1)^{(\\frac{1}{2}-1)} \\cdot (6) \\\\\r\nf\'(x) = \\frac{1}{2}(6x+1)^{-\\frac{1}{2}} \\cdot 6\r\n\\]\r\n', 5, '2025-07-26 00:55:06', '2025-07-26 00:55:06'),
(806, 343, '\r\n\\[\r\n\\text{\\textbf{PASO 6: SIMPLIFICAR Y REESCRIBIR CON EXPONENTE POSITIVO}} \\\\\r\nf\'(x) = \\frac{6}{2}(6x+1)^{-\\frac{1}{2}} \\\\\r\nf\'(x) = 3(6x+1)^{-\\frac{1}{2}} \\\\\r\nf\'(x) = \\frac{3}{(6x+1)^{1/2}}\r\n\\]\r\n', 6, '2025-07-26 00:55:06', '2025-07-26 00:55:06'),
(807, 343, '\r\n\\[\r\n\\text{\\textbf{PASO 7: EXPRESAR EN FORMA DE RAÍZ CUADRADA}} \\\\\r\nf\'(x) = \\frac{3}{\\sqrt{6x+1}}\r\n\\]\r\n', 7, '2025-07-26 00:55:06', '2025-07-26 00:55:06'),
(808, 344, '\r\n\\[\r\n\\text{\\textbf{PASO 1: REESCRIBIR LA FUNCIÓN CON EXPONENTE FRACCIONARIO}} \\\\\r\nf(x) = (x^3-3x+3)^{1/3}\r\n\\]\r\n', 1, '2025-07-26 01:13:54', '2025-07-26 01:13:54'),
(809, 344, '\r\n\\[\r\n\\text{\\textbf{PASO 2: IDENTIFICAR LA FORMA DE LA FUNCIÓN}} \\\\\r\n\\text{La función es de la forma } f(x) = [g(x)]^n \\text{, donde:}\\\r\ng(x) = x^3-3x+3 \\\\\r\nn = \\frac{1}{3}\r\n\\]\r\n', 2, '2025-07-26 01:13:54', '2025-07-26 01:13:54'),
(810, 344, '\r\n\\[\r\n\\text{\\textbf{PASO 3: APLICAR LA REGLA DE LA CADENA}} \\\\\r\n\\text{La derivada se calcula como: } f\'(x) = n[g(x)]^{n-1} \\cdot g\'(x)\r\n\\]\r\n', 3, '2025-07-26 01:13:54', '2025-07-26 01:13:54'),
(811, 344, '\r\n\\[\r\n\\text{\\textbf{PASO 4: CALCULAR LA DERIVADA DE g(x)}} \\\\\r\ng\'(x) = \\frac{d}{dx}(x^3-3x+3) = 3x^2 - 3\r\n\\]\r\n', 4, '2025-07-26 01:13:54', '2025-07-26 01:13:54'),
(812, 344, '\r\n\\[\r\n\\text{\\textbf{PASO 5: SUSTITUIR EN LA FÓRMULA DE LA REGLA DE LA CADENA}} \\\\\r\nf\'(x) = \\frac{1}{3}(x^3-3x+3)^{(\\frac{1}{3}-1)} \\cdot (3x^2 - 3) \\\\\r\nf\'(x) = \\frac{1}{3}(x^3-3x+3)^{-\\frac{2}{3}} \\cdot (3x^2 - 3)\r\n\\]\r\n', 5, '2025-07-26 01:13:54', '2025-07-26 01:13:54'),
(813, 344, '\r\n\\[\r\n\\text{\\textbf{PASO 6: SIMPLIFICAR Y REESCRIBIR CON EXPONENTE POSITIVO}} \\\\\r\n\\text{Factoriza 3 de } (3x^2 - 3) \\text{, entonces:} \\\\\r\nf\'(x) = \\frac{1}{3}(x^3-3x+3)^{-\\frac{2}{3}} \\cdot 3(x^2 - 1) \\\\\r\nf\'(x) = (x^3-3x+3)^{-\\frac{2}{3}} (x^2 - 1) \\\\\r\nf\'(x) = \\frac{x^2 - 1}{(x^3-3x+3)^{2/3}}\r\n\\]\r\n', 6, '2025-07-26 01:13:54', '2025-07-26 01:13:54'),
(814, 344, '\r\n\\[\r\n\\text{\\textbf{PASO 7: EXPRESAR EN FORMA DE RAÍZ CÚBICA}} \\\\\r\nf\'(x) = \\frac{x^2 - 1}{\\sqrt[3]{(x^3-3x+3)^2}}\r\n\\]\r\n', 7, '2025-07-26 01:13:54', '2025-07-26 01:13:54'),
(815, 345, '\r\n\\[\r\n\\text{\\textbf{PASO 1: REESCRIBIR LA FUNCIÓN CON EXPONENTE FRACCIONARIO}} \\\\\r\nf(x) = (2x^3+6x-5)^{1/3}\r\n\\]\r\n', 1, '2025-07-26 01:16:07', '2025-07-26 01:16:07'),
(816, 345, '\r\n\\[\r\n\\text{\\textbf{PASO 2: IDENTIFICAR LA FORMA DE LA FUNCIÓN}} \\\\\r\n\\text{La función es de la forma } f(x) = [g(x)]^n \\text{, donde:}\\\r\ng(x) = 2x^3+6x-5 \\\\\r\nn = \\frac{1}{3}\r\n\\]\r\n', 2, '2025-07-26 01:16:07', '2025-07-26 01:16:07'),
(817, 345, '\r\n\\[\r\n\\text{\\textbf{PASO 3: APLICAR LA REGLA DE LA CADENA}} \\\\\r\n\\text{La derivada se calcula como: } f\'(x) = n[g(x)]^{n-1} \\cdot g\'(x)\r\n\\]\r\n', 3, '2025-07-26 01:16:07', '2025-07-26 01:16:07'),
(818, 345, '\r\n\\[\r\n\\text{\\textbf{PASO 4: CALCULAR LA DERIVADA DE g(x)}} \\\\\r\ng\'(x) = \\frac{d}{dx}(2x^3+6x-5) = 6x^2 + 6\r\n\\]\r\n', 4, '2025-07-26 01:16:07', '2025-07-26 01:16:07'),
(819, 345, '\r\n\\[\r\n\\text{\\textbf{PASO 5: SUSTITUIR EN LA FÓRMULA DE LA REGLA DE LA CADENA}} \\\\\r\nf\'(x) = \\frac{1}{3}(2x^3+6x-5)^{(\\frac{1}{3}-1)} \\cdot (6x^2 + 6) \\\\\r\nf\'(x) = \\frac{1}{3}(2x^3+6x-5)^{-\\frac{2}{3}} \\cdot (6x^2 + 6)\r\n\\]\r\n', 5, '2025-07-26 01:16:07', '2025-07-26 01:16:07'),
(820, 345, '\r\n\\[\r\n\\text{\\textbf{PASO 6: SIMPLIFICAR Y REESCRIBIR CON EXPONENTE POSITIVO}} \\\\\r\n\\text{Factoriza 6 de } (6x^2 + 6) \\text{, entonces:} \\\\\r\nf\'(x) = \\frac{1}{3}(2x^3+6x-5)^{-\\frac{2}{3}} \\cdot 6(x^2 + 1) \\\\\r\nf\'(x) = \\frac{6}{3}(2x^3+6x-5)^{-\\frac{2}{3}} (x^2 + 1) \\\\\r\nf\'(x) = 2(2x^3+6x-5)^{-\\frac{2}{3}} (x^2 + 1) \\\\\r\nf\'(x) = \\frac{2(x^2 + 1)}{(2x^3+6x-5)^{2/3}}\r\n\\]\r\n', 6, '2025-07-26 01:16:07', '2025-07-26 01:16:07'),
(821, 345, '\r\n\\[\r\n\\text{\\textbf{PASO 7: EXPRESAR EN FORMA DE RAÍZ CÚBICA}} \\\\\r\nf\'(x) = \\frac{2(x^2 + 1)}{\\sqrt[3]{(2x^3+6x-5)^2}}\r\n\\]\r\n', 7, '2025-07-26 01:16:07', '2025-07-26 01:16:07'),
(826, 348, '\r\n\\[\r\n\\text{\\textbf{PASO 1: IDENTIFICAR LA REGLA DE DERIVACIÓN A APLICAR}} \\\\\r\n\\text{Para derivar } f(x) = \\sin(g(x)), \\text{ se debe aplicar la Regla de la Cadena.}\\\r\n\\text{La fórmula es: } f\'(x) = \\cos(g(x)) \\cdot g\'(x).\r\n\\]\r\n', 1, '2025-07-27 19:31:52', '2025-07-27 19:31:52'),
(827, 348, '\r\n\\[\r\n\\text{\\textbf{PASO 2: IDENTIFICAR g(x) Y CALCULAR SU DERIVADA g\'(x)}} \\\\\r\n\\text{En la función } f(x) = \\sin(2x^7), \\text{ la función interna es } g(x) = 2x^7.\\\\\r\n\\text{Ahora, calcula su derivada: } g\'(x) = \\frac{d}{dx}(2x^7) = 2 \\cdot 7x^{7-1} = 14x^6.\r\n\\]\r\n', 2, '2025-07-27 19:31:52', '2025-07-27 19:31:52'),
(828, 348, '\r\n\\[\r\n\\text{\\textbf{PASO 3: APLICAR LA REGLA DE LA CADENA}} \\\\\r\n\\text{Sustituye } g(x) \\text{ y } g\'(x) \\text{ en la fórmula de la regla de la cadena:}\\\\\r\nf\'(x) = \\cos(g(x)) \\cdot g\'(x) \\\\\r\nf\'(x) = \\cos(2x^7) \\cdot (14x^6)\r\n\\]\r\n', 3, '2025-07-27 19:31:52', '2025-07-27 19:31:52'),
(829, 348, '\r\n\\[\r\n\\text{\\textbf{PASO 4: ESCRIBIR EL RESULTADO FINAL DE FORMA ESTÁNDAR}} \\\\\r\n\\text{Generalmente, el término polinomial se coloca antes de la función trigonométrica.}\\\r\nf\'(x) = 14x^6 \\cos(2x^7)\r\n\\]\r\n', 4, '2025-07-27 19:31:52', '2025-07-27 19:31:52'),
(830, 349, '\r\n\\[\r\n\\text{\\textbf{PASO 1: IDENTIFICAR LA REGLA DE DERIVACIÓN A APLICAR}} \\\\\r\n\\text{Para derivar } f(x) = \\tan(g(x)), \\text{ se debe aplicar la Regla de la Cadena.}\\\r\n\\text{La fórmula es: } f\'(x) = \\sec^2(g(x)) \\cdot g\'(x).\r\n\\]\r\n', 1, '2025-07-27 19:34:21', '2025-07-27 19:34:21'),
(831, 349, '\r\n\\[\r\n\\text{\\textbf{PASO 2: IDENTIFICAR g(x) Y CALCULAR SU DERIVADA g\'(x)}} \\\\\r\n\\text{En la función } f(x) = \\tan(x^2-1), \\text{ la función interna es } g(x) = x^2-1.\\\\\r\n\\text{Ahora, calcula su derivada: } g\'(x) = \\frac{d}{dx}(x^2-1) = 2x.\r\n\\]\r\n', 2, '2025-07-27 19:34:21', '2025-07-27 19:34:21'),
(832, 349, '\r\n\\[\r\n\\text{\\textbf{PASO 3: APLICAR LA REGLA DE LA CADENA}} \\\\\r\n\\text{Sustituye } g(x) \\text{ y } g\'(x) \\text{ en la fórmula de la regla de la cadena:}\\\\\r\nf\'(x) = \\sec^2(g(x)) \\cdot g\'(x) \\\\\r\nf\'(x) = \\sec^2(x^2-1) \\cdot (2x)\r\n\\]\r\n', 3, '2025-07-27 19:34:21', '2025-07-27 19:34:21'),
(833, 349, '\r\n\\[\r\n\\text{\\textbf{PASO 4: ESCRIBIR EL RESULTADO FINAL DE FORMA ESTÁNDAR}} \\\\\r\n\\text{Generalmente, el término polinomial se coloca antes de la función trigonométrica.}\\\r\nf\'(x) = 2x \\sec^2(x^2-1)\r\n\\]\r\n', 4, '2025-07-27 19:34:21', '2025-07-27 19:34:21'),
(834, 350, '\r\n\\[\r\n\\text{\\textbf{PASO 1: IDENTIFICAR LA REGLA DE DERIVACIÓN A APLICAR}} \\\\\r\n\\text{Para derivar } f(x) = \\tan(g(x)), \\text{ se debe aplicar la Regla de la Cadena.}\\\r\n\\text{La fórmula es: } f\'(x) = \\sec^2(g(x)) \\cdot g\'(x).\r\n\\]\r\n', 1, '2025-07-27 19:37:46', '2025-07-27 19:37:46'),
(835, 350, '\r\n\\[\r\n\\text{\\textbf{PASO 2: IDENTIFICAR g(x) Y CALCULAR SU DERIVADA g\'(x)}} \\\\\r\n\\text{En la función } f(x) = \\tan(3x^2+2x-5), \\text{ la función interna es } g(x) = 3x^2+2x-5.\\\\\r\n\\text{Ahora, calcula su derivada: } g\'(x) = \\frac{d}{dx}(3x^2+2x-5) = 6x+2.\r\n\\]\r\n', 2, '2025-07-27 19:37:46', '2025-07-27 19:37:46'),
(836, 350, '\r\n\\[\r\n\\text{\\textbf{PASO 3: APLICAR LA REGLA DE LA CADENA}} \\\\\r\n\\text{Sustituye } g(x) \\text{ y } g\'(x) \\text{ en la fórmula de la regla de la cadena:}\\\\\r\nf\'(x) = \\sec^2(3x^2+2x-5) \\cdot (6x+2)\r\n\\]\r\n', 3, '2025-07-27 19:37:46', '2025-07-27 19:37:46'),
(837, 350, '\r\n\\[\r\n\\text{\\textbf{PASO 4: SIMPLIFICAR Y ESCRIBIR EL RESULTADO FINAL}} \\\\\r\n\\text{El término polinomial } (6x+2) \\text{ se puede factorizar como } 2(3x+1).\\\r\n\\text{Por lo tanto: } f\'(x) = 2(3x+1) \\sec^2(3x^2+2x-5).\r\n\\]\r\n', 4, '2025-07-27 19:37:46', '2025-07-27 19:37:46'),
(838, 351, '\r\n\\[\r\n\\text{\\textbf{PASO 1: REESCRIBIR LA FUNCIÓN E IDENTIFICAR LA REGLA DE DERIVACIÓN}} \\\\\r\n\\text{La función se puede reescribir como } f(x) = \\csc(x^{1/2}).\\ \\text{Se debe aplicar la Regla de la Cadena.}\\\r\n\\text{La fórmula para derivar la cosecante es: } \\frac{d}{dx}[\\csc(u)] = -\\csc(u)\\cot(u) \\cdot u\'.\r\n\\]\r\n', 1, '2025-07-27 19:58:12', '2025-07-27 19:58:12'),
(839, 351, '\r\n\\[\r\n\\text{\\textbf{PASO 2: IDENTIFICAR u Y CALCULAR SU DERIVADA u\'}} \\\\\r\n\\text{En este caso, } u = \\sqrt{x} = x^{1/2}.\\ \\text{Ahora, calcula su derivada:}\\\\\r\nu\' = \\frac{d}{dx}(x^{1/2}) = \\frac{1}{2}x^{\\frac{1}{2}-1} = \\frac{1}{2}x^{-\\frac{1}{2}} = \\frac{1}{2\\sqrt{x}}.\r\n\\]\r\n', 2, '2025-07-27 19:58:12', '2025-07-27 19:58:12'),
(840, 351, '\r\n\\[\r\n\\text{\\textbf{PASO 3: APLICAR LA FÓRMULA DE LA DERIVADA DE LA COSECANTE}} \\\\\r\n\\text{Sustituye } u \\text{ y } u\' \\text{ en la fórmula:}\\\\\r\nf\'(x) = -\\csc(\\sqrt{x})\\cot(\\sqrt{x}) \\cdot \\left(\\frac{1}{2\\sqrt{x}}\\right)\r\n\\]\r\n', 3, '2025-07-27 19:58:12', '2025-07-27 19:58:12'),
(841, 351, '\r\n\\[\r\n\\text{\\textbf{PASO 4: ESCRIBIR EL RESULTADO FINAL DE FORMA ESTÁNDAR}} \\\\\r\n\\text{Coloca el término algebraico al inicio.}\\\r\nf\'(x) = -\\frac{1}{2\\sqrt{x}} \\csc(\\sqrt{x})\\cot(\\sqrt{x})\r\n\\]\r\n', 4, '2025-07-27 19:58:12', '2025-07-27 19:58:12'),
(842, 352, '\r\n\\[\r\n\\text{\\textbf{PASO 1: REESCRIBIR LA FUNCIÓN E IDENTIFICAR LA REGLA DE DERIVACIÓN}} \\\\\r\n\\text{La función se puede reescribir como } f(x) = \\sec(x^{1/3}).\\ \\text{Se debe aplicar la Regla de la Cadena.}\\\r\n\\text{La fórmula para derivar la secante es: } \\frac{d}{dx}[\\sec(u)] = \\sec(u)\\tan(u) \\cdot u\'.\r\n\\]\r\n', 1, '2025-07-27 20:01:55', '2025-07-27 20:01:55'),
(843, 352, '\r\n\\[\r\n\\text{\\textbf{PASO 2: IDENTIFICAR u Y CALCULAR SU DERIVADA u\'}} \\\\\r\n\\text{En este caso, } u = \\sqrt[3]{x} = x^{1/3}.\\ \\text{Ahora, calcula su derivada:}\\\\\r\nu\' = \\frac{d}{dx}(x^{1/3}) = \\frac{1}{3}x^{\\frac{1}{3}-1} = \\frac{1}{3}x^{-\\frac{2}{3}} = \\frac{1}{3x^{2/3}} = \\frac{1}{3\\sqrt[3]{x^2}}.\r\n\\]\r\n', 2, '2025-07-27 20:01:55', '2025-07-27 20:01:55'),
(844, 352, '\r\n\\[\r\n\\text{\\textbf{PASO 3: APLICAR LA FÓRMULA DE LA DERIVADA DE LA SECANTE}} \\\\\r\n\\text{Sustituye } u \\text{ y } u\' \\text{ en la fórmula:}\\\\\r\nf\'(x) = \\sec(\\sqrt[3]{x})\\tan(\\sqrt[3]{x}) \\cdot \\left(\\frac{1}{3\\sqrt[3]{x^2}}\\right)\r\n\\]\r\n', 3, '2025-07-27 20:01:55', '2025-07-27 20:01:55'),
(845, 352, '\r\n\\[\r\n\\text{\\textbf{PASO 4: ESCRIBIR EL RESULTADO FINAL DE FORMA ESTÁNDAR}} \\\\\r\n\\text{Coloca el término algebraico al inicio.}\\\r\nf\'(x) = \\frac{1}{3\\sqrt[3]{x^2}} \\sec(\\sqrt[3]{x})\\tan(\\sqrt[3]{x})\r\n\\]\r\n', 4, '2025-07-27 20:01:55', '2025-07-27 20:01:55'),
(850, 354, '\r\n\\[\r\n\\text{\\textbf{PASO 1: APLICAR LA REGLA DE LA SUMA Y RESTA}} \\\\\r\n\\text{Deriva cada término de la función por separado:}\\\\\r\nf\'(x) = \\frac{d}{dx}(\\cos(5x)) + \\frac{d}{dx}(\\sin(6x^2)) - \\frac{d}{dx}(3\\cot(x))\r\n\\]\r\n', 1, '2025-07-27 20:40:49', '2025-07-27 20:40:49'),
(851, 354, '\r\n\\[\r\n\\text{\\textbf{PASO 2: DERIVAR EL PRIMER TÉRMINO: }} \\frac{d}{dx}(\\cos(5x)) \\\\\r\n\\text{Usa la regla de la cadena para } \\cos(u): \\frac{d}{dx}[\\cos(u)] = -\\sin(u) \\cdot u\'.\\\r\n\\text{Aquí } u = 5x, \\text{ entonces } u\' = 5.\\\r\n\\text{Así, } \\frac{d}{dx}(\\cos(5x)) = -\\sin(5x) \\cdot 5 = -5\\sin(5x).\r\n\\]\r\n', 2, '2025-07-27 20:40:49', '2025-07-27 20:40:49'),
(852, 354, '\r\n\\[\r\n\\text{\\textbf{PASO 3: DERIVAR EL SEGUNDO TÉRMINO: }} \\frac{d}{dx}(\\sin(6x^2)) \\\\\r\n\\text{Usa la regla de la cadena para } \\sin(u): \\frac{d}{dx}[\\sin(u)] = \\cos(u) \\cdot u\'.\\\r\n\\text{Aquí } u = 6x^2, \\text{ entonces } u\' = 12x.\\\r\n\\text{Así, } \\frac{d}{dx}(\\sin(6x^2)) = \\cos(6x^2) \\cdot 12x = 12x\\cos(6x^2).\r\n\\]\r\n', 3, '2025-07-27 20:40:49', '2025-07-27 20:40:49'),
(853, 354, '\r\n\\[\r\n\\text{\\textbf{PASO 4: DERIVAR EL TERCER TÉRMINO Y COMBINAR}} \\\\\r\n\\text{La derivada de } \\cot(x) \\text{ es } -\\csc^2(x).\\\r\n\\text{Entonces, } \\frac{d}{dx}(-3\\cot(x)) = -3(-\\csc^2(x)) = 3\\csc^2(x).\\\r\n\\text{Combina todos los resultados obtenidos:}\\\r\nf\'(x) = -5\\sin(5x) + 12x\\cos(6x^2) + 3\\csc^2(x).\r\n\\]\r\n', 4, '2025-07-27 20:40:49', '2025-07-27 20:40:49'),
(854, 355, '\r\n\\[\r\n\\text{\\textbf{PASO 1: APLICAR LA REGLA DE LA SUMA Y RESTA}} \\\\\r\n\\text{Deriva cada término de la función por separado:}\\\\\r\nf\'(x) = \\frac{d}{dx}(\\tan(4x^3)) - \\frac{d}{dx}(2\\cot(x^2)) + \\frac{d}{dx}(\\sec(2x-1))\r\n\\]\r\n', 1, '2025-07-27 20:57:44', '2025-07-27 20:57:44'),
(855, 355, '\r\n\\[\r\n\\text{\\textbf{PASO 2: DERIVAR EL PRIMER TÉRMINO: }} \\frac{d}{dx}(\\tan(4x^3)) \\\\\r\n\\text{Usa la regla de la cadena para } \\tan(u): \\frac{d}{dx}[\\tan(u)] = \\sec^2(u) \\cdot u\'.\\\r\n\\text{Aquí } u = 4x^3, \\text{ entonces } u\' = 12x^2.\\\r\n\\text{Así, } \\frac{d}{dx}(\\tan(4x^3)) = \\sec^2(4x^3) \\cdot 12x^2 = 12x^2\\sec^2(4x^3).\r\n\\]\r\n', 2, '2025-07-27 20:57:44', '2025-07-27 20:57:44'),
(856, 355, '\r\n\\[\r\n\\text{\\textbf{PASO 3: DERIVAR EL SEGUNDO TÉRMINO: }} \\frac{d}{dx}(-2\\cot(x^2)) \\\\\r\n\\text{Usa la regla de la cadena para } -2\\cot(u): \\frac{d}{dx}[-2\\cot(u)] = -2(-\\csc^2(u)) \\cdot u\' = 2\\csc^2(u) \\cdot u\'.\\\r\n\\text{Aquí } u = x^2, \\text{ entonces } u\' = 2x.\\\r\n\\text{Así, } \\frac{d}{dx}(-2\\cot(x^2)) = 2\\csc^2(x^2) \\cdot 2x = 4x\\csc^2(x^2).\r\n\\]\r\n', 3, '2025-07-27 20:57:44', '2025-07-27 20:57:44'),
(857, 355, '\r\n\\[\r\n\\text{\\textbf{PASO 4: DERIVAR EL TERCER TÉRMINO Y COMBINAR}} \\\\\r\n\\text{Usa la regla de la cadena para } \\sec(u): \\frac{d}{dx}[\\sec(u)] = \\sec(u)\\tan(u) \\cdot u\'.\\\r\n\\text{Aquí } u = 2x-1, \\text{ entonces } u\' = 2.\\\r\n\\text{Así, } \\frac{d}{dx}(\\sec(2x-1)) = \\sec(2x-1)\\tan(2x-1) \\cdot 2 = 2\\sec(2x-1)\\tan(2x-1).\\\r\n\\text{Combina todos los resultados:}\\\r\nf\'(x) = 12x^2\\sec^2(4x^3) + 4x\\csc^2(x^2) + 2\\sec(2x-1)\\tan(2x-1).\r\n\\]\r\n', 4, '2025-07-27 20:57:44', '2025-07-27 20:57:44'),
(858, 356, '\r\n\\[\r\n\\text{\\textbf{PASO 1: REESCRIBIR LA FUNCIÓN CON EXPONENTE FRACCIONARIO Y APLICAR LA REGLA DE LA CADENA EXTERNA}} \\\\\r\n\\text{Reescribe } f(x) = (\\sec(2x))^{1/2}.\\ \\text{Aplica la regla de la cadena para la potencia: } \\frac{d}{du}(u^{1/2}) = \\frac{1}{2}u^{-1/2}.\\ \\text{Aquí } u = \\sec(2x).\r\n\\]\r\n', 1, '2025-07-27 21:06:08', '2025-07-27 21:06:08'),
(859, 356, '\r\n\\[\r\n\\text{\\textbf{PASO 2: CALCULAR LA DERIVADA DE LA FUNCIÓN INTERNA: }} \\frac{d}{dx}(\\sec(2x)) \\\\\r\n\\text{Para } \\sec(2x), \\text{ aplica la regla de la cadena nuevamente.}\\ \\text{La derivada de } \\sec(v) \\text{ es } \\sec(v)\\tan(v) \\cdot v\'.\\ \\text{Aquí } v = 2x, \\text{ entonces } v\' = 2.\\ \\text{Así, } \\frac{d}{dx}(\\sec(2x)) = 2\\sec(2x)\\tan(2x).\r\n\\]\r\n', 2, '2025-07-27 21:06:08', '2025-07-27 21:06:08'),
(860, 356, '\r\n\\[\r\n\\text{\\textbf{PASO 3: COMBINAR LOS RESULTADOS DE LAS DERIVADAS}} \\\\\r\n\\text{Combina la derivada de la potencia con la derivada de la función interna:}\\\\\r\nf\'(x) = \\frac{1}{2}(\\sec(2x))^{-1/2} \\cdot (2\\sec(2x)\\tan(2x)) \\\\\r\nf\'(x) = \\frac{2\\sec(2x)\\tan(2x)}{2\\sqrt{\\sec(2x)}}\r\n\\]\r\n', 3, '2025-07-27 21:06:08', '2025-07-27 21:06:08'),
(861, 356, '\r\n\\[\r\n\\text{\\textbf{PASO 4: SIMPLIFICAR LA EXPRESIÓN FINAL}} \\\\\r\n\\text{Cancela el 2 del numerador y el denominador. Recuerda que } \\frac{A}{\\sqrt{A}} = \\sqrt{A}.\\\r\n\\text{Entonces, } f\'(x) = \\frac{\\sec(2x)\\tan(2x)}{\\sqrt{\\sec(2x)}} = \\sqrt{\\sec(2x)}\\tan(2x).\r\n\\]\r\n', 4, '2025-07-27 21:06:08', '2025-07-27 21:06:08'),
(862, 357, '\r\n\\[\r\n\\text{\\textbf{PASO 1: REESCRIBIR LA FUNCIÓN CON EXPONENTE FRACCIONARIO Y APLICAR LA REGLA DE LA CADENA EXTERNA}} \\\\\r\n\\text{Reescribe } f(x) = (\\csc(8x^2))^{1/3}.\\ \\text{Aplica la regla de la cadena para la potencia: } \\frac{d}{du}(u^{1/3}) = \\frac{1}{3}u^{-2/3}.\\ \\text{Aquí } u = \\csc(8x^2).\r\n\\]\r\n', 1, '2025-07-27 21:16:38', '2025-07-27 21:16:38'),
(863, 357, '\r\n\\[\r\n\\text{\\textbf{PASO 2: CALCULAR LA DERIVADA DE LA FUNCIÓN INTERMEDIA: }} \\frac{d}{dx}(\\csc(8x^2)) \\\\\r\n\\text{Para } \\csc(8x^2), \\text{ aplica la regla de la cadena nuevamente.}\\ \\text{La derivada de } \\csc(v) \\text{ es } -\\csc(v)\\cot(v) \\cdot v\'.\\ \\text{Aquí } v = 8x^2, \\text{ entonces } v\' = 16x.\\ \\text{Así, } \\frac{d}{dx}(\\csc(8x^2)) = -16x\\csc(8x^2)\\cot(8x^2).\r\n\\]\r\n', 2, '2025-07-27 21:16:38', '2025-07-27 21:16:38'),
(864, 357, '\r\n\\[\r\n\\text{\\textbf{PASO 3: COMBINAR LOS RESULTADOS DE LAS DERIVADAS}} \\\\\r\n\\text{Combina la derivada de la potencia con la derivada de la función intermedia:}\\\\\r\nf\'(x) = \\frac{1}{3}(\\csc(8x^2))^{-2/3} \\cdot (-16x\\csc(8x^2)\\cot(8x^2)) \\\\\r\nf\'(x) = \\frac{-16x\\csc(8x^2)\\cot(8x^2)}{3\\sqrt[3]{\\csc^2(8x^2)}}\r\n\\]\r\n', 3, '2025-07-27 21:16:38', '2025-07-27 21:16:38'),
(865, 357, '\r\n\\[\r\n\\text{\\textbf{PASO 4: SIMPLIFICAR LA EXPRESIÓN FINAL}} \\\\\r\n\\text{Simplifica los términos con } \\csc(8x^2): \\frac{\\csc(8x^2)}{\\sqrt[3]{\\csc^2(8x^2)}} = \\csc(8x^2)^{1 - 2/3} = \\csc(8x^2)^{1/3} = \\sqrt[3]{\\csc(8x^2)}.\\\r\n\\text{Entonces, } f\'(x) = -\\frac{16x}{3} \\sqrt[3]{\\csc(8x^2)}\\cot(8x^2).\r\n\\]\r\n', 4, '2025-07-27 21:16:38', '2025-07-27 21:16:38'),
(866, 358, '\r\n\\[\r\n\\text{\\textbf{PASO 1: IDENTIFICAR LA REGLA DE DERIVACIÓN A APLICAR}} \\\\\r\n\\text{Para derivar funciones inversas trigonométricas, se usa la Regla de la Cadena.}\\\r\n\\text{La fórmula para la derivada de } \\arcsin(u) \\text{ es: } \\frac{d}{dx}(\\arcsin(u)) = \\frac{1}{\\sqrt{1-u^2}} \\cdot u\'.\r\n\\]\r\n', 1, '2025-07-27 21:28:41', '2025-07-27 21:28:41'),
(867, 358, '\r\n\\[\r\n\\text{\\textbf{PASO 2: IDENTIFICAR u Y CALCULAR u\'}} \\\\\r\n\\text{En la función } f(x) = \\arcsin(3x^2-7), \\text{ la función interna es } u = 3x^2-7.\\\\\r\n\\text{Ahora, calcula su derivada: } u\' = \\frac{d}{dx}(3x^2-7) = 6x.\r\n\\]\r\n', 2, '2025-07-27 21:28:41', '2025-07-27 21:28:41'),
(868, 358, '\r\n\\[\r\n\\text{\\textbf{PASO 3: SUSTITUIR u Y u\' EN LA FÓRMULA}} \\\\\r\n\\text{Sustituye } u \\text{ y } u\' \\text{ en la fórmula de la derivada de } \\arcsin(u):\\\\\r\nf\'(x) = \\frac{1}{\\sqrt{1-(3x^2-7)^2}} \\cdot (6x)\r\n\\]\r\n', 3, '2025-07-27 21:28:41', '2025-07-27 21:28:41'),
(869, 358, '\r\n\\[\r\n\\text{\\textbf{PASO 4: ESCRIBIR EL RESULTADO FINAL}} \\\\\r\n\\text{Organiza la expresión para obtener la forma final de la derivada:}\\\r\nf\'(x) = \\frac{6x}{\\sqrt{1-(3x^2-7)^2}}.\r\n\\]\r\n', 4, '2025-07-27 21:28:41', '2025-07-27 21:28:41');
INSERT INTO `problem_hints` (`id`, `problem_id`, `hint`, `sequence_id`, `created_at`, `updated_at`) VALUES
(870, 359, '\r\n\\[\r\n\\text{\\textbf{PASO 1: IDENTIFICAR LA REGLA DE DERIVACIÓN A APLICAR}} \\\\\r\n\\text{Para derivar funciones inversas trigonométricas, se usa la Regla de la Cadena.}\\\r\n\\text{La fórmula para la derivada de } \\arcsin(u) \\text{ es: } \\frac{d}{dx}(\\arcsin(u)) = \\frac{1}{\\sqrt{1-u^2}} \\cdot u\'.\r\n\\]\r\n', 1, '2025-07-27 21:43:10', '2025-07-27 21:43:10'),
(871, 359, '\r\n\\[\r\n\\text{\\textbf{PASO 2: IDENTIFICAR u Y CALCULAR u\'}} \\\\\r\n\\text{En la función } f(x) = \\arcsin(4-5x^3), \\text{ la función interna es } u = 4-5x^3.\\\\\r\n\\text{Ahora, calcula su derivada: } u\' = \\frac{d}{dx}(4-5x^3) = -15x^2.\r\n\\]\r\n', 2, '2025-07-27 21:43:10', '2025-07-27 21:43:10'),
(872, 359, '\r\n\\[\r\n\\text{\\textbf{PASO 3: SUSTITUIR u Y u\' EN LA FÓRMULA}} \\\\\r\n\\text{Sustituye } u \\text{ y } u\' \\text{ en la fórmula de la derivada de } \\arcsin(u):\\\\\r\nf\'(x) = \\frac{1}{\\sqrt{1-(4-5x^3)^2}} \\cdot (-15x^2)\r\n\\]\r\n', 3, '2025-07-27 21:43:10', '2025-07-27 21:43:10'),
(873, 359, '\r\n\\[\r\n\\text{\\textbf{PASO 4: ESCRIBIR EL RESULTADO FINAL}} \\\\\r\n\\text{Organiza la expresión para obtener la forma final de la derivada:}\\\r\nf\'(x) = \\frac{-15x^2}{\\sqrt{1-(4-5x^3)^2}}.\r\n\\]\r\n', 4, '2025-07-27 21:43:10', '2025-07-27 21:43:10'),
(874, 360, '\r\n\\[\r\n\\text{\\textbf{PASO 1: IDENTIFICAR LA REGLA DE DERIVACIÓN A APLICAR}} \\\\\r\n\\text{Para derivar funciones inversas trigonométricas, se usa la Regla de la Cadena.}\\\r\n\\text{La fórmula para la derivada de } \\operatorname{arcsec}(u) \\text{ es: } \\frac{d}{dx}(\\operatorname{arcsec}(u)) = \\frac{1}{|u|\\sqrt{u^2-1}} \\cdot u\'.\r\n\\]\r\n', 1, '2025-07-27 21:49:45', '2025-07-27 21:49:45'),
(875, 360, '\r\n\\[\r\n\\text{\\textbf{PASO 2: IDENTIFICAR u Y CALCULAR u\'}} \\\\\r\n\\text{En la función } f(x) = \\operatorname{arcsec}(4x^3), \\text{ la función interna es } u = 4x^3.\\\\\r\n\\text{Ahora, calcula su derivada: } u\' = \\frac{d}{dx}(4x^3) = 12x^2.\r\n\\]\r\n', 2, '2025-07-27 21:49:45', '2025-07-27 21:49:45'),
(876, 360, '\r\n\\[\r\n\\text{\\textbf{PASO 3: SUSTITUIR u Y u\' EN LA FÓRMULA}} \\\\\r\n\\text{Sustituye } u \\text{ y } u\' \\text{ en la fórmula de la derivada de } \\operatorname{arcsec}(u):\\\\\r\nf\'(x) = \\frac{1}{|4x^3|\\sqrt{(4x^3)^2-1}} \\cdot (12x^2) \\\\\r\nf\'(x) = \\frac{12x^2}{|4x^3|\\sqrt{16x^6-1}}\r\n\\]\r\n', 3, '2025-07-27 21:49:45', '2025-07-27 21:49:45'),
(877, 360, '\r\n\\[\r\n\\text{\\textbf{PASO 4: SIMPLIFICAR LA EXPRESIÓN FINAL}} \\\\\r\n\\text{Considerando el dominio principal donde } x > 0, \\text{ entonces } |4x^3| = 4x^3.\\\\\r\n\\text{Simplifica la fracción: } \\frac{12x^2}{4x^3} = \\frac{3}{x}.\\\\\r\n\\text{Por lo tanto, la derivada simplificada es: } f\'(x) = \\frac{3}{x\\sqrt{16x^6-1}}.\r\n\\]\r\n', 4, '2025-07-27 21:49:45', '2025-07-27 21:49:45'),
(878, 361, '\r\n\\[\r\n\\text{\\textbf{PASO 1: IDENTIFICAR LA REGLA DE DERIVACIÓN A APLICAR}} \\\\\r\n\\text{Para derivar funciones inversas trigonométricas, se usa la Regla de la Cadena.}\\\r\n\\text{La fórmula para la derivada de } \\operatorname{arcsec}(u) \\text{ es: } \\frac{d}{dx}(\\operatorname{arcsec}(u)) = \\frac{1}{|u|\\sqrt{u^2-1}} \\cdot u\'.\r\n\\]\r\n', 1, '2025-07-27 22:06:14', '2025-07-27 22:06:14'),
(879, 361, '\r\n\\[\r\n\\text{\\textbf{PASO 2: IDENTIFICAR u Y CALCULAR u\'}} \\\\\r\n\\text{En la función } f(x) = \\operatorname{arcsec}(1-x^3), \\text{ la función interna es } u = 1-x^3.\\\\\r\n\\text{Ahora, calcula su derivada: } u\' = \\frac{d}{dx}(1-x^3) = -3x^2.\r\n\\]\r\n', 2, '2025-07-27 22:06:14', '2025-07-27 22:06:14'),
(880, 361, '\r\n\\[\r\n\\text{\\textbf{PASO 3: SUSTITUIR u Y u\' EN LA FÓRMULA}} \\\\\r\n\\text{Sustituye } u \\text{ y } u\' \\text{ en la fórmula de la derivada de } \\operatorname{arcsec}(u):\\\\\r\nf\'(x) = \\frac{1}{|1-x^3|\\sqrt{(1-x^3)^2-1}} \\cdot (-3x^2)\r\n\\]\r\n', 3, '2025-07-27 22:06:14', '2025-07-27 22:06:14'),
(881, 361, '\r\n\\[\r\n\\text{\\textbf{PASO 4: ESCRIBIR EL RESULTADO FINAL}} \\\\\r\n\\text{Organiza la expresión para obtener la forma final de la derivada:}\\\r\nf\'(x) = \\frac{-3x^2}{|1-x^3|\\sqrt{(1-x^3)^2-1}}.\r\n\\]\r\n', 4, '2025-07-27 22:06:14', '2025-07-27 22:06:14'),
(882, 362, '\r\n\\[\r\n\\text{\\textbf{PASO 1: IDENTIFICAR LA REGLA DE DERIVACIÓN A APLICAR}} \\\\\r\n\\text{Para derivar funciones inversas trigonométricas, se usa la Regla de la Cadena.}\\\r\n\\text{La fórmula para la derivada de } \\operatorname{arccot}(u) \\text{ es: } \\frac{d}{dx}(\\operatorname{arccot}(u)) = \\frac{-1}{1+u^2} \\cdot u\'.\r\n\\]\r\n', 1, '2025-07-27 22:10:07', '2025-07-27 22:10:07'),
(883, 362, '\r\n\\[\r\n\\text{\\textbf{PASO 2: IDENTIFICAR u Y CALCULAR u\'}} \\\\\r\n\\text{En la función } f(x) = \\operatorname{arccot}(\\cos(2x)), \\text{ la función interna es } u = \\cos(2x).\\\r\n\\text{Para calcular } u\', \\text{ aplica la regla de la cadena nuevamente: } \\frac{d}{dx}(\\cos(v)) = -\\sin(v) \\cdot v\'.\\\r\n\\text{Aquí } v = 2x, \\text{ entonces } v\' = 2.\\\r\n\\text{Así, } u\' = -\\sin(2x) \\cdot 2 = -2\\sin(2x).\r\n\\]\r\n', 2, '2025-07-27 22:10:07', '2025-07-27 22:10:07'),
(884, 362, '\r\n\\[\r\n\\text{\\textbf{PASO 3: SUSTITUIR u Y u\' EN LA FÓRMULA}} \\\\\r\n\\text{Sustituye } u \\text{ y } u\' \\text{ en la fórmula de la derivada de } \\operatorname{arccot}(u):\\\\\r\nf\'(x) = \\frac{-1}{1+(\\cos(2x))^2} \\cdot (-2\\sin(2x))\r\n\\]\r\n', 3, '2025-07-27 22:10:07', '2025-07-27 22:10:07'),
(885, 362, '\r\n\\[\r\n\\text{\\textbf{PASO 4: SIMPLIFICAR Y ESCRIBIR EL RESULTADO FINAL}} \\\\\r\n\\text{Multiplica los numeradores y organiza la expresión:}\\\r\nf\'(x) = \\frac{2\\sin(2x)}{1+\\cos^2(2x)}.\r\n\\]\r\n', 4, '2025-07-27 22:10:07', '2025-07-27 22:10:07'),
(886, 363, '\r\n\\[\r\n\\text{\\textbf{PASO 1: IDENTIFICAR LA REGLA DE DERIVACIÓN A APLICAR}} \\\\\r\n\\text{Para derivar funciones inversas trigonométricas, se usa la Regla de la Cadena.}\\\r\n\\text{La fórmula para la derivada de } \\operatorname{arccot}(u) \\text{ es: } \\frac{d}{dx}(\\operatorname{arccot}(u)) = \\frac{-1}{1+u^2} \\cdot u\'.\r\n\\]\r\n', 1, '2025-07-27 22:14:17', '2025-07-27 22:14:17'),
(887, 363, '\r\n\\[\r\n\\text{\\textbf{PASO 2: IDENTIFICAR u Y CALCULAR u\'}} \\\\\r\n\\text{En la función } f(x) = \\operatorname{arccot}(\\sin(x^2)), \\text{ la función interna es } u = \\sin(x^2).\\\r\n\\text{Para calcular } u\', \\text{ aplica la regla de la cadena nuevamente: } \\frac{d}{dx}(\\sin(v)) = \\cos(v) \\cdot v\'.\\\r\n\\text{Aquí } v = x^2, \\text{ entonces } v\' = 2x.\\\r\n\\text{Así, } u\' = \\cos(x^2) \\cdot 2x = 2x\\cos(x^2).\r\n\\]\r\n', 2, '2025-07-27 22:14:17', '2025-07-27 22:14:17'),
(888, 363, '\r\n\\[\r\n\\text{\\textbf{PASO 3: SUSTITUIR u Y u\' EN LA FÓRMULA}} \\\\\r\n\\text{Sustituye } u \\text{ y } u\' \\text{ en la fórmula de la derivada de } \\operatorname{arccot}(u):\\\\\r\nf\'(x) = \\frac{-1}{1+(\\sin(x^2))^2} \\cdot (2x\\cos(x^2))\r\n\\]\r\n', 3, '2025-07-27 22:14:17', '2025-07-27 22:14:17'),
(889, 363, '\r\n\\[\r\n\\text{\\textbf{PASO 4: SIMPLIFICAR Y ESCRIBIR EL RESULTADO FINAL}} \\\\\r\n\\text{Multiplica los numeradores y organiza la expresión:}\\\r\nf\'(x) = \\frac{-2x\\cos(x^2)}{1+\\sin^2(x^2)}.\r\n\\]\r\n', 4, '2025-07-27 22:14:17', '2025-07-27 22:14:17'),
(890, 364, '\r\n\\[\r\n\\text{\\textbf{PASO 1: IDENTIFICAR LA REGLA DE DERIVACIÓN A APLICAR}} \\\\\r\n\\text{Para derivar funciones inversas trigonométricas, se usa la Regla de la Cadena.}\\\r\n\\text{La fórmula para la derivada de } \\arccos(u) \\text{ es: } \\frac{d}{dx}(\\arccos(u)) = \\frac{-1}{\\sqrt{1-u^2}} \\cdot u\'.\r\n\\]\r\n', 1, '2025-07-27 22:19:04', '2025-07-27 22:19:04'),
(891, 364, '\r\n\\[\r\n\\text{\\textbf{PASO 2: IDENTIFICAR u Y CALCULAR u\'}} \\\\\r\n\\text{En la función } f(x) = \\arccos(\\sqrt{3x}), \\text{ la función interna es } u = \\sqrt{3x} = (3x)^{1/2}.\\\r\n\\text{Ahora, calcula su derivada usando la regla de la cadena: } \\\\\r\nu\' = \\frac{1}{2}(3x)^{-1/2} \\cdot \\frac{d}{dx}(3x) = \\frac{1}{2\\sqrt{3x}} \\cdot 3 = \\frac{3}{2\\sqrt{3x}}.\r\n\\]\r\n', 2, '2025-07-27 22:19:04', '2025-07-27 22:19:04'),
(892, 364, '\r\n\\[\r\n\\text{\\textbf{PASO 3: SUSTITUIR u Y u\' EN LA FÓRMULA}} \\\\\r\n\\text{Sustituye } u \\text{ y } u\' \\text{ en la fórmula de la derivada de } \\arccos(u):\\\\\r\nf\'(x) = \\frac{-1}{\\sqrt{1-(\\sqrt{3x})^2}} \\cdot \\left(\\frac{3}{2\\sqrt{3x}}\\right) \\\\\r\nf\'(x) = \\frac{-1}{\\sqrt{1-3x}} \\cdot \\frac{3}{2\\sqrt{3x}}\r\n\\]\r\n', 3, '2025-07-27 22:19:04', '2025-07-27 22:19:04'),
(893, 364, '\r\n\\[\r\n\\text{\\textbf{PASO 4: SIMPLIFICAR Y ESCRIBIR EL RESULTADO FINAL}} \\\\\r\n\\text{Combina los términos en el numerador y el denominador. Las raíces pueden combinarse:}\\\r\nf\'(x) = \\frac{-3}{2\\sqrt{3x}\\sqrt{1-3x}} = \\frac{-3}{2\\sqrt{3x(1-3x)}} = \\frac{-3}{2\\sqrt{3x-9x^2}}.\r\n\\]\r\n', 4, '2025-07-27 22:19:04', '2025-07-27 22:19:04'),
(894, 365, '\r\n\\[\r\n\\text{\\textbf{PASO 1: IDENTIFICAR LA REGLA DE DERIVACIÓN A APLICAR}} \\\\\r\n\\text{Para derivar funciones inversas trigonométricas, se usa la Regla de la Cadena.}\\\r\n\\text{La fórmula para la derivada de } \\arcsin(u) \\text{ es: } \\frac{d}{dx}(\\arcsin(u)) = \\frac{1}{\\sqrt{1-u^2}} \\cdot u\'.\r\n\\]\r\n', 1, '2025-07-27 22:43:22', '2025-07-27 22:43:22'),
(895, 365, '\r\n\\[\r\n\\text{\\textbf{PASO 2: IDENTIFICAR u Y CALCULAR u\'}} \\\\\r\n\\text{En la función } f(x) = \\arcsin(\\sqrt{5x}), \\text{ la función interna es } u = \\sqrt{5x} = (5x)^{1/2}.\\\r\n\\text{Ahora, calcula su derivada usando la regla de la cadena: } \\\\\r\nu\' = \\frac{1}{2}(5x)^{-1/2} \\cdot \\frac{d}{dx}(5x) = \\frac{1}{2\\sqrt{5x}} \\cdot 5 = \\frac{5}{2\\sqrt{5x}}.\r\n\\]\r\n', 2, '2025-07-27 22:43:22', '2025-07-27 22:43:22'),
(896, 365, '\r\n\\[\r\n\\text{\\textbf{PASO 3: SUSTITUIR u Y u\' EN LA FÓRMULA}} \\\\\r\n\\text{Sustituye } u \\text{ y } u\' \\text{ en la fórmula de la derivada de } \\arcsin(u):\\\\\r\nf\'(x) = \\frac{1}{\\sqrt{1-(\\sqrt{5x})^2}} \\cdot \\left(\\frac{5}{2\\sqrt{5x}}\\right) \\\\\r\nf\'(x) = \\frac{1}{\\sqrt{1-5x}} \\cdot \\frac{5}{2\\sqrt{5x}}\r\n\\]\r\n', 3, '2025-07-27 22:43:22', '2025-07-27 22:43:22'),
(897, 365, '\r\n\\[\r\n\\text{\\textbf{PASO 4: SIMPLIFICAR Y ESCRIBIR EL RESULTADO FINAL}} \\\\\r\n\\text{Combina los términos en el numerador y el denominador. Las raíces pueden combinarse:}\\\r\nf\'(x) = \\frac{5}{2\\sqrt{5x}\\sqrt{1-5x}} = \\frac{5}{2\\sqrt{5x(1-5x)}} = \\frac{5}{2\\sqrt{5x-25x^2}}.\r\n\\]\r\n', 4, '2025-07-27 22:43:22', '2025-07-27 22:43:22'),
(906, 366, '\\[\\boxed{\\text{PASO 1: FUNCIONES DEL TIPO } u(x)^{v(x)}}\\]Aplicamos logaritmos:\\[f(x) = (5x^3 - 1)^{sen(3x)} \\Rightarrow \\ln f(x) = sen(3x) \\cdot \\ln(5x^3 - 1)\\]', 1, '2025-07-30 02:28:34', '2025-07-30 02:28:34'),
(907, 366, '\\[\\boxed{\\text{PASO 2: DERIVACIÓN IMPLÍCITA}}\\]Derivamos ambos lados:\\[\\frac{f\'(x)}{f(x)} = \\frac{d}{dx}[sen(3x) \\cdot \\ln(5x^3 - 1)]\\]Regla del producto.', 2, '2025-07-30 02:28:34', '2025-07-30 02:28:34'),
(908, 366, '\\[\\boxed{\\text{PASO 3: DERIVADAS INTERNAS}}\\]\\[\\frac{d}{dx}[sen(3x)] = 3cos(3x)\\quad\\text{y}\\quad\\frac{d}{dx}[\\ln(5x^3 - 1)] = \\frac{15x^2}{5x^3 - 1}\\]', 3, '2025-07-30 02:28:34', '2025-07-30 02:28:34'),
(909, 366, '\\[\\boxed{\\text{RESULTADO FINAL}}\\]\\[f\'(x) = (5x^3 - 1)^{sen(3x)} \\left[ 3cos(3x) \\cdot \\ln(5x^3 - 1) + \\frac{15x^2 \\cdot sen(3x)}{5x^3 - 1} \\right]\\]', 4, '2025-07-30 02:28:34', '2025-07-30 02:28:34'),
(926, 371, '\r\n\\[\r\n\\boxed{\\text{PASO 1: DERIVAR AMBOS LADOS DE LA ECUACIÓN CON RESPECTO A } x}\r\n\\]\r\nAplica el operador \\( \\frac{d}{dx} \\) a cada término de la ecuación. Recuerda que \\( y \\) es una función de \\( x \\):\r\n\r\n\\[\r\n\\frac{d}{dx}(4x^3y^2) + \\frac{d}{dx}(x^3) = \\frac{d}{dx}(2) - \\frac{d}{dx}(xy)\r\n\\]\r\n', 1, '2025-07-31 06:50:19', '2025-07-31 06:50:19'),
(927, 371, '\r\n\\[\r\n\\boxed{\\text{PASO 2: APLICAR LAS REGLAS DE DERIVACIÓN (PRODUCTO Y CADENA)}}\r\n\\]\r\nPara \\( 4x^3y^2 \\): usa la regla del producto \\( (uv)\' = u\'v + uv\' \\), con \\( u = 4x^3, v = y^2 \\)\r\n\r\nPara \\( xy \\): también es un producto, con \\( u = x, v = y \\)\r\n\r\nRecuerda que:\r\n\\[\r\n\\frac{d}{dx}(y^2) = 2y \\frac{dy}{dx}, \\quad \\frac{d}{dx}(y) = \\frac{dy}{dx}\r\n\\]\r\n\r\nDerivadas:\r\n\\[\r\n\\frac{d}{dx}(4x^3y^2) = 12x^2y^2 + 8x^3y \\frac{dy}{dx}\r\n\\]\r\n\\[\r\n\\frac{d}{dx}(x^3) = 3x^2, \\quad \\frac{d}{dx}(2) = 0\r\n\\]\r\n\\[\r\n\\frac{d}{dx}(xy) = y + x \\frac{dy}{dx}\r\n\\]\r\n', 2, '2025-07-31 06:50:19', '2025-07-31 06:50:19'),
(928, 371, '\r\n\\[\r\n\\boxed{\\text{PASO 3: SUSTITUIR Y AGRUPAR}}\r\n\\]\r\nSustituye en la ecuación:\r\n\r\n\\[\r\n12x^2y^2 + 8x^3y\\frac{dy}{dx} + 3x^2 = -y - x\\frac{dy}{dx}\r\n\\]\r\n\r\nAgrupa los términos con \\( \\frac{dy}{dx} \\):\r\n\r\n\\[\r\n8x^3y\\frac{dy}{dx} + x\\frac{dy}{dx} = -12x^2y^2 - 3x^2 - y\r\n\\]\r\n', 3, '2025-07-31 06:50:19', '2025-07-31 06:50:19'),
(929, 371, '\r\n\\[\r\n\\boxed{\\text{PASO 4: FACTORIZAR Y DESPEJAR}}\r\n\\]\r\nFactoriza \\( \\frac{dy}{dx} \\):\r\n\r\n\\[\r\n\\frac{dy}{dx}(8x^3y + x) = -12x^2y^2 - 3x^2 - y\r\n\\]\r\n\r\nDespeja finalmente:\r\n\r\n\\[\r\n\\frac{dy}{dx} = \\frac{-12x^2y^2 - 3x^2 - y}{8x^3y + x}\r\n\\]\r\n', 4, '2025-07-31 06:50:19', '2025-07-31 06:50:19'),
(958, 379, '\r\n\\[\r\n\\boxed{\\text{PASO 1: DERIVAR AMBOS LADOS DE LA ECUACIÓN CON RESPECTO A } x}\r\n\\]\r\n\r\nAplica el operador \\( \\frac{d}{dx} \\) a cada término. Recuerda que \\(y\\) es función de \\(x\\).\r\n\r\n\\[\r\n\\frac{d}{dx}\\bigl(3x^5y^3\\bigr) + \\frac{d}{dx}\\bigl(2x^4\\bigr) = \\frac{d}{dx}\\bigl(xy\\bigr) + \\frac{d}{dx}(1)\r\n\\]\r\n', 1, '2025-08-02 00:54:44', '2025-08-02 00:54:44'),
(959, 379, '\r\n\\[\r\n\\boxed{\\text{PASO 2: APLICAR LAS REGLAS DE DERIVACIÓN (PRODUCTO Y CADENA)}}\r\n\\]\r\n\r\nPara \\(3x^5y^3\\), usa la regla del producto:\r\n\r\n\\[\r\n(uv)\' = u\'v + uv\'\r\n\\]\r\n\r\ndonde \\(u = 3x^5\\) y \\(v = y^3\\).\r\n\r\nRecuerda:\r\n\r\n\\[\r\n\\frac{d}{dx}\\bigl(y^3\\bigr) = 3y^2 \\frac{dy}{dx}\r\n\\quad y \\quad\r\n\\frac{d}{dx}\\bigl(y\\bigr) = \\frac{dy}{dx}\r\n\\]\r\n\r\nLas derivadas parciales son:\r\n\r\n\\[\r\n\\frac{d}{dx}\\bigl(3x^5y^3\\bigr) = 15x^4y^3 + 9x^5y^2 \\frac{dy}{dx}\r\n\\]\r\n\r\n\\[\r\n\\frac{d}{dx}\\bigl(2x^4\\bigr) = 8x^3\r\n\\]\r\n\r\n\\[\r\n\\frac{d}{dx}\\bigl(xy\\bigr) = y + x\\frac{dy}{dx}\r\n\\]\r\n', 2, '2025-08-02 00:54:44', '2025-08-02 00:54:44'),
(960, 379, '\r\n\\[\r\n\\boxed{\\text{PASO 3: SUSTITUIR Y REORDENAR LOS TÉRMINOS}}\r\n\\]\r\n\r\nSustituimos todas las derivadas en la ecuación original:\r\n\r\n\\[\r\n15x^4y^3 + 9x^5y^2\\frac{dy}{dx} + 8x^3 = y + x\\frac{dy}{dx}\r\n\\]\r\n\r\nAgrupamos los términos con \\(\\frac{dy}{dx}\\):\r\n\r\n\\[\r\n9x^5y^2\\frac{dy}{dx} - x\\frac{dy}{dx} = y - 15x^4y^3 - 8x^3\r\n\\]\r\n', 3, '2025-08-02 00:54:44', '2025-08-02 00:54:44'),
(961, 379, '\r\n\\[\r\n\\boxed{\\text{PASO 4: FACTORIZAR Y DESPEJAR}}\r\n\\]\r\n\r\nSacamos factor común \\(\\frac{dy}{dx}\\):\r\n\r\n\\[\r\n\\bigl(9x^5y^2 - x\\bigr)\\frac{dy}{dx} = y - 15x^4y^3 - 8x^3\r\n\\]\r\n\r\nDespejamos finalmente:\r\n\r\n\\[\r\n\\frac{dy}{dx} = \\frac{y - 15x^4y^3 - 8x^3}{9x^5y^2 - x}\r\n\\]\r\n', 4, '2025-08-02 00:54:44', '2025-08-02 00:54:44'),
(962, 380, '\r\n\\[\r\n\\boxed{\\text{PASO 1: DERIVAR AMBOS LADOS DE LA ECUACIÓN CON RESPECTO A } x}\r\n\\]\r\nDeriva cada término, recordando que \\(y\\) es función de \\(x\\):\r\n\r\n\\[\r\n\\frac{d}{dx}(x^2) + \\frac{d}{dx}(y^3) = \\frac{d}{dx}\\bigl[\\tan(x^2 y)\\bigr]\r\n\\]\r\n', 1, '2025-08-02 00:58:05', '2025-08-02 00:58:05'),
(963, 380, '\r\n\\[\r\n\\boxed{\\text{PASO 2: DERIVAR CADA TÉRMINO POR SEPARADO}}\r\n\\]\r\n\\[\r\n\\frac{d}{dx}(x^2) = 2x\r\n\\quad\r\n\\frac{d}{dx}(y^3) = 3y^2 \\frac{dy}{dx}\r\n\\]\r\n\r\nPara \\(\\tan(x^2 y)\\):\r\n\r\n\\[\r\n\\frac{d}{dx}[\\tan(u)] = \\sec^2(u)\\,u\'\r\n\\quad\r\nu = x^2 y\r\n\\]\r\n\\[\r\nu\' = 2x y + x^2\\frac{dy}{dx}\r\n\\]\r\n', 2, '2025-08-02 00:58:05', '2025-08-02 00:58:05'),
(964, 380, '\r\n\\[\r\n\\boxed{\\text{PASO 3: SUSTITUIR Y REORDENAR}}\r\n\\]\r\nSustituyendo:\r\n\r\n\\[\r\n2x + 3y^2\\frac{dy}{dx} = \\sec^2(x^2 y)\\,(2x y + x^2\\frac{dy}{dx})\r\n\\]\r\n\r\nAgrupamos términos con \\(\\frac{dy}{dx}\\):\r\n\r\n\\[\r\n3y^2\\frac{dy}{dx} - x^2\\sec^2(x^2 y)\\frac{dy}{dx} = 2x\\sec^2(x^2 y)\\,y - 2x\r\n\\]\r\n', 3, '2025-08-02 00:58:05', '2025-08-02 00:58:05'),
(965, 380, '\r\n\\[\r\n\\boxed{\\text{PASO 4: FACTORIZAR Y DESPEJAR}}\r\n\\]\r\nSacamos factor común y despejamos:\r\n\r\n\\[\r\n\\bigl(3y^2 - x^2\\sec^2(x^2 y)\\bigr)\\frac{dy}{dx} = 2x\\,y\\,\\sec^2(x^2 y) - 2x\r\n\\]\r\n\r\n\\[\r\n\\frac{dy}{dx} = \\frac{2x\\,y\\,\\sec^2(x^2 y) - 2x}{3y^2 - x^2\\sec^2(x^2 y)}\r\n\\]\r\n', 4, '2025-08-02 00:58:05', '2025-08-02 00:58:05'),
(966, 381, '\r\n\\[\r\n\\boxed{\\text{PASO 1: DERIVAR AMBOS LADOS DE LA ECUACIÓN CON RESPECTO A } x}\r\n\\]\r\nAplica el operador \\(\\frac{d}{dx}\\) a ambos lados:\r\n\r\n\\[\r\n\\frac{d}{dx}(x^5) - \\frac{d}{dx}(y^4) + \\frac{d}{dx}(3) = \\frac{d}{dx}(\\sin(x^3 y))\r\n\\]\r\n', 1, '2025-08-02 01:54:29', '2025-08-02 01:54:29'),
(967, 381, '\r\n\\[\r\n\\boxed{\\text{PASO 2: DERIVAR CADA TÉRMINO}}\r\n\\]\r\n\\[\r\n\\frac{d}{dx}(x^5) = 5x^4\r\n\\quad\r\n\\frac{d}{dx}(y^4) = 4y^3 \\frac{dy}{dx}\r\n\\quad\r\n\\frac{d}{dx}(3) = 0\r\n\\]\r\n\r\nPara \\(\\sin(x^3 y)\\) usamos la regla de la cadena:\r\n\r\n\\[\r\n\\frac{d}{dx}(\\sin(u)) = \\cos(u)\\cdot u\', \\text{ con } u = x^3 y\r\n\\]\r\n\r\n\\[\r\nu\' = 3x^2 y + x^3 \\frac{dy}{dx}\r\n\\]\r\n', 2, '2025-08-02 01:54:29', '2025-08-02 01:54:29'),
(968, 381, '\r\n\\[\r\n\\boxed{\\text{PASO 3: SUSTITUIR DERIVADAS Y AGRUPAR}}\r\n\\]\r\n\r\n\\[\r\n5x^4 - 4y^3\\frac{dy}{dx} = \\cos(x^3 y)(3x^2 y + x^3 \\frac{dy}{dx})\r\n\\]\r\n\r\nDistribuye y agrupa los términos con \\(\\frac{dy}{dx}\\):\r\n\r\n\\[\r\n-4y^3 \\frac{dy}{dx} - x^3 \\cos(x^3 y)\\frac{dy}{dx} = 3x^2 y \\cos(x^3 y) - 5x^4\r\n\\]\r\n', 3, '2025-08-02 01:54:29', '2025-08-02 01:54:29'),
(969, 381, '\r\n\\[\r\n\\boxed{\\text{PASO 4: FACTORIZAR Y DESPEJAR}}\r\n\\]\r\n\r\nSaca factor común:\r\n\r\n\\[\r\n(-4y^3 - x^3 \\cos(x^3 y))\\frac{dy}{dx} = 3x^2 y \\cos(x^3 y) - 5x^4\r\n\\]\r\n\r\nDespeja:\r\n\r\n\\[\r\n\\frac{dy}{dx} = \\frac{3x^2 y \\cos(x^3 y) - 5x^4}{-4y^3 - x^3 \\cos(x^3 y)}\r\n\\]\r\n', 4, '2025-08-02 01:54:29', '2025-08-02 01:54:29'),
(970, 382, '\r\n\\[\r\n\\boxed{\\text{PASO 1: DERIVAR AMBOS LADOS}}\r\n\\]\r\nAplica el operador \\(\\frac{d}{dx}\\):\r\n\\[\r\n\\frac{d}{dx}\\bigl(e^{2x+y}\\bigr) = \\frac{d}{dx}\\bigl(3x^2 y^5 - 1\\bigr)\r\n\\]\r\n', 1, '2025-08-02 13:31:25', '2025-08-02 13:31:25'),
(971, 382, '\r\n\\[\r\n\\boxed{\\text{PASO 2: DERIVAR LADO IZQUIERDO}}\r\n\\]\r\nRegla de la cadena:\r\n\\[\r\n\\frac{d}{dx}\\bigl(e^{2x+y}\\bigr) = e^{2x+y}\\,(2 + \\frac{dy}{dx})\r\n\\]\r\n', 2, '2025-08-02 13:31:25', '2025-08-02 13:31:25'),
(972, 382, '\r\n\\[\r\n\\boxed{\\text{PASO 3: DERIVAR LADO DERECHO}}\r\n\\]\r\nPara \\(3x^2 y^5\\):\r\n\\[\r\n3 \\bigl(2x y^5 + 5x^2 y^4 \\frac{dy}{dx}\\bigr) = 6x y^5 + 15x^2 y^4 \\frac{dy}{dx}\r\n\\]\r\n', 3, '2025-08-02 13:31:25', '2025-08-02 13:31:25'),
(973, 382, '\r\n\\[\r\n\\boxed{\\text{PASO 4: AGRUPAR Y DESPEJAR}}\r\n\\]\r\n\\[\r\n2 e^{2x+y} + e^{2x+y}\\,\\frac{dy}{dx} = 6x y^5 + 15x^2 y^4 \\frac{dy}{dx}\r\n\\]\r\n\\[\r\ne^{2x+y}\\,\\frac{dy}{dx} - 15x^2 y^4 \\frac{dy}{dx} = 6x y^5 - 2 e^{2x+y}\r\n\\]\r\n\\[\r\n\\frac{dy}{dx} = \\frac{6x y^5 - 2 e^{2x+y}}{e^{2x+y} - 15x^2 y^4}\r\n\\]\r\n', 4, '2025-08-02 13:31:25', '2025-08-02 13:31:25'),
(974, 383, '\r\n\\[\r\n\\boxed{\\text{PASO 1: DERIVA AMBOS LADOS}}\r\n\\]\r\nAplica \\( \\frac{d}{dx} \\) a ambos lados:\r\n\\[\r\n\\frac{d}{dx}(1 - e^{3x - y}) = \\frac{d}{dx}(2xy^2)\r\n\\]\r\n', 1, '2025-08-02 13:46:26', '2025-08-02 13:46:26'),
(975, 383, '\r\n\\[\r\n\\boxed{\\text{PASO 2: DERIVA EL LADO IZQUIERDO}}\r\n\\]\r\nUsamos regla de la cadena:\r\n\\[\r\n\\frac{d}{dx}(e^{3x - y}) = e^{3x - y}(3 - \\frac{dy}{dx})\r\n\\]\r\n\\[\r\n\\Rightarrow -e^{3x - y}(3 - \\frac{dy}{dx})\r\n\\]\r\n', 2, '2025-08-02 13:46:26', '2025-08-02 13:46:26'),
(976, 383, '\r\n\\[\r\n\\boxed{\\text{PASO 3: DERIVA EL LADO DERECHO}}\r\n\\]\r\nRegla del producto:\r\n\\[\r\n\\frac{d}{dx}(2xy^2) = 2y^2 + 4xy \\cdot \\frac{dy}{dx}\r\n\\]\r\n', 3, '2025-08-02 13:46:26', '2025-08-02 13:46:26'),
(977, 383, '\r\n\\[\r\n\\boxed{\\text{PASO 4: AGRUPAR Y DESPEJAR}}\r\n\\]\r\nSustituimos y agrupamos términos con \\( \\frac{dy}{dx} \\):\r\n\\[\r\n-3e^{3x - y} + e^{3x - y} \\cdot \\frac{dy}{dx} = 2y^2 + 4xy \\cdot \\frac{dy}{dx}\r\n\\]\r\n\\[\r\n\\Rightarrow (e^{3x - y} - 4xy) \\cdot \\frac{dy}{dx} = 2y^2 + 3e^{3x - y}\r\n\\]\r\n\\[\r\n\\Rightarrow \\boxed{\\frac{dy}{dx} = \\frac{2y^2 + 3e^{3x - y}}{e^{3x - y} - 4xy}}\r\n\\]\r\n', 4, '2025-08-02 13:46:26', '2025-08-02 13:46:26'),
(1056, 288, '\\[ \\boxed{\\text{PASO 1: ESCRIBIMOS LA DEFINICIÓN DE DERIVADA}} \\]  La derivada de una función \\( f(x) \\) por definición es:  \\[ f\'(x) = \\lim_{h \\to 0} \\frac{f(x+h) - f(x)}{h} \\]', 10, '2025-08-04 11:10:18', '2025-08-04 11:10:18'),
(1057, 288, '\\[ \\boxed{\\text{PASO 2: SUSTITUIMOS LA FUNCIÓN EN LA DEFINICIÓN}} \\]  Dada la función:  \\[ f(x) = \\sqrt{2x} \\]  Sustituimos en la fórmula de la derivada:  \\[ f\'(x) = \\lim_{h \\to 0} \\frac{\\sqrt{2(x+h)} - \\sqrt{2x}}{h} \\]', 20, '2025-08-04 11:10:18', '2025-08-04 11:10:18'),
(1058, 288, '\\[ \\boxed{\\text{PASO 3: RACIONALIZAMOS EL NUMERADOR}} \\]  Multiplicamos numerador y denominador por el conjugado del numerador:  \\[ f\'(x) = \\lim_{h \\to 0} \\frac{\\sqrt{2(x+h)} - \\sqrt{2x}}{h} \\cdot \\frac{\\sqrt{2(x+h)} + \\sqrt{2x}}{\\sqrt{2(x+h)} + \\sqrt{2x}} \\]  Aplicamos la identidad notable \\( (a - b)(a + b) = a^2 - b^2 \\):  \\[ = \\lim_{h \\to 0} \\frac{2(x+h) - 2x}{h\\left(\\sqrt{2(x+h)} + \\sqrt{2x}\\right)} \\]  Simplificamos el numerador:  \\[ = \\lim_{h \\to 0} \\frac{2h}{h\\left(\\sqrt{2(x+h)} + \\sqrt{2x}\\right)} \\]', 30, '2025-08-04 11:10:18', '2025-08-04 11:10:18'),
(1059, 288, '\\[ \\boxed{\\text{PASO 4: CANCELAMOS h Y APLICAMOS EL LÍMITE}} \\]  Cancelamos \\( h \\) en el numerador y denominador:  \\[ = \\lim_{h \\to 0} \\frac{2}{\\sqrt{2(x+h)} + \\sqrt{2x}} \\]  Aplicamos el límite:  \\[ f\'(x) = \\frac{2}{2\\sqrt{2x}} = \\frac{1}{\\sqrt{2x}} \\]', 40, '2025-08-04 11:10:18', '2025-08-04 11:10:18'),
(1060, 288, '\\[ \\boxed{\\text{RESULTADO FINAL:} \\quad f\'(x) = \\frac{1}{\\sqrt{2x}}} \\]', 50, '2025-08-04 11:10:18', '2025-08-04 11:10:18'),
(1061, 388, '\r\n\\[\r\n\\boxed{\\text{PASO 1: DERIVA POR PRIMERA VEZ}}\r\n\\]\r\n\\[\r\nf(x) = x^4 - 5x^3 + 7x^2 - 9x + 11\r\n\\]\r\n\\[\r\nf\'(x) = 4x^3 - 15x^2 + 14x - 9\r\n\\]\r\n', 1, '2025-08-05 01:27:01', '2025-08-05 01:27:01'),
(1062, 388, '\r\n\\[\r\n\\boxed{\\text{PASO 2: DERIVA POR SEGUNDA VEZ}}\r\n\\]\r\n\\[\r\nf\'\'(x) = 12x^2 - 30x + 14\r\n\\]\r\n', 2, '2025-08-05 01:27:01', '2025-08-05 01:27:01'),
(1063, 388, '\r\n\\[\r\n\\boxed{\\text{PASO 3: DERIVA POR TERCERA VEZ}}\r\n\\]\r\n\\[\r\nf^{(3)}(x) = 24x - 30\r\n\\]\r\n', 3, '2025-08-05 01:27:01', '2025-08-05 01:27:01'),
(1064, 388, '\r\n\\[\r\n\\boxed{\\text{PASO 4: DERIVA POR CUARTA VEZ}}\r\n\\]\r\n\\[\r\nf^{(4)}(x) = 24\r\n\\]\r\n\r\n', 4, '2025-08-05 01:27:01', '2025-08-05 01:28:34'),
(1065, 389, '\r\n\\[\r\n\\boxed{\\text{PASO 1: Deriva la función por primera vez}}\r\n\\]\r\n\\[\r\nf\'(x) = 7x^6 - 9x^2 - 4x - 3\r\n\\]\r\n', 1, '2025-08-06 02:09:26', '2025-08-06 02:09:26'),
(1066, 389, '\r\n\\[\r\n\\boxed{\\text{PASO 2: Segunda derivada}}\r\n\\]\r\n\\[\r\nf\'\'(x) = 42x^5 - 18x - 4\r\n\\]\r\n', 2, '2025-08-06 02:09:26', '2025-08-06 02:09:26'),
(1067, 389, '\r\n\\[\r\n\\boxed{\\text{PASO 3: Tercera y cuarta derivada}}\r\n\\]\r\n\\[\r\nf^{(3)}(x) = 210x^4 - 18 \\\\\r\nf^{(4)}(x) = 840x^3\r\n\\]\r\n', 3, '2025-08-06 02:09:26', '2025-08-06 02:09:26'),
(1068, 389, '\r\n\\[\r\n\\boxed{\\text{PASO 4: Quinta derivada}}\r\n\\]\r\n\\[\r\nf^{(5)}(x) = \\frac{d}{dx}(840x^3) = 2520x^2\r\n\\]\r\n', 4, '2025-08-06 02:09:26', '2025-08-06 02:09:26'),
(1069, 390, '\r\n\\[\r\n\\boxed{\\text{PASO 1: Derivada primera}}\r\n\\]\r\n\\[\r\nf\'(x) = 3x^2 - 2\r\n\\]\r\n', 1, '2025-08-06 02:41:12', '2025-08-06 02:41:12'),
(1070, 390, '\r\n\\[\r\n\\boxed{\\text{PASO 2: Segunda derivada}}\r\n\\]\r\n\\[\r\nf\'\'(x) = 6x\r\n\\]\r\n', 2, '2025-08-06 02:41:12', '2025-08-06 02:41:12'),
(1071, 390, '\r\n\\[\r\n\\boxed{\\text{PASO 3: Tercera derivada}}\r\n\\]\r\n\\[\r\nf^{(3)}(x) = 6\r\n\\]\r\n', 3, '2025-08-06 02:41:12', '2025-08-06 02:41:12'),
(1072, 390, '\r\n\\[\r\n\\boxed{\\text{PASO 4: Cuarta derivada}}\r\n\\]\r\n\\[\r\nf^{(4)}(x) = 0\r\n\\]\r\n', 4, '2025-08-06 02:41:12', '2025-08-06 02:41:12'),
(1081, 393, '\r\n\\[\r\n\\boxed{\\text{PASO 1: Derivada primera}}\r\n\\]\r\n\\[\r\nf\'(x) = 4x^3 + 2\r\n\\]\r\n', 1, '2025-08-06 04:03:50', '2025-08-06 04:03:50'),
(1082, 393, '\r\n\\[\r\n\\boxed{\\text{PASO 2: Segunda derivada}}\r\n\\]\r\n\\[\r\nf\'\'(x) = 12x^2\r\n\\]\r\n', 2, '2025-08-06 04:03:50', '2025-08-06 04:03:50'),
(1083, 393, '\r\n\\[\r\n\\boxed{\\text{PASO 3: Tercera derivada}}\r\n\\]\r\n\\[\r\nf^{(3)}(x) = 24x\r\n\\]\r\n', 3, '2025-08-06 04:03:50', '2025-08-06 04:03:50'),
(1084, 393, '\r\n\\[\r\n\\boxed{\\text{PASO 4: Cuarta derivada}}\r\n\\]\r\n\\[\r\nf^{(4)}(x) = 24\r\n\\]\r\n', 4, '2025-08-06 04:03:50', '2025-08-06 04:03:50'),
(1085, 393, '\r\n\\[\r\n\\boxed{\\text{PASO 5: Quinta derivada}}\r\n\\]\r\n\\[\r\nf^{(5)}(x) = 0\r\n\\]\r\n', 5, '2025-08-06 04:03:50', '2025-08-06 04:03:50'),
(1086, 394, '\r\n\\[\r\n\\boxed{\\text{PASO 1: Derivada de } \\sin(u)}\r\n\\]\r\n\\[\r\n\\frac{d}{dx} \\sin(u) = \\cos(u) \\cdot u\'\r\n\\quad \\text{donde } u = 2x^2\r\n\\]\r\n', 1, '2025-08-06 15:15:58', '2025-08-06 15:15:58'),
(1087, 394, '\r\n\\[\r\n\\boxed{\\text{PASO 2: Derivada de } u = 2x^2}\r\n\\]\r\n\\[\r\nu\' = 4x\r\n\\quad \\Rightarrow \\quad f\'(x) = 4x \\cos(2x^2)\r\n\\]\r\n', 2, '2025-08-06 15:15:58', '2025-08-06 15:15:58'),
(1088, 394, '\r\n\\[\r\n\\boxed{\\text{PASO 3: Segunda derivada usando regla del producto}}\r\n\\]\r\n\\[\r\nf\'(x) = 4x \\cos(2x^2)\r\n\\quad \\Rightarrow \\quad f\'\'(x) = \\frac{d}{dx}(4x) \\cdot \\cos(2x^2) + 4x \\cdot \\frac{d}{dx}(\\cos(2x^2))\r\n\\]\r\n', 3, '2025-08-06 15:15:58', '2025-08-06 15:15:58'),
(1089, 394, '\r\n\\[\r\n\\boxed{\\text{PASO 4: Resultado de la segunda derivada}}\r\n\\]\r\n\\[\r\nf\'\'(x) = 4\\cos(2x^2) - 16x^2\\sin(2x^2)\r\n\\quad \\Rightarrow \\quad f\'\'(x) = -16x^2\\sin(2x^2) + 4\\cos(2x^2)\r\n\\]\r\n', 4, '2025-08-06 15:15:58', '2025-08-06 15:15:58'),
(1090, 395, '\r\n\\[\r\n\\boxed{\\text{PASO 1: Derivada de } \\cos(u)}\r\n\\]\r\n\\[\r\n\\frac{d}{dx} \\cos(u) = -\\sin(u) \\cdot u\'\r\n\\quad \\text{donde } u = 3x^2\r\n\\]\r\n', 1, '2025-08-06 15:22:39', '2025-08-06 15:22:39'),
(1091, 395, '\r\n\\[\r\n\\boxed{\\text{PASO 2: Derivada de } u = 3x^2}\r\n\\]\r\n\\[\r\nu\' = 6x\r\n\\quad \\Rightarrow \\quad f\'(x) = -6x \\sin(3x^2)\r\n\\]\r\n', 2, '2025-08-06 15:22:39', '2025-08-06 15:22:39'),
(1092, 395, '\r\n\\[\r\n\\boxed{\\text{PASO 3: Segunda derivada con regla del producto}}\r\n\\]\r\n\\[\r\nf\'\'(x) = \\frac{d}{dx}[-6x \\sin(3x^2)]\r\n= -6 \\sin(3x^2) - 36x^2 \\cos(3x^2)\r\n\\]\r\n', 3, '2025-08-06 15:22:39', '2025-08-06 15:22:39'),
(1093, 395, '\r\n\\[\r\n\\boxed{\\text{PASO 4: Resultado final}}\r\n\\]\r\n\\[\r\nf\'\'(x) = -6\\sin(3x^2) - 36x^2\\cos(3x^2)\r\n\\]\r\n', 4, '2025-08-06 15:22:39', '2025-08-06 15:22:39'),
(1094, 396, '\r\n\\[\r\n\\boxed{\\text{PASO 1: Reescribir la raíz cuadrada}}\r\n\\]\r\n\\[\r\nf(x) = (3x - 1)^{1/2}\r\n\\]\r\n', 1, '2025-08-06 15:35:08', '2025-08-06 15:35:08'),
(1095, 396, '\r\n\\[\r\n\\boxed{\\text{PASO 2: Derivada de una potencia}}\r\n\\]\r\n\\[\r\nf\'(x) = \\frac{1}{2}(3x - 1)^{-1/2} \\cdot 3 = \\frac{3}{2\\sqrt{3x - 1}}\r\n\\]\r\n', 2, '2025-08-06 15:35:08', '2025-08-06 15:35:08'),
(1096, 396, '\r\n\\[\r\n\\boxed{\\text{PASO 3: Derivar nuevamente usando la regla del producto y cadena}}\r\n\\]\r\n\\[\r\nf\'\'(x) = -\\frac{3}{2} \\cdot \\frac{3}{2} (3x - 1)^{-3/2}\r\n= -\\frac{9}{4(3x - 1)^{3/2}}\r\n\\]\r\n', 3, '2025-08-06 15:35:08', '2025-08-06 15:35:08'),
(1097, 396, '\r\n\\[\r\n\\boxed{\\text{PASO 4: Resultado final}}\r\n\\]\r\n\\[\r\nf\'\'(x) = -\\frac{9}{4(3x - 1)^{3/2}}\r\n\\]\r\n', 4, '2025-08-06 15:35:08', '2025-08-06 15:35:08'),
(1098, 397, '\r\n\\[\r\n\\boxed{\\text{PASO 1: Reescribir la raíz cúbica como potencia}}\r\n\\]\r\n\\[\r\nf(x) = (3x - 1)^{1/3}\r\n\\]\r\n', 1, '2025-08-06 15:37:06', '2025-08-06 15:37:06'),
(1099, 397, '\r\n\\[\r\n\\boxed{\\text{PASO 2: Derivar usando regla de la cadena}}\r\n\\]\r\n\\[\r\nf\'(x) = \\frac{1}{3}(3x - 1)^{-2/3} \\cdot 3 = (3x - 1)^{-2/3}\r\n\\]\r\n', 2, '2025-08-06 15:37:06', '2025-08-06 15:37:06'),
(1100, 397, '\r\n\\[\r\n\\boxed{\\text{PASO 3: Derivada de f\'(x)}}\r\n\\]\r\n\\[\r\nf\'\'(x) = -\\frac{2}{3}(3x - 1)^{-5/3} \\cdot 3 = -2(3x - 1)^{-5/3}\r\n\\]\r\n', 3, '2025-08-06 15:37:06', '2025-08-06 15:37:06'),
(1101, 397, '\r\n\\[\r\n\\boxed{\\text{PASO 4: Resultado final}}\r\n\\]\r\n\\[\r\nf\'\'(x) = -2(3x - 1)^{-5/3}\r\n\\]\r\n', 4, '2025-08-06 15:37:06', '2025-08-06 15:37:06'),
(1102, 386, '\\[ \\boxed{\\text{PASO 1: ANALIZAMOS EL PUNTO x = 2}} \\]  La función dada es: \\[ f(x) = x^3 - 3x^2 - x + 3 \\]  Evaluamos en el punto: \\[ f(2) = (2)^3 - 3(2)^2 - 2 + 3 = 8 - 12 - 2 + 3 = -3 \\]', 10, '2025-08-07 22:39:24', '2025-08-07 22:39:24'),
(1103, 386, '\\[ \\boxed{\\text{PASO 2: CALCULAMOS EL LÍMITE CUANDO x \\\\to 2}} \\]  Como la función es un polinomio, sabemos que los límites existen en todo número real. \\[ \\lim_{x \\to 2} f(x) = f(2) = -3 \\]', 20, '2025-08-07 22:39:24', '2025-08-07 22:39:24'),
(1104, 386, '\\[ \\boxed{\\text{PASO 3: COMPARAMOS f(2) Y EL LÍMITE}} \\]  Tenemos: \\[ \\lim_{x \\to 2} f(x) = -3 \\quad \\text{y} \\quad f(2) = -3 \\]', 30, '2025-08-07 22:39:24', '2025-08-07 22:39:24'),
(1105, 386, '\\[ \\boxed{\\text{CONCLUSIÓN}} \\]  Como el límite existe y es igual al valor de la función: \\[ f(x) \\text{ es continua en } x = 2 \\]', 40, '2025-08-07 22:39:24', '2025-08-07 22:39:24'),
(1106, 386, '\\[ \\boxed{\\text{PASO 4: TABULAMOS LOS VALORES}} \\]  Calculamos valores desde dos antes hasta dos después de 2:  \\[ \\begin{array}{|c|c|} \\hline x & f(x) \\\\ \\hline 0 & (0)^3 - 3(0)^2 - 0 + 3 = 3 \\\\ 1 & (1)^3 - 3(1)^2 - 1 + 3 = 0 \\\\ 2 & (2)^3 - 3(2)^2 - 2 + 3 = -3 \\\\ 3 & (3)^3 - 3(3)^2 - 3 + 3 = -6 \\\\ 4 & (4)^3 - 3(4)^2 - 4 + 3 = -5 \\\\ \\hline \\end{array} \\]', 50, '2025-08-07 22:39:24', '2025-08-07 22:39:24'),
(1107, 386, '\\[ \\boxed{\\text{La gráfica correcta es:}} \\]  <image src=\"/storage/11/Calculo_Dif02ago25/CDM2/CDM2.1/CDM2.1_1.4C.png\">', 60, '2025-08-07 22:39:24', '2025-08-07 22:39:24'),
(1123, 414, '\\[\\boxed{\\text{PASO 1: IDENTIFICAMOS LAS COORDENADAS DE LOS PUNTOS}}\\]\\\\Sean los puntos \\( C(-1, 1) \\) y \\( D(1, 2) \\), entonces:\\\\ \\[x_1 = -1,\\quad y_1 = 1,\\quad x_2 = 1,\\quad y_2 = 2\\]', 1, '2025-08-08 02:19:38', '2025-08-08 02:19:38'),
(1124, 414, '\\[\\boxed{\\text{PASO 2: ESCRIBIMOS LA FÓRMULA PARA CALCULAR LA PENDIENTE}}\\]\\\\\\[m = \\frac{y_2 - y_1}{x_2 - x_1}\\]', 2, '2025-08-08 02:19:38', '2025-08-08 02:19:38'),
(1125, 414, '\\[\\boxed{\\text{PASO 3: SUSTITUIMOS LOS VALORES EN LA FÓRMULA}}\\]\\\\\\[m = \\frac{2 - 1}{1 - (-1)} = \\frac{1}{2}\\]', 3, '2025-08-08 02:19:38', '2025-08-08 02:19:38'),
(1126, 414, '\\[\\boxed{\\text{PASO 4: ESCRIBIMOS LA FÓRMULA PARA CALCULAR EL ÁNGULO}}\\]\\\\\\[\\theta = \\tan^{-1}(m)\\]', 4, '2025-08-08 02:19:38', '2025-08-08 02:19:38'),
