(1232, 433, '\\[\\boxed{\\text{PASO 3: SUSTITUIMOS LOS VALORES EN LA FÓRMULA}}\\]\\[m = \\frac{4 - 0}{2 - 0} = \\frac{4}{2} = 2\\]', 3, '2025-08-13 20:32:34', '2025-08-13 20:32:34'),
(1233, 433, '\\[\\boxed{\\text{PASO 4: ESCRIBIMOS LA FÓRMULA PARA CALCULAR EL ÁNGULO}}\\]\\[\\theta = \\tan^{-1}(m)\\]', 4, '2025-08-13 20:32:34', '2025-08-13 20:32:34'),
(1234, 433, '\\[\\boxed{\\text{PASO 5: SUSTITUIMOS LA PENDIENTE Y CALCULAMOS EL ÁNGULO}}\\]\\[\\theta = \\tan^{-1}(2) \\approx 63.43^\\circ\\]', 5, '2025-08-13 20:32:34', '2025-08-13 20:32:34'),
(1235, 434, '\\[\\boxed{\\text{PASO 1: IDENTIFICAMOS LAS COORDENADAS DE LOS PUNTOS}}\\] Sean los puntos \\( E(0, 0) \\) y \\( D(1, 1) \\), entonces: \\[x_1 = 0,\\quad y_1 = 0,\\quad x_2 = 1,\\quad y_2 = 1\\]', 1, '2025-08-13 20:57:36', '2025-08-13 20:57:36'),
(1236, 434, '\\[\\boxed{\\text{PASO 2: ESCRIBIMOS LA FÓRMULA PARA CALCULAR LA PENDIENTE}}\\]\\[m = \\frac{y_2 - y_1}{x_2 - x_1}\\]', 2, '2025-08-13 20:57:36', '2025-08-13 20:57:36'),
(1237, 434, '\\[\\boxed{\\text{PASO 3: SUSTITUIMOS LOS VALORES EN LA FÓRMULA}}\\]\\[m = \\frac{1 - 0}{1 - 0} = \\frac{1}{1} = 1\\]', 3, '2025-08-13 20:57:36', '2025-08-13 20:57:36'),
(1238, 434, '\\[\\boxed{\\text{PASO 4: ESCRIBIMOS LA FÓRMULA PARA CALCULAR EL ÁNGULO}}\\]\\[\\theta = \\tan^{-1}(m)\\]', 4, '2025-08-13 20:57:36', '2025-08-13 20:57:36'),
(1239, 434, '\\[\\boxed{\\text{PASO 5: SUSTITUIMOS LA PENDIENTE Y CALCULAMOS EL ÁNGULO}}\\]\\[\\theta = \\tan^{-1}(1) = 45^\\circ\\]', 5, '2025-08-13 20:57:36', '2025-08-13 20:57:36'),
(1240, 435, '\\[\\boxed{\\text{PASO 1: IDENTIFICAMOS LAS COORDENADAS DE LOS PUNTOS}}\\] Ambos puntos son \\( E(0,0) \\) y \\( E(0,0) \\), por lo que: \\[x_1 = 0,\\quad y_1 = 0,\\quad x_2 = 0,\\quad y_2 = 0\\]', 1, '2025-08-13 21:01:13', '2025-08-13 21:01:13'),
(1241, 435, '\\[\\boxed{\\text{PASO 2: APLICAMOS LA FÓRMULA DE LA PENDIENTE}}\\]\\[m = \\frac{y_2 - y_1}{x_2 - x_1} = \\frac{0 - 0}{0 - 0}\\]', 2, '2025-08-13 21:01:13', '2025-08-13 21:01:13'),
(1242, 435, '\\[\\boxed{\\text{PASO 3: INTERPRETAMOS EL RESULTADO}}\\] El cálculo \\( \\frac{0}{0} \\) es indeterminado, por lo tanto la pendiente no existe.', 3, '2025-08-13 21:01:13', '2025-08-13 21:01:13'),
(1243, 435, '\\[\\boxed{\\text{PASO 4: ÁNGULO}}\\] Si la pendiente no existe, tampoco es posible calcular un ángulo de inclinación definido.', 4, '2025-08-13 21:01:13', '2025-08-13 21:01:13'),
(1256, 214, 'Paso 1: Sustituimos directamente x = 1  \\[ \\frac{x^3 - 1}{2x^2 - 5x + 3} \\bigg|_{x = 1} = \\frac{1^3 - 1}{2(1)^2 - 5(1) + 3} = \\frac{0}{0} \\]  Tenemos una indeterminación del tipo. \\[  \\frac{0}{0}. \\]', 10, '2025-08-20 15:20:45', '2025-08-20 15:20:45'),
(1257, 214, 'Paso 2: Factorizamos numerador y denominador  \\[ x^3 - 1 = (x - 1)(x^2 + x + 1) \\quad \\text{(diferencia de cubos)} \\]  \\[ 2x^2 - 5x + 3 = (2x - 3)(x - 1) \\]', 20, '2025-08-20 15:20:45', '2025-08-20 15:20:45'),
(1258, 214, 'Paso 3: Cancelamos el factor común (x - 1)  \\[ \\frac{(x - 1)(x^2 + x + 1)}{(2x - 3)(x - 1)} = \\frac{x^2 + x + 1}{2x - 3}, \\quad x \\ne 1 \\]', 30, '2025-08-20 15:20:45', '2025-08-20 15:20:45'),
(1259, 214, 'Paso 4: Sustituimos x = 1 en la expresión simplificada  \\[ \\frac{1^2 + 1 + 1}{2(1) - 3} = \\frac{3}{-1} = -3 \\]', 40, '2025-08-20 15:20:45', '2025-08-20 15:20:45'),
(1268, 171, '1. El eje \"x\" es la línea horizontal central, acostada, que va de izquierda a derecha de color negro.', 10, '2025-08-20 21:31:43', '2025-08-20 21:31:43'),
(1269, 171, '2. El eje \"y\" es la línea vertical central, parada, trazada de arriba a abajo de color negro.', 20, '2025-08-20 21:31:43', '2025-08-20 21:31:43');
INSERT INTO `problem_hints` (`id`, `problem_id`, `hint`, `sequence_id`, `created_at`, `updated_at`) VALUES
(1270, 171, '3. La función o curva es la línea de color rojo o color diferente a negro que intersecta, atraviesa o corta el eje \"x\".', 30, '2025-08-20 21:31:43', '2025-08-20 21:31:43'),
