(1399, 457, '\r\n\\[\r\n\\boxed{\\text{PASO 3: INTERPRETACIÓN}}\r\n\\]\r\nComo la función es continua en \\( x = 1 \\), el valor del límite es igual al valor de la función en ese punto:\r\n\\[\r\n\\lim_{x \\to 1} (x^2 - 8)(4x + 1) = -35\r\n\\]\r\n', 3, '2025-08-27 05:23:36', '2025-08-27 05:23:36'),
(1400, 457, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\n\\[\r\n\\lim_{x \\to 1} (x^2 - 8)(4x + 1) = -35\r\n\\]\r\n', 4, '2025-08-27 05:23:36', '2025-08-27 05:23:36'),
(1401, 458, '\r\n\\[\r\n\\boxed{\\text{PASO 1: IDENTIFICAR LA FUNCIÓN}}\r\n\\]\r\nLa expresión es un polinomio compuesto: \r\n\\( f(x) = (2x^3 - 3x)^3 \\).\r\nComo los polinomios son continuos en todos los reales:\r\n\\[\r\n\\lim_{x \\to 2} f(x) = f(2)\r\n\\]\r\n', 1, '2025-08-27 05:27:14', '2025-08-27 05:27:14'),
(1402, 458, '\r\n\\[\r\n\\boxed{\\text{PASO 2: SUSTITUCIÓN DIRECTA}}\r\n\\]\r\nSustituimos \\( x = 2 \\) directamente:\r\n\\[\r\nf(2) = (2(2)^3 - 3(2))^3 = (2(8) - 6)^3 = (16 - 6)^3 = (10)^3 = 1000\r\n\\]\r\n', 2, '2025-08-27 05:27:14', '2025-08-27 05:27:14'),
(1403, 458, '\r\n\\[\r\n\\boxed{\\text{PASO 3: INTERPRETACIÓN}}\r\n\\]\r\nDado que la función es continua en \\( x = 2 \\), el límite coincide con el valor de la función en ese punto:\r\n\\[\r\n\\lim_{x \\to 2} (2x^3 - 3x)^3 = 1000\r\n\\]\r\n', 3, '2025-08-27 05:27:14', '2025-08-27 05:27:14'),
(1404, 458, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\n\\[\r\n\\lim_{x \\to 2} (2x^3 - 3x)^3 = 1000\r\n\\]\r\n', 4, '2025-08-27 05:27:14', '2025-08-27 05:27:14'),
(1405, 459, '\r\n\\[\r\n\\boxed{\\text{PASO 1: IDENTIFICAR LA FUNCIÓN}}\r\n\\]\r\nLa expresión es un polinomio compuesto: \r\n\\( f(x) = (2x^3 - 3x)^3 \\).\r\nComo los polinomios son continuos en todos los reales:\r\n\\[\r\n\\lim_{x \\to 2} f(x) = f(2)\r\n\\]\r\n', 1, '2025-08-27 05:28:33', '2025-08-27 05:28:33'),
(1406, 459, '\r\n\\[\r\n\\boxed{\\text{PASO 2: SUSTITUCIÓN DIRECTA}}\r\n\\]\r\nSustituimos \\( x = 2 \\) directamente:\r\n\\[\r\nf(2) = (2(2)^3 - 3(2))^3 = (2(8) - 6)^3 = (16 - 6)^3 = (10)^3 = 1000\r\n\\]\r\n', 2, '2025-08-27 05:28:33', '2025-08-27 05:28:33'),
(1407, 459, '\r\n\\[\r\n\\boxed{\\text{PASO 3: INTERPRETACIÓN}}\r\n\\]\r\nDado que la función es continua en \\( x = 2 \\), el límite coincide con el valor de la función en ese punto:\r\n\\[\r\n\\lim_{x \\to 2} (2x^3 - 3x)^3 = 1000\r\n\\]\r\n', 3, '2025-08-27 05:28:33', '2025-08-27 05:28:33'),
(1408, 459, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\n\\[\r\n\\lim_{x \\to 2} (2x^3 - 3x)^3 = 1000\r\n\\]\r\n', 4, '2025-08-27 05:28:33', '2025-08-27 05:28:33'),
(1409, 461, '\r\n\\[\r\n\\boxed{\\text{PASO 1: IDENTIFICAR LA FUNCIÓN}}\r\n\\]\r\nLa expresión es un polinomio al cuadrado:\r\n\\[\r\nf(x) = (2x^2 + 2)^2\r\n\\]\r\nComo los polinomios son funciones continuas en todos los reales:\r\n\\[\r\n\\lim_{x \\to 4} f(x) = f(4)\r\n\\]\r\n', 1, '2025-08-29 14:20:03', '2025-08-29 14:20:03'),
(1410, 461, '\r\n\\[\r\n\\boxed{\\text{PASO 2: SUSTITUCIÓN DIRECTA}}\r\n\\]\r\nSustituimos directamente:\r\n\\[\r\nf(4) = (2(4^2) + 2)^2 = (2 \\cdot 16 + 2)^2 = (32 + 2)^2 = 34^2 = 1156\r\n\\]\r\n', 2, '2025-08-29 14:20:03', '2025-08-29 14:20:03'),
(1411, 461, '\r\n\\[\r\n\\boxed{\\text{PASO 3: INTERPRETACIÓN}}\r\n\\]\r\nComo la función es continua en \\( x = 4 \\), el valor del límite es simplemente el valor de la función en ese punto:\r\n\\[\r\n\\lim_{x \\to 4} (2x^2 + 2)^2 = 1156\r\n\\]\r\n', 3, '2025-08-29 14:20:03', '2025-08-29 14:20:03'),
(1412, 461, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\n\\[\r\n\\lim_{x \\to 4} (2x^2 + 2)^2 = 1156\r\n\\]\r\n', 4, '2025-08-29 14:20:03', '2025-08-29 14:20:03'),
(1413, 462, '\r\n\\[\r\n\\boxed{\\text{PASO 1: IDENTIFICAR LA FUNCIÓN}}\r\n\\]\r\nLa expresión es un polinomio al cuadrado:\r\n\\[\r\nf(x) = (2x^2 + 2)^2\r\n\\]\r\nComo los polinomios son funciones continuas en todos los reales:\r\n\\[\r\n\\lim_{x \\to 4} f(x) = f(4)\r\n\\]\r\n', 1, '2025-08-29 14:20:53', '2025-08-29 14:20:53'),
(1414, 462, '\r\n\\[\r\n\\boxed{\\text{PASO 2: SUSTITUCIÓN DIRECTA}}\r\n\\]\r\nSustituimos directamente:\r\n\\[\r\nf(4) = (2(4^2) + 2)^2 = (2 \\cdot 16 + 2)^2 = (32 + 2)^2 = 34^2 = 1156\r\n\\]\r\n', 2, '2025-08-29 14:20:53', '2025-08-29 14:20:53'),
(1415, 462, '\r\n\\[\r\n\\boxed{\\text{PASO 3: INTERPRETACIÓN}}\r\n\\]\r\nComo la función es continua en \\( x = 4 \\), el valor del límite es simplemente el valor de la función en ese punto:\r\n\\[\r\n\\lim_{x \\to 4} (2x^2 + 2)^2 = 1156\r\n\\]\r\n', 3, '2025-08-29 14:20:53', '2025-08-29 14:20:53'),
(1416, 462, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\n\\[\r\n\\lim_{x \\to 4} (2x^2 + 2)^2 = 1156\r\n\\]\r\n', 4, '2025-08-29 14:20:53', '2025-08-29 14:20:53'),
(1417, 463, '\r\n\\[\r\n\\boxed{\\text{PASO 1: IDENTIFICAR LA FUNCIÓN}}\r\n\\]\r\nLa expresión es una raíz cuadrada de un polinomio:\r\n\\[\r\nf(x) = \\sqrt{4 - x^2}\r\n\\]\r\nComo \\( f(x) \\) es continua en \\( x = 0 \\), podemos evaluar directamente:\r\n\\[\r\n\\lim_{x \\to 0} f(x) = f(0)\r\n\\]\r\n', 1, '2025-08-29 14:23:38', '2025-08-29 14:23:38'),
(1418, 463, '\r\n\\[\r\n\\boxed{\\text{PASO 2: SUSTITUCIÓN DIRECTA}}\r\n\\]\r\nSustituimos \\( x = 0 \\) directamente:\r\n\\[\r\nf(0) = \\sqrt{4 - (0)^2} = \\sqrt{4} = 2\r\n\\]\r\n', 2, '2025-08-29 14:23:38', '2025-08-29 14:23:38'),
(1419, 463, '\r\n\\[\r\n\\boxed{\\text{PASO 3: INTERPRETACIÓN}}\r\n\\]\r\nComo la función es continua en \\( x = 0 \\), el valor del límite es simplemente el valor de la función en ese punto:\r\n\\[\r\n\\lim_{x \\to 0} \\sqrt{4 - x^2} = 2\r\n\\]\r\n', 3, '2025-08-29 14:23:38', '2025-08-29 14:23:38'),
(1420, 463, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\n\\[\r\n\\lim_{x \\to 0} \\sqrt{4 - x^2} = 2\r\n\\]\r\n', 4, '2025-08-29 14:23:38', '2025-08-29 14:23:38'),
(1421, 464, '\r\n\\[\r\n\\boxed{\\text{PASO 1: IDENTIFICAR LA FUNCIÓN}}\r\n\\]\r\nLa expresión es una raíz cuadrada de un polinomio:\r\n\\[\r\nf(x) = \\sqrt{4 - x^2}\r\n\\]\r\nComo \\( f(x) \\) es continua en \\( x = 0 \\), podemos evaluar directamente:\r\n\\[\r\n\\lim_{x \\to 0} f(x) = f(0)\r\n\\]\r\n', 1, '2025-08-29 14:24:33', '2025-08-29 14:24:33'),
(1422, 464, '\r\n\\[\r\n\\boxed{\\text{PASO 2: SUSTITUCIÓN DIRECTA}}\r\n\\]\r\nSustituimos \\( x = 0 \\) directamente:\r\n\\[\r\nf(0) = \\sqrt{4 - (0)^2} = \\sqrt{4} = 2\r\n\\]\r\n', 2, '2025-08-29 14:24:33', '2025-08-29 14:24:33'),
(1423, 464, '\r\n\\[\r\n\\boxed{\\text{PASO 3: INTERPRETACIÓN}}\r\n\\]\r\nComo la función es continua en \\( x = 0 \\), el valor del límite es simplemente el valor de la función en ese punto:\r\n\\[\r\n\\lim_{x \\to 0} \\sqrt{4 - x^2} = 2\r\n\\]\r\n', 3, '2025-08-29 14:24:33', '2025-08-29 14:24:33'),
(1424, 464, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\n\\[\r\n\\lim_{x \\to 0} \\sqrt{4 - x^2} = 2\r\n\\]\r\n', 4, '2025-08-29 14:24:33', '2025-08-29 14:24:33'),
(1425, 465, '\r\n\\[\r\n\\boxed{\\text{PASO 1: IDENTIFICAR LA FUNCIÓN}}\r\n\\]\r\nLa expresión es un cociente de polinomios:\r\n\\[\r\nf(x) = \\frac{x^2 + 3x - 1}{2x - 4}\r\n\\]\r\nLa función está definida en todos los reales excepto donde el denominador es cero, es decir, \\( x \\neq 2 \\).\r\nComo \\( x = 1 \\) no anula el denominador, podemos aplicar sustitución directa.\r\n', 1, '2025-08-29 14:48:14', '2025-08-29 14:48:14'),
(1426, 465, '\r\n\\[\r\n\\boxed{\\text{PASO 2: SUSTITUCIÓN DIRECTA}}\r\n\\]\r\nEvaluamos en \\( x = 1 \\):\r\n\\[\r\nf(1) = \\frac{(1)^2 + 3(1) - 1}{2(1) - 4}\r\n= \\frac{1 + 3 - 1}{2 - 4}\r\n= \\frac{3}{-2}\r\n= -1.5\r\n\\]\r\n', 2, '2025-08-29 14:48:14', '2025-08-29 14:48:14'),
(1427, 465, '\r\n\\[\r\n\\boxed{\\text{PASO 3: INTERPRETACIÓN}}\r\n\\]\r\nComo el denominador no es cero en \\( x = 1 \\), la función es continua en ese punto, por lo tanto:\r\n\\[\r\n\\lim_{x \\to 1} \\frac{x^2 + 3x - 1}{2x - 4} = f(1)\r\n\\]\r\n', 3, '2025-08-29 14:48:14', '2025-08-29 14:48:14'),
(1428, 465, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\n\\[\r\n\\lim_{x \\to 1} \\frac{x^2 + 3x - 1}{2x - 4} = -1.5\r\n\\]\r\n', 4, '2025-08-29 14:48:14', '2025-08-29 14:48:14'),
(1429, 466, '\r\n\\[\r\n\\boxed{\\text{PASO 1: IDENTIFICAR LA FUNCIÓN}}\r\n\\]\r\nLa expresión es un cociente de polinomios:\r\n\\[\r\nf(x) = \\frac{x^2 + 3x - 1}{2x - 4}\r\n\\]\r\nLa función está definida en todos los reales excepto donde el denominador es cero, es decir, \\( x \\neq 2 \\).\r\nComo \\( x = 1 \\) no anula el denominador, podemos aplicar sustitución directa.\r\n', 1, '2025-08-29 14:49:22', '2025-08-29 14:49:22'),
(1430, 466, '\r\n\\[\r\n\\boxed{\\text{PASO 2: SUSTITUCIÓN DIRECTA}}\r\n\\]\r\nEvaluamos en \\( x = 1 \\):\r\n\\[\r\nf(1) = \\frac{(1)^2 + 3(1) - 1}{2(1) - 4}\r\n= \\frac{1 + 3 - 1}{2 - 4}\r\n= \\frac{3}{-2}\r\n= -1.5\r\n\\]\r\n', 2, '2025-08-29 14:49:22', '2025-08-29 14:49:22'),
(1431, 466, '\r\n\\[\r\n\\boxed{\\text{PASO 3: INTERPRETACIÓN}}\r\n\\]\r\nComo el denominador no es cero en \\( x = 1 \\), la función es continua en ese punto, por lo tanto:\r\n\\[\r\n\\lim_{x \\to 1} \\frac{x^2 + 3x - 1}{2x - 4} = f(1)\r\n\\]\r\n', 3, '2025-08-29 14:49:22', '2025-08-29 14:49:22'),
(1432, 466, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\n\\[\r\n\\lim_{x \\to 1} \\frac{x^2 + 3x - 1}{2x - 4} = -1.5\r\n\\]\r\n', 4, '2025-08-29 14:49:22', '2025-08-29 14:49:22'),
(1437, 468, '\r\n\\[\r\n\\boxed{\\text{PASO 1: IDENTIFICAR LA FUNCIÓN}}\r\n\\]\r\nLa expresión es un cociente de polinomios:\r\n\\[\r\nf(x) = \\frac{x^3 - 2x^2 + x - 5}{4x + 7}\r\n\\]\r\nLa función está definida para todo número real excepto donde el denominador se anule.\r\nEn este caso, \\(4x+7=0\\) cuando \\(x=-\\tfrac{7}{4}\\).\r\nComo evaluamos en \\(x=1\\), la función es continua y podemos aplicar sustitución directa.\r\n', 1, '2025-08-29 15:09:14', '2025-08-29 15:09:14'),
(1438, 468, '\r\n\\[\r\n\\boxed{\\text{PASO 2: SUSTITUCIÓN DIRECTA}}\r\n\\]\r\nSustituyendo \\( x = 1 \\):\r\n\\[\r\nf(1) = \\frac{1^3 - 2(1)^2 + 1 - 5}{4(1) + 7}\r\n= \\frac{1 - 2 + 1 - 5}{11}\r\n= \\frac{-5}{11}\r\n\\]\r\n', 2, '2025-08-29 15:09:14', '2025-08-29 15:09:14'),
(1439, 468, '\r\n\\[\r\n\\boxed{\\text{PASO 3: CONVERSIÓN A DECIMAL}}\r\n\\]\r\nDividimos:\r\n\\[\r\n\\frac{-5}{11} = -0.454545... \\approx -0.455\r\n\\]\r\nUsamos tres decimales como se indica.\r\n', 3, '2025-08-29 15:09:14', '2025-08-29 15:09:14'),
(1440, 468, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\n\\[\r\n\\lim_{x \\to 1} \\frac{x^3 - 2x^2 + x - 5}{4x + 7} = -0.455\r\n\\]\r\n', 4, '2025-08-29 15:09:14', '2025-08-29 15:09:14'),
(1441, 469, '\r\n\\[\r\n\\boxed{\\text{PASO 1: IDENTIFICAR LA FUNCIÓN}}\r\n\\]\r\nLa expresión es un cociente de polinomios:\r\n\\[\r\nf(x) = \\frac{x^3 - 2x^2 + x - 5}{4x + 7}\r\n\\]\r\nLa función está definida para todo número real excepto donde el denominador se anule.\r\nEn este caso, \\(4x+7=0\\) cuando \\(x=-\\tfrac{7}{4}\\).\r\nComo evaluamos en \\(x=1\\), la función es continua y podemos aplicar sustitución directa.\r\n', 1, '2025-08-29 15:10:03', '2025-08-29 15:10:03'),
(1442, 469, '\r\n\\[\r\n\\boxed{\\text{PASO 2: SUSTITUCIÓN DIRECTA}}\r\n\\]\r\nSustituyendo \\( x = 1 \\):\r\n\\[\r\nf(1) = \\frac{1^3 - 2(1)^2 + 1 - 5}{4(1) + 7}\r\n= \\frac{1 - 2 + 1 - 5}{11}\r\n= \\frac{-5}{11}\r\n\\]\r\n', 2, '2025-08-29 15:10:03', '2025-08-29 15:10:03'),
(1443, 469, '\r\n\\[\r\n\\boxed{\\text{PASO 3: CONVERSIÓN A DECIMAL}}\r\n\\]\r\nDividimos:\r\n\\[\r\n\\frac{-5}{11} = -0.454545... \\approx -0.455\r\n\\]\r\nUsamos tres decimales como se indica.\r\n', 3, '2025-08-29 15:10:03', '2025-08-29 15:10:03'),
(1444, 469, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\n\\[\r\n\\lim_{x \\to 1} \\frac{x^3 - 2x^2 + x - 5}{4x + 7} = -0.455\r\n\\]\r\n', 4, '2025-08-29 15:10:03', '2025-08-29 15:10:03'),
(1445, 470, '\r\n\\[\r\n\\boxed{\\text{PASO 1: IDENTIFICAR LA FUNCIÓN}}\r\n\\]\r\nLa expresión es un cociente de polinomios:\r\n\\[\r\nf(x) = \\frac{x^2 + 3x - 4}{x - 2}\r\n\\]\r\nEl denominador se anula en \\(x=2\\), pero como evaluamos en \\(x=1\\), la función es continua en ese punto y se puede aplicar sustitución directa.\r\n', 1, '2025-08-29 15:43:09', '2025-08-29 15:43:09'),
(1446, 470, '\r\n\\[\r\n\\boxed{\\text{PASO 2: SUSTITUCIÓN DIRECTA}}\r\n\\]\r\nSustituimos \\( x = 1 \\) en la función:\r\n\\[\r\nf(1) = \\frac{1^2 + 3(1) - 4}{1 - 2} = \\frac{1 + 3 - 4}{-1} = \\frac{0}{-1} = 0\r\n\\]\r\n', 2, '2025-08-29 15:43:09', '2025-08-29 15:43:09'),
(1447, 470, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\n\\[\r\n\\lim_{x \\to 1} \\frac{x^2 + 3x - 4}{x - 2} = 0\r\n\\]\r\n', 3, '2025-08-29 15:43:09', '2025-08-29 15:43:09'),
(1448, 471, '\r\n\\[\r\n\\boxed{\\text{PASO 1: IDENTIFICAR LA FUNCIÓN}}\r\n\\]\r\nLa expresión es un cociente de polinomios:\r\n\\[\r\nf(x) = \\frac{x^2 + 3x - 4}{x - 2}\r\n\\]\r\nEl denominador se anula en \\(x=2\\), pero como evaluamos en \\(x=1\\), la función es continua en ese punto y se puede aplicar sustitución directa.\r\n', 1, '2025-08-29 15:43:42', '2025-08-29 15:43:42'),
(1449, 471, '\r\n\\[\r\n\\boxed{\\text{PASO 2: SUSTITUCIÓN DIRECTA}}\r\n\\]\r\nSustituimos \\( x = 1 \\) en la función:\r\n\\[\r\nf(1) = \\frac{1^2 + 3(1) - 4}{1 - 2} = \\frac{1 + 3 - 4}{-1} = \\frac{0}{-1} = 0\r\n\\]\r\n', 2, '2025-08-29 15:43:42', '2025-08-29 15:43:42'),
(1450, 471, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\n\\[\r\n\\lim_{x \\to 1} \\frac{x^2 + 3x - 4}{x - 2} = 0\r\n\\]\r\n', 3, '2025-08-29 15:43:42', '2025-08-29 15:43:42'),
(1451, 472, '\r\n\\[\r\n\\boxed{\\text{PASO 1: IDENTIFICAR LA FUNCIÓN}}\r\n\\]\r\nLa expresión es un cociente de polinomios:\r\n\\[\r\nf(x) = \\frac{x^2 - 5x + 4}{3x + 2}\r\n\\]\r\nComo el denominador en \\(x = 1\\) no se anula, la función es continua en ese punto y se puede aplicar sustitución directa.\r\n', 1, '2025-08-29 20:10:48', '2025-08-29 20:10:48'),
(1452, 472, '\r\n\\[\r\n\\boxed{\\text{PASO 2: SUSTITUCIÓN DIRECTA}}\r\n\\]\r\nSustituimos \\( x = 1 \\) en la función:\r\n\\[\r\nf(1) = \\frac{1^2 - 5(1) + 4}{3(1) + 2} = \\frac{1 - 5 + 4}{5} = \\frac{0}{5} = 0\r\n\\]\r\n', 2, '2025-08-29 20:10:48', '2025-08-29 20:10:48'),
(1453, 472, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\n\\[\r\n\\lim_{x \\to 1} \\frac{x^2 - 5x + 4}{3x + 2} = 0\r\n\\]\r\n', 3, '2025-08-29 20:10:48', '2025-08-29 20:10:48'),
(1454, 473, '\r\n\\[\r\n\\boxed{\\text{PASO 1: IDENTIFICAR LA FUNCIÓN}}\r\n\\]\r\nLa expresión es un cociente de polinomios:\r\n\\[\r\nf(x) = \\frac{x^2 - 5x + 4}{3x + 2}\r\n\\]\r\nComo el denominador en \\(x = 1\\) no se anula, la función es continua en ese punto y se puede aplicar sustitución directa.\r\n', 1, '2025-08-29 20:11:19', '2025-08-29 20:11:19'),
(1455, 473, '\r\n\\[\r\n\\boxed{\\text{PASO 2: SUSTITUCIÓN DIRECTA}}\r\n\\]\r\nSustituimos \\( x = 1 \\) en la función:\r\n\\[\r\nf(1) = \\frac{1^2 - 5(1) + 4}{3(1) + 2} = \\frac{1 - 5 + 4}{5} = \\frac{0}{5} = 0\r\n\\]\r\n', 2, '2025-08-29 20:11:19', '2025-08-29 20:11:19'),
(1456, 473, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\n\\[\r\n\\lim_{x \\to 1} \\frac{x^2 - 5x + 4}{3x + 2} = 0\r\n\\]\r\n', 3, '2025-08-29 20:11:19', '2025-08-29 20:11:19'),
(1457, 474, '\r\n\\[\r\n\\boxed{\\text{PASO 1: IDENTIFICAR LA FUNCIÓN}}\r\n\\]\r\nLa expresión es un cociente de polinomios:\r\n\\[\r\nf(x) = \\frac{x^2 + 2x + 1}{2x - 6}\r\n\\]\r\n', 1, '2025-08-29 20:13:33', '2025-08-29 20:13:33'),
(1458, 474, '\r\n\\[\r\n\\boxed{\\text{PASO 2: VERIFICAR EL DENOMINADOR}}\r\n\\]\r\nEvaluamos el denominador en \\(x = 3\\):\r\n\\[\r\n2(3) - 6 = 0\r\n\\]\r\nAl anularse el denominador, la función no es continua en \\(x = 3\\).\r\n', 2, '2025-08-29 20:13:33', '2025-08-29 20:13:33'),
(1459, 474, '\r\n\\[\r\n\\boxed{\\text{PASO 3: SUSTITUCIÓN DIRECTA EN EL NUMERADOR}}\r\n\\]\r\nEvaluamos el numerador en \\(x = 3\\):\r\n\\[\r\n3^2 + 2(3) + 1 = 9 + 6 + 1 = 16\r\n\\]\r\nSe obtiene \\( \\tfrac{16}{0} \\), lo cual indica una indeterminación infinita.\r\n', 3, '2025-08-29 20:13:33', '2025-08-29 20:13:33'),
(1460, 474, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\nDado que el denominador se hace cero mientras el numerador es distinto de cero:\r\n\\[\r\n\\lim_{x \\to 3} \\frac{x^2 + 2x + 1}{2x - 6} \\; \\text{no existe (}\\to \\infty\\text{).}\r\n\\]\r\nPor lo tanto, conforme a la instrucción:\r\n\\[\r\n\\text{Respuesta} = 99999\r\n\\]\r\n', 4, '2025-08-29 20:13:33', '2025-08-29 20:13:33'),
(1461, 475, '\r\n\\[\r\n\\boxed{\\text{PASO 1: IDENTIFICAR LA FUNCIÓN}}\r\n\\]\r\nLa expresión es un cociente de polinomios:\r\n\\[\r\nf(x) = \\frac{x^2 + 2x + 1}{2x - 6}\r\n\\]\r\n', 1, '2025-08-29 20:14:16', '2025-08-29 20:14:16'),
(1462, 475, '\r\n\\[\r\n\\boxed{\\text{PASO 2: VERIFICAR EL DENOMINADOR}}\r\n\\]\r\nEvaluamos el denominador en \\(x = 3\\):\r\n\\[\r\n2(3) - 6 = 0\r\n\\]\r\nAl anularse el denominador, la función no es continua en \\(x = 3\\).\r\n', 2, '2025-08-29 20:14:16', '2025-08-29 20:14:16'),
(1463, 475, '\r\n\\[\r\n\\boxed{\\text{PASO 3: SUSTITUCIÓN DIRECTA EN EL NUMERADOR}}\r\n\\]\r\nEvaluamos el numerador en \\(x = 3\\):\r\n\\[\r\n3^2 + 2(3) + 1 = 9 + 6 + 1 = 16\r\n\\]\r\nSe obtiene \\( \\tfrac{16}{0} \\), lo cual indica una indeterminación infinita.\r\n', 3, '2025-08-29 20:14:16', '2025-08-29 20:14:16'),
(1464, 475, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\nDado que el denominador se hace cero mientras el numerador es distinto de cero:\r\n\\[\r\n\\lim_{x \\to 3} \\frac{x^2 + 2x + 1}{2x - 6} \\; \\text{no existe (}\\to \\infty\\text{).}\r\n\\]\r\nPor lo tanto, conforme a la instrucción:\r\n\\[\r\n\\text{Respuesta} = 99999\r\n\\]\r\n', 4, '2025-08-29 20:14:16', '2025-08-29 20:14:16'),
(1465, 476, '\r\n\\[\r\n\\boxed{\\text{PASO 1: IDENTIFICAR LA FUNCIÓN}}\r\n\\]\r\nLa expresión es un cociente de polinomios:\r\n\\[\r\nf(x) = \\frac{x^2 + x + 1}{5x - 10}\r\n\\]\r\n', 1, '2025-08-29 20:20:23', '2025-08-29 20:20:23'),
(1466, 476, '\r\n\\[\r\n\\boxed{\\text{PASO 2: VERIFICAR EL DENOMINADOR}}\r\n\\]\r\nEvaluamos el denominador en \\(x = 2\\):\r\n\\[\r\n5(2) - 10 = 0\r\n\\]\r\nEsto muestra que la función no es continua en ese punto.\r\n', 2, '2025-08-29 20:20:23', '2025-08-29 20:20:23'),
(1467, 476, '\r\n\\[\r\n\\boxed{\\text{PASO 3: EVALUAR EL NUMERADOR}}\r\n\\]\r\nSustituimos \\(x = 2\\) en el numerador:\r\n\\[\r\n2^2 + 2 + 1 = 7\r\n\\]\r\nObtenemos \\(\\tfrac{7}{0}\\), lo que indica una indeterminación infinita.\r\n', 3, '2025-08-29 20:20:23', '2025-08-29 20:20:23'),
(1468, 476, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\nEl numerador es distinto de cero y el denominador se hace cero en \\(x = 2\\):\r\n\\[\r\n\\lim_{x \\to 2} \\frac{x^2 + x + 1}{5x - 10} \\; \\text{no existe (}\\to \\infty\\text{).}\r\n\\]\r\nDe acuerdo a la instrucción:\r\n\\[\r\n\\text{Respuesta} = 99999\r\n\\]\r\n', 4, '2025-08-29 20:20:23', '2025-08-29 20:20:23'),
(1469, 477, '\r\n\\[\r\n\\boxed{\\text{PASO 1: IDENTIFICAR LA FUNCIÓN}}\r\n\\]\r\nLa expresión es un cociente de polinomios:\r\n\\[\r\nf(x) = \\frac{x^2 + x + 1}{5x - 10}\r\n\\]\r\n', 1, '2025-08-29 20:21:08', '2025-08-29 20:21:08'),
(1470, 477, '\r\n\\[\r\n\\boxed{\\text{PASO 2: VERIFICAR EL DENOMINADOR}}\r\n\\]\r\nEvaluamos el denominador en \\(x = 2\\):\r\n\\[\r\n5(2) - 10 = 0\r\n\\]\r\nEsto muestra que la función no es continua en ese punto.\r\n', 2, '2025-08-29 20:21:08', '2025-08-29 20:21:08'),
(1471, 477, '\r\n\\[\r\n\\boxed{\\text{PASO 3: EVALUAR EL NUMERADOR}}\r\n\\]\r\nSustituimos \\(x = 2\\) en el numerador:\r\n\\[\r\n2^2 + 2 + 1 = 7\r\n\\]\r\nObtenemos \\(\\tfrac{7}{0}\\), lo que indica una indeterminación infinita.\r\n', 3, '2025-08-29 20:21:08', '2025-08-29 20:21:08'),
(1472, 477, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\nEl numerador es distinto de cero y el denominador se hace cero en \\(x = 2\\):\r\n\\[\r\n\\lim_{x \\to 2} \\frac{x^2 + x + 1}{5x - 10} \\; \\text{no existe (}\\to \\infty\\text{).}\r\n\\]\r\nDe acuerdo a la instrucción:\r\n\\[\r\n\\text{Respuesta} = 99999\r\n\\]\r\n', 4, '2025-08-29 20:21:08', '2025-08-29 20:21:08'),
(1473, 478, '\r\n\\[\r\n\\boxed{\\text{PASO 1: FACTORIZAR}}\r\n\\]\r\nEl numerador y denominador se pueden factorizar:\r\n\\[\r\nx^2 - 4 = (x-2)(x+2), \\quad x^2 + 3x + 2 = (x+1)(x+2)\r\n\\]\r\n', 1, '2025-08-29 20:26:15', '2025-08-29 20:26:15'),
(1474, 478, '\r\n\\[\r\n\\boxed{\\text{PASO 2: SIMPLIFICAR}}\r\n\\]\r\nCancelamos el factor \\((x+2)\\) (válido siempre que \\(x \\neq -2\\)):\r\n\\[\r\n\\frac{(x-2)(x+2)}{(x+1)(x+2)} = \\frac{x-2}{x+1}\r\n\\]\r\n', 2, '2025-08-29 20:26:15', '2025-08-29 20:26:15'),
(1475, 478, '\r\n\\[\r\n\\boxed{\\text{PASO 3: SUSTITUCIÓN DIRECTA}}\r\n\\]\r\nEvaluamos en \\(x = -2\\):\r\n\\[\r\n\\frac{-2 - 2}{-2 + 1} = \\frac{-4}{-1} = 4\r\n\\]\r\n', 3, '2025-08-29 20:26:15', '2025-08-29 20:26:15'),
(1476, 478, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\n\\[\r\n\\lim_{x \\to -2} \\frac{x^2 - 4}{x^2 + 3x + 2} = 4\r\n\\]\r\n', 4, '2025-08-29 20:26:15', '2025-08-29 20:26:15'),
(1477, 479, '\r\n\\[\r\n\\boxed{\\text{PASO 1: FACTORIZAR}}\r\n\\]\r\nEl numerador y denominador se pueden factorizar:\r\n\\[\r\nx^2 - 4 = (x-2)(x+2), \\quad x^2 + 3x + 2 = (x+1)(x+2)\r\n\\]\r\n', 1, '2025-08-29 20:26:48', '2025-08-29 20:26:48'),
(1478, 479, '\r\n\\[\r\n\\boxed{\\text{PASO 2: SIMPLIFICAR}}\r\n\\]\r\nCancelamos el factor \\((x+2)\\) (válido siempre que \\(x \\neq -2\\)):\r\n\\[\r\n\\frac{(x-2)(x+2)}{(x+1)(x+2)} = \\frac{x-2}{x+1}\r\n\\]\r\n', 2, '2025-08-29 20:26:48', '2025-08-29 20:26:48'),
(1479, 479, '\r\n\\[\r\n\\boxed{\\text{PASO 3: SUSTITUCIÓN DIRECTA}}\r\n\\]\r\nEvaluamos en \\(x = -2\\):\r\n\\[\r\n\\frac{-2 - 2}{-2 + 1} = \\frac{-4}{-1} = 4\r\n\\]\r\n', 3, '2025-08-29 20:26:48', '2025-08-29 20:26:48'),
(1480, 479, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\n\\[\r\n\\lim_{x \\to -2} \\frac{x^2 - 4}{x^2 + 3x + 2} = 4\r\n\\]\r\n', 4, '2025-08-29 20:26:48', '2025-08-29 20:26:48'),
(1481, 480, '\r\n\\[\r\n\\boxed{\\text{PASO 1: FACTORIZAR}}\r\n\\]\r\nFactorizamos numerador y denominador:\r\n\\[\r\nx^2 - 9 = (x-3)(x+3), \\quad x^2 + 5x + 6 = (x+2)(x+3)\r\n\\]\r\n', 1, '2025-08-29 20:46:55', '2025-08-29 20:46:55'),
(1482, 480, '\r\n\\[\r\n\\boxed{\\text{PASO 2: SIMPLIFICAR}}\r\n\\]\r\nCancelamos el factor común \\((x+3)\\) (válido si \\(x \\neq -3\\)):\r\n\\[\r\n\\frac{(x-3)(x+3)}{(x+2)(x+3)} = \\frac{x-3}{x+2}\r\n\\]\r\n', 2, '2025-08-29 20:46:55', '2025-08-29 20:46:55'),
(1483, 480, '\r\n\\[\r\n\\boxed{\\text{PASO 3: SUSTITUCIÓN DIRECTA}}\r\n\\]\r\nEvaluamos en \\(x = -3\\):\r\n\\[\r\n\\frac{-3 - 3}{-3 + 2} = \\frac{-6}{-1} = 6\r\n\\]\r\n', 3, '2025-08-29 20:46:55', '2025-08-29 20:46:55'),
(1484, 480, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\n\\[\r\n\\lim_{x \\to -3} \\frac{x^2 - 9}{x^2 + 5x + 6} = 6\r\n\\]\r\n', 4, '2025-08-29 20:46:55', '2025-08-29 20:46:55'),
(1485, 481, '\r\n\\[\r\n\\boxed{\\text{PASO 1: FACTORIZAR}}\r\n\\]\r\nFactorizamos numerador y denominador:\r\n\\[\r\nx^2 - 9 = (x-3)(x+3), \\quad x^2 + 5x + 6 = (x+2)(x+3)\r\n\\]\r\n', 1, '2025-08-29 20:47:35', '2025-08-29 20:47:35'),
(1486, 481, '\r\n\\[\r\n\\boxed{\\text{PASO 2: SIMPLIFICAR}}\r\n\\]\r\nCancelamos el factor común \\((x+3)\\) (válido si \\(x \\neq -3\\)):\r\n\\[\r\n\\frac{(x-3)(x+3)}{(x+2)(x+3)} = \\frac{x-3}{x+2}\r\n\\]\r\n', 2, '2025-08-29 20:47:35', '2025-08-29 20:47:35'),
(1487, 481, '\r\n\\[\r\n\\boxed{\\text{PASO 3: SUSTITUCIÓN DIRECTA}}\r\n\\]\r\nEvaluamos en \\(x = -3\\):\r\n\\[\r\n\\frac{-3 - 3}{-3 + 2} = \\frac{-6}{-1} = 6\r\n\\]\r\n', 3, '2025-08-29 20:47:35', '2025-08-29 20:47:35'),
(1488, 481, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\n\\[\r\n\\lim_{x \\to -3} \\frac{x^2 - 9}{x^2 + 5x + 6} = 6\r\n\\]\r\n', 4, '2025-08-29 20:47:35', '2025-08-29 20:47:35'),
(1489, 482, '\r\n\\[\r\n\\boxed{\\text{PASO 1: FACTORIZAR}}\r\n\\]\r\nFactorizamos numerador y denominador:\r\n\\[\r\nx^2 + 6x + 9 = (x+3)^2, \\quad x^2 + 7x + 12 = (x+3)(x+4)\r\n\\]\r\n', 1, '2025-08-29 20:51:30', '2025-08-29 20:51:30'),
(1490, 482, '\r\n\\[\r\n\\boxed{\\text{PASO 2: SIMPLIFICAR}}\r\n\\]\r\nCancelamos el factor común \\((x+3)\\) (válido si \\(x \\neq -3\\)):\r\n\\[\r\n\\frac{(x+3)^2}{(x+3)(x+4)} = \\frac{x+3}{x+4}\r\n\\]\r\n', 2, '2025-08-29 20:51:30', '2025-08-29 20:51:30'),
(1491, 482, '\r\n\\[\r\n\\boxed{\\text{PASO 3: SUSTITUCIÓN DIRECTA}}\r\n\\]\r\nEvaluamos en \\(x = -3\\):\r\n\\[\r\n\\frac{-3+3}{-3+4} = \\frac{0}{1} = 0\r\n\\]\r\n', 3, '2025-08-29 20:51:30', '2025-08-29 20:51:30'),
(1492, 482, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\n\\[\r\n\\lim_{x \\to -3} \\frac{x^2 + 6x + 9}{x^2 + 7x + 12} = 0\r\n\\]\r\n', 4, '2025-08-29 20:51:30', '2025-08-29 20:51:30'),
(1493, 483, '\r\n\\[\r\n\\boxed{\\text{PASO 1: FACTORIZAR}}\r\n\\]\r\nFactorizamos numerador y denominador:\r\n\\[\r\nx^2 + 6x + 9 = (x+3)^2, \\quad x^2 + 7x + 12 = (x+3)(x+4)\r\n\\]\r\n', 1, '2025-08-29 20:52:24', '2025-08-29 20:52:24'),
(1494, 483, '\r\n\\[\r\n\\boxed{\\text{PASO 2: SIMPLIFICAR}}\r\n\\]\r\nCancelamos el factor común \\((x+3)\\) (válido si \\(x \\neq -3\\)):\r\n\\[\r\n\\frac{(x+3)^2}{(x+3)(x+4)} = \\frac{x+3}{x+4}\r\n\\]\r\n', 2, '2025-08-29 20:52:24', '2025-08-29 20:52:24'),
(1495, 483, '\r\n\\[\r\n\\boxed{\\text{PASO 3: SUSTITUCIÓN DIRECTA}}\r\n\\]\r\nEvaluamos en \\(x = -3\\):\r\n\\[\r\n\\frac{-3+3}{-3+4} = \\frac{0}{1} = 0\r\n\\]\r\n', 3, '2025-08-29 20:52:24', '2025-08-29 20:52:24'),
(1496, 483, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\n\\[\r\n\\lim_{x \\to -3} \\frac{x^2 + 6x + 9}{x^2 + 7x + 12} = 0\r\n\\]\r\n', 4, '2025-08-29 20:52:24', '2025-08-29 20:52:24'),
(1497, 484, '\r\n\\[\r\n\\boxed{\\text{PASO 1: FACTORIZAR}}\r\n\\]\r\nFactorizamos numerador y denominador:\r\n\\[\r\nx^2 + 4x + 4 = (x+2)^2, \\quad x^2 + 8x + 12 = (x+2)(x+6)\r\n\\]\r\n', 1, '2025-08-29 21:00:11', '2025-08-29 21:00:11'),
(1498, 484, '\r\n\\[\r\n\\boxed{\\text{PASO 2: SIMPLIFICAR}}\r\n\\]\r\nCancelamos el factor común \\((x+2)\\) (válido si \\(x \\neq -2\\)):\r\n\\[\r\n\\frac{(x+2)^2}{(x+2)(x+6)} = \\frac{x+2}{x+6}\r\n\\]\r\n', 2, '2025-08-29 21:00:11', '2025-08-29 21:00:11'),
(1499, 484, '\r\n\\[\r\n\\boxed{\\text{PASO 3: SUSTITUCIÓN DIRECTA}}\r\n\\]\r\nEvaluamos en \\(x = -2\\):\r\n\\[\r\n\\frac{-2+2}{-2+6} = \\frac{0}{4} = 0\r\n\\]\r\n', 3, '2025-08-29 21:00:11', '2025-08-29 21:00:11'),
(1500, 484, '\r\n\\[\r\n\\boxed{\\text{RESULTADO FINAL}}\r\n\\]\r\n\\[\r\n\\lim_{x \\to -2} \\frac{x^2 + 4x + 4}{x^2 + 8x + 12} = 0\r\n\\]\r\n', 4, '2025-08-29 21:00:11', '2025-08-29 21:00:11'),
