(1502, 485, '\r\n\\[\r\n\\boxed{\\text{PASO 2: SIMPLIFICAR}}\r\n\\]\r\nCancelamos el factor común \\((x+2)\\) (válido si \\(x \\neq -2\\)):\r\n\\[\r\n\\frac{(x+2)^2}{(x+2)(x+6)} = \\frac{x+2}{x+6}\r\n\\]\r\n', 2, '2025-08-29 21:00:41', '2025-08-29 21:00:41'),
